  reporter_id uuid not null,
  reported_user_id uuid,
  listing_id uuid,
  booking_id uuid,
  category text not null,
  details text,
  status text default 'open'::text not null,
  resolution_note text,
  created_at timestamp with time zone default now() not null,
  resolved_at timestamp with time zone,
  resolved_by uuid
);
do $c$ begin if not exists (select 1 from pg_constraint where conname='reports_pkey' and conrelid='public.reports'::regclass) then
  alter table public.reports add constraint reports_pkey PRIMARY KEY (id); end if; end $c$;
do $c$ begin if not exists (select 1 from pg_constraint where conname='reports_category_check' and conrelid='public.reports'::regclass) then
  alter table public.reports add constraint reports_category_check CHECK ((category = ANY (ARRAY['safety'::text, 'fraud'::text, 'inappropriate'::text, 'listing_issue'::text, 'other'::text]))); end if; end $c$;
do $c$ begin if not exists (select 1 from pg_constraint where conname='reports_status_check' and conrelid='public.reports'::regclass) then
  alter table public.reports add constraint reports_status_check CHECK ((status = ANY (ARRAY['open'::text, 'reviewing'::text, 'resolved'::text, 'dismissed'::text]))); end if; end $c$;
create table if not exists public.reviews (
  id uuid default gen_random_uuid() not null,
  booking_id uuid not null,
  listing_id uuid,
  reviewer_id uuid not null,
  reviewer_name text not null,
  reviewer_avatar_url text,
  reviewee_id uuid not null,
  review_type review_type not null,
  overall_rating numeric(2,1) not null,
  cleanliness_rating numeric(2,1),
  accuracy_rating numeric(2,1),
  communication_rating numeric(2,1),
  location_rating numeric(2,1),
  value_rating numeric(2,1),
  comment text,
  is_revealed boolean default false not null,
  revealed_at timestamp with time zone,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  updated_at timestamp with time zone default timezone('utc'::text, now()) not null
);
do $c$ begin if not exists (select 1 from pg_constraint where conname='reviews_pkey' and conrelid='public.reviews'::regclass) then
  alter table public.reviews add constraint reviews_pkey PRIMARY KEY (id); end if; end $c$;
do $c$ begin if not exists (select 1 from pg_constraint where conname='review_categories_for_guest' and conrelid='public.reviews'::regclass) then
  alter table public.reviews add constraint review_categories_for_guest CHECK (((review_type = 'host_to_guest'::review_type) OR ((review_type = 'guest_to_host'::review_type) AND (cleanliness_rating IS NOT NULL) AND (accuracy_rating IS NOT NULL) AND (communication_rating IS NOT NULL) AND (location_rating IS NOT NULL) AND (value_rating IS NOT NULL)))); end if; end $c$;
do $c$ begin if not exists (select 1 from pg_constraint where conname='reviews_accuracy_rating_check' and conrelid='public.reviews'::regclass) then
  alter table public.reviews add constraint reviews_accuracy_rating_check CHECK (((accuracy_rating >= (1)::numeric) AND (accuracy_rating <= (5)::numeric))); end if; end $c$;
do $c$ begin if not exists (select 1 from pg_constraint where conname='reviews_cleanliness_rating_check' and conrelid='public.reviews'::regclass) then
  alter table public.reviews add constraint reviews_cleanliness_rating_check CHECK (((cleanliness_rating >= (1)::numeric) AND (cleanliness_rating <= (5)::numeric))); end if; end $c$;
do $c$ begin if not exists (select 1 from pg_constraint where conname='reviews_communication_rating_check' and conrelid='public.reviews'::regclass) then
  alter table public.reviews add constraint reviews_communication_rating_check CHECK (((communication_rating >= (1)::numeric) AND (communication_rating <= (5)::numeric))); end if; end $c$;
do $c$ begin if not exists (select 1 from pg_constraint where conname='reviews_location_rating_check' and conrelid='public.reviews'::regclass) then
  alter table public.reviews add constraint reviews_location_rating_check CHECK (((location_rating >= (1)::numeric) AND (location_rating <= (5)::numeric))); end if; end $c$;
do $c$ begin if not exists (select 1 from pg_constraint where conname='reviews_overall_rating_check' and conrelid='public.reviews'::regclass) then
  alter table public.reviews add constraint reviews_overall_rating_check CHECK (((overall_rating >= (1)::numeric) AND (overall_rating <= (5)::numeric))); end if; end $c$;
do $c$ begin if not exists (select 1 from pg_constraint where conname='reviews_value_rating_check' and conrelid='public.reviews'::regclass) then
  alter table public.reviews add constraint reviews_value_rating_check CHECK (((value_rating >= (1)::numeric) AND (value_rating <= (5)::numeric))); end if; end $c$;
