create table if not exists public.sms_campaigns (
  id uuid default gen_random_uuid() not null,
  title text not null,
  body text not null,
  kind text default 'promotional'::text not null,
  status text default 'draft'::text not null,
  audience jsonb default '{}'::jsonb not null,
  created_by uuid,
  total_recipients integer default 0 not null,
  sent_count integer default 0 not null,
  failed_count integer default 0 not null,
  encoding text default 'gsm7'::text not null,
  segments_each integer default 1 not null,
  created_at timestamp with time zone default now() not null,
  started_at timestamp with time zone,
  finished_at timestamp with time zone,
  error text
);
do $c$ begin if not exists (select 1 from pg_constraint where conname='sms_campaigns_pkey' and conrelid='public.sms_campaigns'::regclass) then
