do $c$ begin if not exists (select 1 from pg_constraint where conname='sms_campaigns_status_check' and conrelid='public.sms_campaigns'::regclass) then
  alter table public.sms_campaigns add constraint sms_campaigns_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'queued'::text, 'sending'::text, 'sent'::text, 'cancelled'::text, 'failed'::text]))); end if; end $c$;
create table if not exists public.sms_recipients (
