CREATE OR REPLACE FUNCTION public._localize_date_bn(d text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT replace(replace(replace(replace(replace(replace(replace(
           replace(replace(replace(replace(replace(replace(replace(
           replace(replace(replace(replace(replace($1,
           'January', 'জানুয়ারি'), 'February', 'ফেব্রুয়ারি'),
           'March', 'মার্চ'), 'April', 'এপ্রিল'), 'May', 'মে'),
           'June', 'জুন'), 'July', 'জুলাই'), 'August', 'আগস্ট'),
           'September', 'সেপ্টেম্বর'), 'October', 'অক্টোবর'),
           'November', 'নভেম্বর'), 'December', 'ডিসেম্বর'),
           'Sunday', 'রবিবার'), 'Monday', 'সোমবার'), 'Tuesday', 'মঙ্গলবার'),
           'Wednesday', 'বুধবার'), 'Thursday', 'বৃহস্পতিবার'),
           'Friday', 'শুক্রবার'), 'Saturday', 'শনিবার');
$function$;

CREATE OR REPLACE FUNCTION public.add_payout_method(p_channel text, p_account_name text, p_account_number text, p_bank_name text DEFAULT NULL::text, p_branch_name text DEFAULT NULL::text, p_routing_number text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid      uuid := auth.uid();
  v_channel  public.payout_channel;
  v_number   text;
  v_enabled  text;
  v_live     int;
  v_id       uuid;
  v_is_first boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  begin
    v_channel := lower(btrim(p_channel))::public.payout_channel;
  exception when others then
    raise exception 'unknown payout channel %', p_channel using errcode = '22023';
  end;

  -- Re-check the admin's offered-channel list server-side. The app hides
  -- disabled channels, but "the client hid it" has never been a control.
  select value into v_enabled from public.app_settings
   where key = 'payout_channels_enabled';
  if v_enabled is not null
     and not (v_channel::text = any (
       select btrim(t) from unnest(string_to_array(v_enabled, ',')) t)) then
    raise exception 'the % payout channel is not currently accepted', v_channel
      using errcode = '22023';
  end if;

  if coalesce(btrim(p_account_name), '') = '' then
    raise exception 'the account holder name is required' using errcode = '22023';
  end if;

  v_number := case
    when v_channel = 'bank'
      then regexp_replace(coalesce(p_account_number, ''), '[^0-9]', '', 'g')
    else public.normalise_bd_msisdn(p_account_number)
  end;

  -- Cheap ceiling on a table an authenticated user can grow. Five is well past
  -- what anyone legitimately needs and well short of a nuisance.
  select count(*) into v_live from public.payout_methods
   where user_id = v_uid and retired_at is null;
  if v_live >= 5 then
    raise exception 'you already have the maximum of 5 payout methods — retire one first'
      using errcode = '22023';
  end if;

  if exists (
    select 1 from public.payout_methods
     where user_id = v_uid and channel = v_channel
       and account_number = v_number and retired_at is null
  ) then
    raise exception 'you have already added that account' using errcode = '23505';
  end if;

  -- The first method a user adds becomes their default, so the common case
  -- (exactly one account, ever) never needs a second decision from them.
  v_is_first := not exists (
    select 1 from public.payout_methods
     where user_id = v_uid and retired_at is null and is_default
  );

  insert into public.payout_methods (
    user_id, channel, account_name, account_number,
    bank_name, branch_name, routing_number, is_default
  ) values (
    v_uid, v_channel, btrim(p_account_name), v_number,
    case when v_channel = 'bank' then nullif(btrim(p_bank_name), '') end,
    case when v_channel = 'bank' then nullif(btrim(p_branch_name), '') end,
    case when v_channel = 'bank'
         then nullif(regexp_replace(coalesce(p_routing_number, ''), '[^0-9]', '', 'g'), '') end,
    v_is_first
  )
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_add_sms_recipients(p_campaign_id uuid, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_campaign   public.sms_campaigns;
  v_row        jsonb;
  v_phone      text;
  v_name       text;
  v_user       uuid;
  v_added      integer := 0;
  v_invalid    integer := 0;
  v_duplicate  integer := 0;
  v_suppressed integer := 0;
  v_inserted   integer;
begin
  perform public.fn_require_service_role();

  select * into v_campaign from public.sms_campaigns where id = p_campaign_id;
  if not found then
    raise exception 'No such campaign' using errcode = '22023';
  end if;
  -- Recipients may only be added while the campaign has not gone out. Adding to
  -- a sending campaign would make the total a moving target and the admin's
  -- confirmed count a lie.
  if v_campaign.status <> 'draft' then
    raise exception 'Campaign is already %, recipients cannot be changed', v_campaign.status
      using errcode = '22023';
  end if;

  for v_row in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb))
  loop
    v_phone := public.fn_canonical_bd_phone(v_row ->> 'phone');
    v_name  := nullif(trim(coalesce(v_row ->> 'name', '')), '');
    begin
      v_user := nullif(v_row ->> 'user_id', '')::uuid;
    exception when others then
      v_user := null;
    end;

    if v_phone is null then
      v_invalid := v_invalid + 1;
      continue;
    end if;

    -- A promotional campaign never reaches the suppression list. A
    -- transactional one may, and that is the only difference between them.
    if v_campaign.kind = 'promotional'
       and exists (select 1 from public.sms_suppressions s where s.phone = v_phone) then
      v_suppressed := v_suppressed + 1;
      continue;
    end if;

    insert into public.sms_recipients
      (campaign_id, phone, msisdn, user_id, name, body_rendered)
    values
      (p_campaign_id, v_phone, public.fn_msisdn(v_phone), v_user, v_name,
       public.fn_render_sms_body(v_campaign.body, v_name))
    on conflict (campaign_id, phone) do nothing;

    get diagnostics v_inserted = row_count;
    if v_inserted = 1 then
      v_added := v_added + 1;
    else
      -- The unique index caught it. This is the count that makes the four
      -- duplicated numbers on live visible instead of silently doubled.
      v_duplicate := v_duplicate + 1;
    end if;
  end loop;

  update public.sms_campaigns
     set total_recipients = (select count(*) from public.sms_recipients
                              where campaign_id = p_campaign_id)
   where id = p_campaign_id;

  return jsonb_build_object(
    'added', v_added,
    'invalid', v_invalid,
    'duplicate', v_duplicate,
    'suppressed', v_suppressed,
    'total', (select count(*) from public.sms_recipients where campaign_id = p_campaign_id)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_approve_verification(p_user_id uuid, p_document_type text, p_front_path text, p_back_path text DEFAULT NULL::text, p_face_attempt_id uuid DEFAULT NULL::uuid, p_face_evidence_version uuid DEFAULT NULL::uuid, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.profiles; identity_done boolean:=false; face_done boolean:=false;
begin
  if auth.uid() is null or not public.is_admin() or auth.uid()=p_user_id then
    raise exception 'Another admin must approve this verification' using errcode='42501'; end if;
  select * into p from public.profiles where id=p_user_id for update;
  if not found then raise exception 'Account not found'; end if;

  if p.verification_status='pending' then
    perform public.approve_identity_document(p_user_id,p_document_type,p_front_path,p_back_path);
    identity_done:=true;
  elsif not (p.verification_status='verified' and coalesce(p.nid_verified,false)) then
    raise exception 'No identity document is waiting for review. Refresh the queue';
  end if;

  if p_face_attempt_id is not null then
    if (select user_id from public.face_verification_attempts where id=p_face_attempt_id) is distinct from p_user_id then
      raise exception 'Face submission belongs to another account' using errcode='42501'; end if;
    perform public.review_face_verification(p_face_attempt_id,p_face_evidence_version,'approved',coalesce(p_note,''));
    face_done:=true;
  elsif public.face_review_required() and not coalesce((select status='approved'
      from public.face_verification_attempts where user_id=p_user_id
      order by created_at desc,id desc limit 1),false) then
    raise exception 'Face verification is required and this person has not submitted one yet';
  end if;

  if not identity_done and not face_done then
    raise exception 'Nothing is waiting for review. Refresh the queue'; end if;
  return jsonb_build_object('identity_approved',identity_done,'face_approved',face_done);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_auto_complete_bookings()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF current_setting('role') != 'service_role' THEN
        RAISE EXCEPTION 'Only service_role can execute this function';
    END IF;
    RETURN public.auto_complete_elapsed_bookings();
END;
$function$;

CREATE OR REPLACE FUNCTION public.admin_cancel_sms_campaign(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stopped integer;
begin
  perform public.fn_require_service_role();

  update public.sms_recipients
     set status = 'skipped', skip_reason = 'campaign cancelled'
   where campaign_id = p_campaign_id and status = 'pending';
  get diagnostics v_stopped = row_count;

  update public.sms_campaigns
     set status = 'cancelled', finished_at = now()
   where id = p_campaign_id and status in ('draft', 'queued', 'sending');

  return jsonb_build_object('stopped', v_stopped);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_claim_sms_batch(p_campaign_id uuid, p_limit integer DEFAULT 50)
 RETURNS TABLE(id uuid, msisdn text, body_rendered text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.fn_require_service_role();

  update public.sms_campaigns
     set status = 'sending'
   where sms_campaigns.id = p_campaign_id and status = 'queued';

  return query
  with picked as (
    select c.id
      from public.sms_recipients c
     where c.campaign_id = p_campaign_id
       and c.status = 'pending'
     order by c.created_at, c.id
     limit greatest(1, least(coalesce(p_limit, 50), 200))
     for update skip locked
  )
  update public.sms_recipients r
     set status = 'sending',
         claimed_at = now(),
         attempts = r.attempts + 1
    from picked
   where r.id = picked.id
  returning r.id, r.msisdn, r.body_rendered;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_create_sms_campaign(p_title text, p_body text, p_kind text, p_audience jsonb, p_created_by uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  perform public.fn_require_service_role();

  if coalesce(trim(p_title), '') = '' then
    raise exception 'A campaign needs a title' using errcode = '22023';
  end if;
  if coalesce(trim(p_body), '') = '' then
    raise exception 'A campaign needs a message' using errcode = '22023';
  end if;
  if p_kind not in ('promotional', 'transactional') then
    raise exception 'Invalid campaign kind: %', p_kind using errcode = '22023';
  end if;

  insert into public.sms_campaigns (title, body, kind, audience, created_by,
                                    encoding, segments_each)
  values (trim(p_title), p_body, p_kind, coalesce(p_audience, '{}'::jsonb), p_created_by,
          public.fn_sms_encoding(p_body), public.fn_sms_segments(p_body))
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_expire_bookings()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    -- Only allow service_role to execute
    IF current_setting('role') != 'service_role' THEN
        RAISE EXCEPTION 'Only service_role can execute this function';
    END IF;

    RETURN public.expire_stale_bookings();
END;
$function$;

CREATE OR REPLACE FUNCTION public.admin_mark_sms_result(p_recipient_id uuid, p_ok boolean, p_provider_status text DEFAULT NULL::text, p_provider_ref text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_campaign uuid;
begin
  perform public.fn_require_service_role();

  update public.sms_recipients
     set status = case when p_ok then 'sent' else 'failed' end,
         sent_at = case when p_ok then now() else sent_at end,
         provider_status = p_provider_status,
         provider_ref = p_provider_ref,
         error = case when p_ok then null else p_error end
   where id = p_recipient_id
     and status = 'sending'
  returning campaign_id into v_campaign;

  if v_campaign is null then
    return;
  end if;

  -- Counters are recomputed rather than incremented, so a retried or
  -- hand-corrected row cannot drift them away from the recipient rows they
  -- summarise.
  update public.sms_campaigns c
     set sent_count   = s.sent,
         failed_count = s.failed,
         status = case
                    when c.status = 'cancelled' then 'cancelled'
                    when s.outstanding = 0 and s.sent = 0 then 'failed'
                    when s.outstanding = 0 then 'sent'
                    else c.status
                  end,
         finished_at = case when s.outstanding = 0 then now() else c.finished_at end
    from (
      select count(*) filter (where status = 'sent')                 as sent,
             count(*) filter (where status = 'failed')               as failed,
             count(*) filter (where status in ('pending','sending')) as outstanding
        from public.sms_recipients where campaign_id = v_campaign
    ) s
   where c.id = v_campaign;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_notify_audience(p_filters jsonb DEFAULT '{}'::jsonb, p_type notification_type DEFAULT 'system_alert'::notification_type, p_priority notification_priority DEFAULT 'normal'::notification_priority)
 RETURNS TABLE(user_id uuid, full_name text, role text, delivers boolean, push_allowed boolean, has_token boolean, skip_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cat text := public.fn_notification_category(p_type);
  -- Bangladesh-only product, and `quiet_hours_start/end` are `time` with no
  -- zone, so there is nothing else they could sensibly mean.
  v_local time := (now() at time zone 'Asia/Dhaka')::time;
begin
  perform public.fn_require_service_role();

  return query
  with candidate as (
    select p.id,
           p.full_name,
           p.role::text as role,
           p.is_host,
           p.verification_status::text as verification_status,
           p.created_at,
           coalesce(np.global_enabled, true) as global_enabled,
           coalesce((np.category_preferences -> v_cat ->> 'enabled')::boolean, true)
             as category_enabled,
           -- Absent channels key -> app default, which includes push.
           coalesce(np.category_preferences -> v_cat -> 'channels' ? 'push', true)
             as push_channel,
           coalesce(np.quiet_hours_enabled, false) as quiet_on,
           coalesce(np.quiet_hours_allow_urgent, true) as quiet_allows_urgent,
           np.quiet_hours_start,
           np.quiet_hours_end,
           exists (select 1 from public.fcm_tokens f
                    where f.user_id = p.id and f.is_active) as has_token
      from public.profiles p
      left join public.notification_preferences np on np.user_id = p.id
  ),
  scoped as (
    select c.*,
           -- The default window is 22:00–07:00, which CROSSES MIDNIGHT — so
           -- a plain BETWEEN is wrong for exactly the case that matters and
           -- would leave the small-hours push it exists to prevent.
           (c.quiet_on and (
              case when c.quiet_hours_start <= c.quiet_hours_end
                   then v_local between c.quiet_hours_start and c.quiet_hours_end
                   else v_local >= c.quiet_hours_start or v_local <= c.quiet_hours_end
              end))
             and not (p_priority = 'urgent' and c.quiet_allows_urgent) as in_quiet_hours
      from candidate c
     where (p_filters ->> 'role' is null or c.role = p_filters ->> 'role')
       and (p_filters ->> 'is_host' is null
            or c.is_host = (p_filters ->> 'is_host')::boolean)
       and (p_filters ->> 'verification_status' is null
            or c.verification_status = p_filters ->> 'verification_status')
       and (p_filters ->> 'joined_from' is null
            or c.created_at >= (p_filters ->> 'joined_from')::timestamptz)
       and (p_filters ->> 'joined_to' is null
            or c.created_at <= (p_filters ->> 'joined_to')::timestamptz)
       and (p_filters -> 'user_ids' is null
            or c.id = any (select (jsonb_array_elements_text(p_filters -> 'user_ids'))::uuid))
  )
  select s.id,
         s.full_name,
         s.role,
         (s.global_enabled and s.category_enabled) as delivers,
         (s.global_enabled and s.category_enabled and s.push_channel
            and s.has_token and not s.in_quiet_hours) as push_allowed,
         s.has_token,
         case
           when not s.global_enabled  then 'notifications turned off'
           when not s.category_enabled then v_cat || ' notifications turned off'
           when not s.push_channel    then 'in-app only, by their choice'
           when s.in_quiet_hours      then 'quiet hours — in-app only'
           when not s.has_token       then 'no device registered — in-app only'
           else null
         end as skip_reason
    from scoped s
   order by s.full_name nulls last, s.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_register_device(p_user_id uuid, p_device_id text, p_platform text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_id uuid;
begin
  -- The guard every admin_* function in this schema carries. Without it this
  -- is a public endpoint that registers a device against any account, which
  -- under a cap is a way to sign other people out.
  if current_setting('request.jwt.claims', true)::jsonb ->> 'role'
     is distinct from 'service_role' then
    raise exception 'Only service_role can execute this function'
      using errcode = '42501';
  end if;

  if p_device_id is null or length(p_device_id) not between 8 and 128 then
    raise exception 'Invalid device id' using errcode = '22023';
  end if;

  insert into public.user_devices as d (user_id, device_id, platform)
  values (p_user_id, p_device_id, p_platform)
  on conflict (user_id, device_id) do update set
    platform = excluded.platform,
    last_seen_at = now(),
    revoked_at = null
  returning d.id into v_id;

  -- Protecting the arriving row by id, exactly as register_device does: a user
  -- must never be signed out by their own login, and `now()` is transaction
  -- time so two rows can share a last_seen_at precisely.
  return public.fn_enforce_device_limit(p_user_id, v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_reject_payment(p_payment_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payment public.payments%rowtype;
begin
  perform public.fn_require_service_role();

  select * into v_payment from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'Payment not found' using errcode = 'P0002';
  end if;
  if v_payment.status <> 'pending_review' then
    raise exception 'Only a payment held for review can be rejected (status is %)',
      v_payment.status using errcode = '22023';
  end if;

  -- `failed` rather than a new `rejected`: from the guest's and the host's
  -- point of view this payment did not happen, and every screen that already
  -- knows how to render a failed attempt renders this one correctly. The
  -- reason is kept in the gateway blob, which is where the risk fields
  -- that caused the hold already live.
  update public.payments
     set status = 'failed',
         gateway_response = coalesce(gateway_response, '{}'::jsonb)
           || jsonb_build_object('musafir_review',
                jsonb_build_object('decision', 'rejected',
                                   'reason', p_reason,
                                   'at', now())),
         updated_at = now()
   where id = p_payment_id;

  return jsonb_build_object('payment_id', p_payment_id, 'status', 'failed');
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_reject_verification(p_user_id uuid, p_reason text, p_face_attempt_id uuid DEFAULT NULL::uuid, p_face_evidence_version uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.profiles; reason text:=btrim(coalesce(p_reason,'')); identity_done boolean:=false;
  face_done boolean:=false; approved_faces int:=0;
begin
  if auth.uid() is null or not public.is_admin() or auth.uid()=p_user_id then
    raise exception 'Another admin must review this verification' using errcode='42501'; end if;
  if reason='' then raise exception 'A rejection reason is required'; end if;
  if length(reason)>500 then raise exception 'Keep the reason under 500 characters'; end if;
  select * into p from public.profiles where id=p_user_id for update;
  if not found then raise exception 'Account not found'; end if;

  if p.verification_status in ('pending','verified') then
    update public.owner_documents set verified_at=null,verified_by=null,rejection_reason=reason
      where user_id=p_user_id and document_type in ('nid_front','nid_back');
    update public.profiles set verification_status='rejected',nid_verified=false where id=p_user_id;
    identity_done:=true;
  end if;

  if p_face_attempt_id is not null then
    if (select user_id from public.face_verification_attempts where id=p_face_attempt_id) is distinct from p_user_id then
      raise exception 'Face submission belongs to another account' using errcode='42501'; end if;
    perform public.review_face_verification(p_face_attempt_id,p_face_evidence_version,'rejected',reason);
    face_done:=true;
  end if;

  update public.face_verification_attempts set status='rejected', reviewed_by=auth.uid(),
    reviewed_at=now(), review_note=reason
    where user_id=p_user_id and status='approved';
  get diagnostics approved_faces = row_count;
  face_done := face_done or approved_faces > 0;

  if not identity_done and not face_done then
    raise exception 'Nothing to reject. Refresh the queue'; end if;
  return jsonb_build_object('identity_rejected',identity_done,'face_rejected',face_done);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_release_payment(p_payment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payment public.payments%rowtype;
  v_booking_status text;
begin
  perform public.fn_require_service_role();

  select * into v_payment from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'Payment not found' using errcode = 'P0002';
  end if;
  if v_payment.status <> 'pending_review' then
    raise exception 'Only a payment held for review can be released (status is %)',
      v_payment.status using errcode = '22023';
  end if;

  select booking_status::text into v_booking_status
    from public.bookings where id = v_payment.booking_id;
  if v_booking_status is null or v_booking_status not in ('confirmed', 'active') then
    raise exception 'This booking is % — the payment can only be rejected and refunded, not released',
      coalesce(v_booking_status, 'gone')
      using errcode = '22023', hint = 'booking_not_open';
  end if;

  update public.payments
     set status = 'paid', updated_at = now()
   where id = p_payment_id;

  perform set_config('musafir.settlement_write', '1', true);
  update public.bookings
     set payment_status = 'paid',
         paid_at = coalesce(paid_at, now())
   where id = v_payment.booking_id;
  perform set_config('musafir.settlement_write', '0', true);

  return jsonb_build_object('payment_id', p_payment_id,
                            'booking_id', v_payment.booking_id,
                            'status', 'paid');
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_retry_sms_failures(p_campaign_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
begin
  perform public.fn_require_service_role();

  update public.sms_recipients
     set status = 'pending', error = null, provider_status = null
   where campaign_id = p_campaign_id and status = 'failed';
  get diagnostics v_count = row_count;

  if v_count > 0 then
    update public.sms_campaigns
       set status = 'queued', finished_at = null
     where id = p_campaign_id;
  end if;

  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_reveal_reviews()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    -- Only allow service_role to execute
    IF current_setting('role') != 'service_role' THEN
        RAISE EXCEPTION 'Only service_role can execute this function';
    END IF;

    RETURN public.auto_reveal_old_reviews();
END;
$function$;

CREATE OR REPLACE FUNCTION public.admin_send_bulk_notification(p_title text, p_body text, p_type notification_type, p_priority notification_priority, p_action_url text, p_filters jsonb, p_created_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_campaign uuid;
  v_max      integer := public.notification_bulk_max_recipients();
  v_total    integer;
  v_pushed   integer;
  v_skipped  integer;
begin
  perform public.fn_require_service_role();

  if coalesce(trim(p_title), '') = '' then
    raise exception 'A notification needs a title' using errcode = '22023';
  end if;
  if coalesce(trim(p_body), '') = '' then
    raise exception 'A notification needs a message' using errcode = '22023';
  end if;

  -- Hold the audience still for the whole call. Reading it twice — once to
  -- count, once to insert — could answer differently if somebody changed their
  -- preferences in between, and the admin confirmed the first number.
  --
  -- Dropped first, not just `on commit drop`. Every raise below happens AFTER
  -- the table exists, so a caught exception leaves it behind and the next call
  -- in the SAME transaction dies with "relation already exists" — invisible in
  -- production, where each call is its own transaction, and immediate in any
  -- test that exercises a refusal and then a success.
  drop table if exists t_audience;
  create temp table t_audience on commit drop as
    select * from public.admin_notify_audience(p_filters, p_type, p_priority);

  select count(*) filter (where delivers),
         count(*) filter (where push_allowed),
         count(*) filter (where not delivers)
    into v_total, v_pushed, v_skipped
    from t_audience;

  if v_total = 0 then
    raise exception 'Nobody in this audience would receive it' using errcode = '22023';
  end if;
  if v_max = 0 then
    raise exception 'Bulk notifications are disabled (notification_bulk_max_recipients is 0)'
      using errcode = '22023';
  end if;
  -- Refused, never truncated: sending to the first 2000 of 3000 would leave the
  -- admin believing everyone was reached.
  if v_total > v_max then
    raise exception 'This campaign has % recipients, above the current limit of %',
      v_total, v_max using errcode = '22023';
  end if;

  insert into public.notification_campaigns
    (title, body, type, priority, action_url, audience, created_by,
     total_recipients, pushed_count, skipped_count, sent_at)
  values
    (trim(p_title), p_body, p_type, p_priority, nullif(trim(coalesce(p_action_url,'')), ''),
     coalesce(p_filters, '{}'::jsonb), p_created_by,
     v_total, v_pushed, v_skipped, now())
  returning id into v_campaign;

  -- `suppress_push` is set per recipient, so one campaign can buzz the phones
  -- of people who allow it while still reaching the in-app inbox of those who
  -- asked for in-app only. Row-level, because the preference is.
  insert into public.notifications
    (user_id, type, title, body, priority, action_url, campaign_id, data)
  select a.user_id,
         p_type,
         trim(p_title),
         p_body,
         p_priority,
         nullif(trim(coalesce(p_action_url,'')), ''),
         v_campaign,
         jsonb_build_object(
           'campaign_id', v_campaign::text,
           'suppress_push', (not a.push_allowed)
         )
    from t_audience a
   where a.delivers;

  drop table if exists t_audience;

  return jsonb_build_object(
    'campaign_id', v_campaign,
    'total', v_total,
    'pushed', v_pushed,
    'skipped', v_skipped
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_sms_suppression(p_phone text, p_opt_out boolean, p_reason text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_phone text := public.fn_canonical_bd_phone(p_phone);
begin
  perform public.fn_require_service_role();

  if v_phone is null then
    raise exception 'Not a valid Bangladeshi mobile number: %', p_phone
      using errcode = '22023';
  end if;

  if p_opt_out then
    insert into public.sms_suppressions (phone, reason, created_by)
    values (v_phone, p_reason, p_actor)
    on conflict (phone) do update set reason = excluded.reason;
  else
    delete from public.sms_suppressions where phone = v_phone;
  end if;

  return p_opt_out;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_sms_audience(p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(user_id uuid, full_name text, phone text, suppressed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
  perform public.fn_require_service_role();

  return query
  select distinct on (c.phone)
         c.id,
         c.full_name,
         c.phone,
         exists (select 1 from public.sms_suppressions s where s.phone = c.phone)
    from (
      select p.id,
             p.full_name,
             coalesce(
               public.fn_canonical_bd_phone(
                 substring(u.email from '^phone\.([0-9]+)@musaafir\.app$')),
               public.fn_canonical_bd_phone(p.mobile)
             ) as phone,
             p.role::text as role,
             p.is_host,
             p.verification_status::text as verification_status,
             p.created_at
        from public.profiles p
        left join auth.users u on u.id = p.id
    ) c
   where c.phone is not null
     and (p_filters ->> 'role' is null
          or c.role = p_filters ->> 'role')
     and (p_filters ->> 'is_host' is null
          or c.is_host = (p_filters ->> 'is_host')::boolean)
     and (p_filters ->> 'verification_status' is null
          or c.verification_status = p_filters ->> 'verification_status')
     and (p_filters ->> 'joined_from' is null
          or c.created_at >= (p_filters ->> 'joined_from')::timestamptz)
     and (p_filters ->> 'joined_to' is null
          or c.created_at <= (p_filters ->> 'joined_to')::timestamptz)
     -- An explicit list of ids, for "select some users" rather than a filter.
     and (p_filters -> 'user_ids' is null
          or c.id = any (select (jsonb_array_elements_text(p_filters -> 'user_ids'))::uuid))
   -- Ties between two accounts sharing a number resolve to the older one, so
   -- repeating the same query gives the same answer.
   order by c.phone, c.created_at, c.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_start_sms_campaign(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_campaign public.sms_campaigns;
  v_pending  integer;
  v_max      integer := public.sms_bulk_max_recipients();
begin
  perform public.fn_require_service_role();

  select * into v_campaign from public.sms_campaigns where id = p_campaign_id for update;
  if not found then
    raise exception 'No such campaign' using errcode = '22023';
  end if;
  -- Idempotent by status, so a double-submitted form cannot start one twice.
  if v_campaign.status <> 'draft' then
    raise exception 'Campaign is already %', v_campaign.status using errcode = '22023';
  end if;

  select count(*) into v_pending
    from public.sms_recipients where campaign_id = p_campaign_id and status = 'pending';

  if v_pending = 0 then
    raise exception 'This campaign has no recipients to send to' using errcode = '22023';
  end if;

  -- Refused, never truncated. Silently sending to the first 500 of 900 would
  -- leave the admin believing 900 were reached.
  if v_max = 0 then
    raise exception 'Bulk SMS is disabled (sms_bulk_max_recipients is 0)'
      using errcode = '22023';
  end if;
  if v_pending > v_max then
    raise exception 'This campaign has % recipients, above the current limit of %',
      v_pending, v_max using errcode = '22023';
  end if;

  update public.sms_campaigns
     set status = 'queued', started_at = now(), total_recipients = v_pending
   where id = p_campaign_id;

  return jsonb_build_object('queued', v_pending);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_suspend_user(p_user_id uuid, p_reason text, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_role     text;
  v_already  timestamptz;
  v_sessions integer := 0;
  v_listings integer := 0;
  v_declined integer := 0;
  v_own      integer := 0;
begin
  perform public.fn_require_service_role();

  select role, suspended_at into v_role, v_already
    from public.profiles where id = p_user_id for update;
  if v_role is null then
    raise exception 'User not found' using errcode = 'P0002';
  end if;
  -- An admin is suspended by taking the role away first; doing both in one
  -- move from a text box is how a console loses its last admin.
  if v_role = 'admin' then
    raise exception 'Change this account''s role before suspending it'
      using errcode = '42501';
  end if;
  if v_already is not null then
    return jsonb_build_object('already_suspended', true, 'suspended_at', v_already);
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'A reason is required' using errcode = '22023';
  end if;

  update public.profiles
     set suspended_at = now(), suspended_reason = btrim(p_reason), suspended_by = p_actor
   where id = p_user_id;

  -- The enforcement. postgres holds DELETE on auth.sessions (124, proven by
  -- doing it); every device dies at its next token refresh.
  delete from auth.sessions where user_id = p_user_id;
  get diagnostics v_sessions = row_count;

  -- No more pushes to a phone that can no longer act on them.
  update public.fcm_tokens set is_active = false
   where user_id = p_user_id and is_active;

  -- A suspended host's live listings come down, and are marked so
  -- admin_unsuspend_user can put back exactly these.
  update public.listings
     set is_active = false, suspended_hidden = true
   where owner_id = p_user_id and is_active;
  get diagnostics v_listings = row_count;

  -- Requests waiting on this host would otherwise sit until the sweep expires
  -- them; the guests are told now, through the normal "declined" path.
  update public.bookings b
     set booking_status = 'rejected',
         rejection_reason = 'The host''s account is no longer active'
   where b.booking_status = 'pending'
     and exists (select 1 from public.listings l
                  where l.id = b.listing_id and l.owner_id = p_user_id);
  get diagnostics v_declined = row_count;

  -- And this account's own open requests as a guest are withdrawn. Named as
  -- the guest's own cancellation so the host is told the way they would be
  -- for any other withdrawn request.
  update public.bookings
     set booking_status = 'cancelled', cancelled_by = p_user_id, cancelled_at = now()
   where tenant_id = p_user_id and booking_status = 'pending';
  get diagnostics v_own = row_count;

  return jsonb_build_object(
    'suspended_at', now(),
    'sessions_ended', v_sessions,
    'listings_hidden', v_listings,
    'requests_declined', v_declined,
    'own_requests_withdrawn', v_own);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_unsuspend_user(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_already timestamptz;
  v_listings integer := 0;
begin
  perform public.fn_require_service_role();

  select suspended_at into v_already
    from public.profiles where id = p_user_id for update;
  if not found then
    raise exception 'User not found' using errcode = 'P0002';
  end if;
  if v_already is null then
    return jsonb_build_object('was_suspended', false);
  end if;

  update public.profiles
     set suspended_at = null, suspended_reason = null, suspended_by = null
   where id = p_user_id;

  update public.listings
     set is_active = true, suspended_hidden = false
   where owner_id = p_user_id and suspended_hidden;
  get diagnostics v_listings = row_count;

  return jsonb_build_object('was_suspended', true, 'listings_restored', v_listings);
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_identity_document(p_user_id uuid, p_document_type text, p_front_path text, p_back_path text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not public.is_admin() or auth.uid()=p_user_id then
    raise exception 'Another admin must approve this document' using errcode='42501'; end if;
  perform 1 from public.profiles where id=p_user_id and id_document_type is not distinct from p_document_type and verification_status='pending' for update;
  if not found then raise exception 'Submission changed. Refresh the review queue'; end if;
  if p_document_type='nid' and p_back_path is null then raise exception 'NID requires both sides'; end if;
  perform 1 from public.owner_documents where user_id=p_user_id and document_type in ('nid_front','nid_back') for update;
  if not exists(select 1 from public.owner_documents where user_id=p_user_id and document_type='nid_front' and file_path=p_front_path)
    or (p_back_path is not null and not exists(select 1 from public.owner_documents where user_id=p_user_id and document_type='nid_back' and file_path=p_back_path))
    or (p_back_path is null and exists(select 1 from public.owner_documents where user_id=p_user_id and document_type='nid_back')) then
    raise exception 'Documents changed. Refresh the review queue'; end if;
  if not exists(select 1 from storage.objects where bucket_id='documents' and name=p_front_path)
    or (p_back_path is not null and not exists(select 1 from storage.objects where bucket_id='documents' and name=p_back_path)) then
    raise exception 'Document evidence is unavailable'; end if;
  update public.owner_documents set verified_at=now(),verified_by=auth.uid(),rejection_reason=null
    where user_id=p_user_id and document_type in ('nid_front','nid_back');
  update public.profiles set verification_status='verified',nid_verified=true where id=p_user_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_nid_verification(p_user_id uuid, p_front_path text, p_back_path text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.approve_identity_document(p_user_id,'nid',p_front_path,p_back_path);
$function$;

CREATE OR REPLACE FUNCTION public.auto_complete_elapsed_bookings()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    completed_count integer;
    booking_record RECORD;
    listing_record RECORD;
    guest_record RECORD;
BEGIN
    completed_count := 0;

    FOR booking_record IN
        SELECT b.*
        FROM public.bookings b
        WHERE b.booking_status IN ('confirmed', 'active')
        AND b.ends_at < NOW() - INTERVAL '24 hours'
    LOOP
        -- Presume the stay happened: move to completed and stamp completed_at.
        UPDATE public.bookings
        SET
            booking_status = 'completed',
            completed_at = NOW()
        WHERE id = booking_record.id;

        -- Send the host's "After checkout" template to the guest. Auto-complete
        -- is the ONLY completion path for stays the host never marks done, so
        -- without this the checkout message never fires. Defensive: a bad
        -- template must not abort the whole completion job.
        BEGIN
            PERFORM public.send_checkout_for_booking(booking_record.id);
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'checkout message failed for booking %: %', booking_record.id, SQLERRM;
        END;

        -- Listing info for notifications
        SELECT l.title, l.owner_id INTO listing_record
        FROM public.listings l
        WHERE l.id = booking_record.listing_id;

        -- Guest info
        SELECT p.full_name INTO guest_record
        FROM public.profiles p
        WHERE p.id = booking_record.tenant_id;

        -- Nudge the guest to leave a review (opens the review window)
        INSERT INTO public.notifications (
            user_id, type, title, body, priority, action_url, data
        ) VALUES (
            booking_record.tenant_id,
            'review_prompt'::notification_type,
            'How was your stay?',
            format('Your stay at %s is complete. Leave a review to help other travelers!',
                COALESCE(listing_record.title, 'the property')),
            'normal'::notification_priority,
            '/review/' || booking_record.id || '/guest',
            jsonb_build_object(
                'booking_id', booking_record.id,
                'listing_id', booking_record.listing_id,
                'reason', 'auto_completed',
                'completed_at', NOW()
            )
        );

        -- Nudge the host to review the guest
        INSERT INTO public.notifications (
            user_id, type, title, body, priority, action_url, data
        ) VALUES (
            listing_record.owner_id,
            'review_prompt'::notification_type,
            'Reservation completed',
            format('%s''s stay at %s is complete. Leave a review for your guest.',
                COALESCE(guest_record.full_name, 'Your guest'),
                COALESCE(listing_record.title, 'your property')),
            'normal'::notification_priority,
            '/review/' || booking_record.id || '/host',
            jsonb_build_object(
                'booking_id', booking_record.id,
                'listing_id', booking_record.listing_id,
                'reason', 'auto_completed',
                'completed_at', NOW()
            )
        );

        completed_count := completed_count + 1;
    END LOOP;

    IF completed_count > 0 THEN
        RAISE NOTICE 'Auto-completed % elapsed bookings', completed_count;
    END IF;

    RETURN completed_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.auto_reveal_old_reviews()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    revealed_count integer;
    review_record RECORD;
    booking_record RECORD;
    listing_record RECORD;
BEGIN
    revealed_count := 0;

    -- Find reviews older than 14 days that haven't been revealed
    FOR review_record IN
        SELECT r.*
        FROM public.reviews r
        WHERE r.is_revealed = false
        AND r.created_at < NOW() - INTERVAL '14 days'
    LOOP
        -- Reveal the review
        UPDATE public.reviews
        SET
            is_revealed = true,
            revealed_at = NOW()
        WHERE id = review_record.id;

        -- Get booking and listing info for notification
        SELECT b.*, l.title AS listing_title, l.owner_id AS host_id
        INTO booking_record
        FROM public.bookings b
        LEFT JOIN public.listings l ON l.id = b.listing_id
        WHERE b.id = review_record.booking_id;

        -- Notify the reviewee that they received a review
        INSERT INTO public.notifications (
            user_id, type, title, body, priority, action_url, data
        ) VALUES (
            review_record.reviewee_id,
            'review_received'::notification_type,
            'New Review Available',
            CASE
                WHEN review_record.review_type = 'guest_to_host' THEN
                    format('You received a %s star review for %s',
                        review_record.overall_rating,
                        COALESCE(booking_record.listing_title, 'your property'))
                ELSE
                    format('You received a %s star review from a host', review_record.overall_rating)
            END,
            'normal'::notification_priority,
            CASE
                WHEN review_record.review_type = 'guest_to_host' THEN '/listing/' || review_record.listing_id || '/reviews'
                ELSE '/profile/reviews'
            END,
            jsonb_build_object(
                'review_id', review_record.id,
                'booking_id', review_record.booking_id,
                'rating', review_record.overall_rating,
                'review_type', review_record.review_type,
                'auto_revealed', true
            )
        );

        revealed_count := revealed_count + 1;
    END LOOP;

    -- Log the result
    IF revealed_count > 0 THEN
        RAISE NOTICE 'Auto-revealed % reviews', revealed_count;
    END IF;

    RETURN revealed_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_listing_dates(p_listing_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_block public.listing_availability_blocks%rowtype;
begin
  if v_uid is null then
    raise exception 'You must be signed in' using errcode = '42501';
  end if;

  if p_starts_at is null or p_ends_at is null or p_ends_at <= p_starts_at then
    raise exception 'Invalid dates' using errcode = '22023';
  end if;

  -- Ownership. SECURITY DEFINER means RLS is not doing this for us.
  if not exists (
    select 1 from public.listings l
    where l.id = p_listing_id
      and (l.owner_id = v_uid or public.is_admin())
  ) then
    raise exception 'You can only block dates on your own listing'
      using errcode = '42501';
  end if;

  -- Refuse to block over a live booking. Silently swallowing this would leave
  -- the host believing they are free on a date a guest is already holding, and
  -- the guest with a booking the host has mentally cancelled. Make them decline
  -- it explicitly instead.
  if exists (
    select 1 from public.bookings b
    where b.listing_id = p_listing_id
      and b.booking_status in ('pending', 'confirmed', 'active')
      and tstzrange(b.starts_at, b.ends_at, '[)')
          && tstzrange(p_starts_at, p_ends_at, '[)')
  ) then
    raise exception 'You already have a booking in these dates. Decline or cancel it first.'
      using errcode = '23P01', hint = 'block_over_booking';
  end if;

  -- The handler is scoped to the INSERT alone, deliberately. 23P01 *is*
  -- exclusion_violation, so a function-level `when exclusion_violation` would
  -- also catch the booking-overlap raise above and relabel it as a block
  -- collision — the wrong sentence for the wrong problem.
  begin
    insert into public.listing_availability_blocks
      (listing_id, starts_at, ends_at, note, created_by)
    values
      (p_listing_id, p_starts_at, p_ends_at, nullif(trim(coalesce(p_note, '')), ''), v_uid)
    returning * into v_block;
  exception
    -- listing_blocks_no_overlap. Reachable by a double-tap or two devices, and
    -- "conflicting key value violates exclusion constraint" is not a sentence
    -- to show a host.
    when exclusion_violation then
      raise exception 'These dates overlap a block you already have.'
        using errcode = '23P01', hint = 'block_overlaps_block';
  end;

  return to_jsonb(v_block);
end;
$function$;

CREATE OR REPLACE FUNCTION public.booking_accept_window_hours()
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select btrim(value)::integer
       from public.app_settings
      where key = 'booking_accept_window_hours'
        and btrim(coalesce(value, '')) ~ '^[0-9]+$'),
    24);
$function$;

CREATE OR REPLACE FUNCTION public.can_publish_listings()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(select 1 from public.profiles p where p.id=auth.uid()
    and p.role in ('owner','admin') and public.has_approved_face_or_identity(p.id));
$function$;

CREATE OR REPLACE FUNCTION public.can_see_listing_address(p_listing_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    -- Admins run the safety/verification queues and need the real address.
    public.is_admin()
    -- The host knows their own address.
    or exists (
      select 1 from public.listings l
      where l.id = p_listing_id and l.owner_id = auth.uid()
    )
    -- A guest with a LIVE entitlement. `pending` is excluded on purpose: asking
    -- to stay somewhere must not be enough to learn where it is. `rejected` and
    -- `cancelled` are excluded too — an acceptance that fell through is not a
    -- standing invitation.
    --
    -- `completed` is time-boxed (103). It used to be unbounded, which meant one
    -- finished stay disclosed the host's door to that guest permanently, on
    -- every later visit to the listing page. The window is measured from
    -- `ends_at` — when the guest was last entitled to be there — rather than
    -- from `completed_at`, so a host who marks a stay done weeks late cannot
    -- extend a stranger's access by being slow with their paperwork.
    or exists (
      select 1 from public.bookings b
      where b.listing_id = p_listing_id
        and b.tenant_id = auth.uid()
        and (
          b.booking_status in ('confirmed', 'active')
          or (
            b.booking_status = 'completed'
            and b.ends_at > now() - make_interval(days =>
                  coalesce(
                    (select nullif(btrim(value), '')::int
                       from public.app_settings
                      where key = 'address_disclosure_grace_days'),
                    7))
          )
        )
    );
$function$;

CREATE OR REPLACE FUNCTION public.can_upload_listing_image()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.can_publish_listings()
      or exists (select 1 from public.listings l where l.owner_id = auth.uid());
$function$;

CREATE OR REPLACE FUNCTION public.capture_monthly_leaderboard_snapshot()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.host_leaderboard_snapshots (period, host_id, rank, score, captured_at)
  SELECT to_char(timezone('utc', now()), 'YYYY-MM'), host_id, rank, score, timezone('utc', now())
  FROM public.host_leaderboard_ranked('monthly')
  ON CONFLICT (period, host_id) DO UPDATE
    SET rank = EXCLUDED.rank,
        score = EXCLUDED.score,
        captured_at = EXCLUDED.captured_at;
$function$;

CREATE OR REPLACE FUNCTION public.check_and_reveal_reviews()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    other_review_exists boolean;
begin
    select exists (
        select 1 from public.reviews
        where booking_id = new.booking_id
          and review_type != new.review_type
          and is_revealed = false
    ) into other_review_exists;

    if other_review_exists then
        update public.reviews
        set is_revealed = true, revealed_at = timezone('utc', now())
        where booking_id = new.booking_id and is_revealed = false;
    end if;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.cleanup_old_otps()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  deleted_count integer;
begin
  with deleted as (
    delete from public.otp_attempts
    where
      -- Remove verified OTPs after 24 hours
      (verified_at is not null and verified_at < now() - interval '24 hours')
      -- Remove expired unverified OTPs after 24 hours
      or (verified_at is null and expires_at < now() - interval '24 hours')
      -- Hard limit: remove anything older than 7 days
      or created_at < now() - interval '7 days'
    returning 1
  )
  select count(*) into deleted_count from deleted;

  return deleted_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.coupons_normalize_code()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.code := upper(trim(new.code));
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_marketplace_booking(p_listing_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_pricing_unit text, p_guest_count integer, p_tenant_name text DEFAULT NULL::text, p_coupon_code text DEFAULT NULL::text, p_listing_image_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid        uuid := auth.uid();
  v_listing    public.listings%rowtype;
  v_rate       numeric;
  v_qty        int;
  v_min        int;
  v_max        int;
  v_unit_word  text;
  v_gross      numeric;
  v_discount   numeric := 0;
  v_coupon_id  uuid;
  v_total      numeric;
  v_res        jsonb;
  v_booking    public.bookings%rowtype;
  v_unit       uuid;
  v_units      int;
begin
  if v_uid is null then
    raise exception 'You must be signed in to book' using errcode = '42501';
  end if;

  -- Either historical identity approval or explicit current face-review approval.
  -- Keep the stable error hint consumed by the booking client.
  if not public.has_approved_face_or_identity(v_uid) then
    raise exception 'Admin face review is required before booking'
      using errcode = '42501', hint = 'identity_unverified';
  end if;

  -- Reserved interval must be forward-in-time.
  if p_ends_at is null or p_starts_at is null or p_ends_at <= p_starts_at then
    raise exception 'Invalid booking dates' using errcode = '22023';
  end if;

  -- 135: and it must not be in the past. Measured: a stay starting ten days
  -- ago was accepted and returned an id. Past slots are always "free", so the
  -- availability checks below never object, and `expire_stale_bookings` /
  -- the auto-complete sweep then walk the row straight to completed — which
  -- is a review prompt and a ledger entry for a stay nobody had.
  --
  -- The calendar already hides past dates. That is the "the booking form
  -- checks it" pattern this codebase has been bitten by four times: the form
  -- is skippable and the RPC is a public endpoint.
  --
  -- One hour of slack rather than a hard `>= now()`, because a guest booking
  -- a turf for *this* hour is the normal case for hourly listings, the
  -- client's clock is its own, and `now()` here is transaction time. The
  -- guard exists to stop last month, not to police the last minute.
  if p_starts_at < now() - interval '1 hour' then
    raise exception 'Choose a start time in the future'
      using errcode = '22023', hint = 'starts_in_past';
  end if;

  -- Load the listing. Must exist and be active.
  select * into v_listing from public.listings where id = p_listing_id;
  if not found then
    raise exception 'Listing not found' using errcode = 'P0002';
  end if;
  if not coalesce(v_listing.is_active, true) then
    raise exception 'This listing is no longer available' using errcode = '22023';
  end if;

  -- 135: a host must not book their own listing. Nothing checked this, and
  -- live already holds one such booking. Two things go wrong when it is
  -- allowed: the ledger posts the owner an earning against money that only
  -- moved between their own two pockets (or did not move at all, on the cash
  -- path), and a host can black out their own calendar through the booking
  -- path instead of listing_availability_blocks (110), which is the feature
  -- built for exactly that and the only one the host's own UI can undo.
  if v_listing.owner_id = v_uid then
    raise exception 'You cannot book your own listing'
      using errcode = '42501', hint = 'self_booking';
  end if;

  -- 138: a block is a wall, not a filter. `user_blocks` (SAFETY.md) only ever
  -- hid the other party's listings and threads in the CLIENT; measured
  -- 2026-09-19, a guest a host had blocked booked that host's listing and
  -- opened a conversation with them without a hitch. Either direction counts:
  -- a host who blocked a guest does not want their money, and a guest who
  -- blocked a host does not want to stay there.
  -- 140: a suspended account keeps its access token for up to an hour.
  if public.fn_is_suspended(v_uid) then
    raise exception 'This account is suspended'
      using errcode = '42501', hint = 'account_suspended';
  end if;
  -- And a suspended host's listings are hidden, but a deep link or a stale
  -- client can still name one.
  if public.fn_is_suspended(v_listing.owner_id) then
    raise exception 'This listing is no longer available' using errcode = '22023';
  end if;

  if public.fn_users_blocked(v_uid, v_listing.owner_id) then
    raise exception 'You cannot book this listing'
      using errcode = '42501', hint = 'blocked';
  end if;

  -- The host-wide Away switch (038). Only ever a search filter before this, so
  -- a guest who already had the page open could book straight past it.
  if not coalesce(v_listing.host_available, true) then
    raise exception 'This host isn''t accepting new bookings right now'
      using errcode = '22023';
  end if;

  -- Guest count within the listing's capacity.
  if p_guest_count is null or p_guest_count < 1 then
    raise exception 'At least one guest is required' using errcode = '22023';
  end if;
  if v_listing.max_guests is not null and p_guest_count > v_listing.max_guests then
    raise exception 'This place hosts up to % guests', v_listing.max_guests
      using errcode = '22023';
  end if;

  -- Server-side rate + quantity. Quantity is derived from the reserved interval
  -- so the client can't understate it; hour/day are exact epoch multiples,
  -- month is a calendar diff (monthly stays are booked whole-month, same day).
  -- The per-plan duration limits (055) are read here too, so the unit, the
  -- quantity and the bounds they are compared against always come from the same
  -- branch and cannot drift apart.
  case p_pricing_unit
    when 'hour' then
      v_rate := v_listing.hourly_rate;
      v_qty  := round(extract(epoch from (p_ends_at - p_starts_at)) / 3600.0);
      v_min  := v_listing.min_hours;
      v_max  := v_listing.max_hours;
      v_unit_word := 'hour';
    when 'day' then
      v_rate := v_listing.daily_rate;
      v_qty  := round(extract(epoch from (p_ends_at - p_starts_at)) / 86400.0);
      v_min  := v_listing.min_nights;
      v_max  := v_listing.max_nights;
      -- 'night', not 'day' — matches the word the booking form uses, so the
      -- guest doesn't get two different names for one number.
      v_unit_word := 'night';
    when 'month' then
      v_rate := v_listing.monthly_rate;
      v_qty  := (extract(year from p_ends_at) - extract(year from p_starts_at))::int * 12
              + (extract(month from p_ends_at) - extract(month from p_starts_at))::int;
      v_min  := v_listing.min_months;
      v_max  := v_listing.max_months;
      v_unit_word := 'month';
    else
      raise exception 'Unsupported booking type: %', p_pricing_unit using errcode = '22023';
  end case;

  if v_rate is null then
    raise exception 'This listing is not available for % bookings', p_pricing_unit
      using errcode = '22023';
  end if;

  -- The hourly policy (148): the platform floor per listing type, the offered
  -- slot durations and the host's day-use window. One function holds the rule
  -- for the server and HourlyPolicy.resolve mirrors it in Dart; it is checked
  -- here, before the generic min/max, because its floor can be HIGHER than
  -- the host's own min_hours and its message says which.
  if p_pricing_unit = 'hour' then
    perform public.hourly_booking_check(p_listing_id, p_starts_at, p_ends_at);
  end if;
  if v_qty is null or v_qty < 1 then
    raise exception 'Booking must be at least one %', p_pricing_unit using errcode = '22023';
  end if;

  -- The host's per-plan minimum/maximum (055). `coalesce(v_min, 1)` mirrors
  -- BookingLimits.minFor's `?? 1` in lib/models/listing.dart — if those two ever
  -- disagree, the form and the server disagree about the floor and the guest
  -- gets refused for something the UI let them pick.
  if v_qty < coalesce(v_min, 1) then
    raise exception 'Minimum booking is % %', coalesce(v_min, 1),
      v_unit_word || case when coalesce(v_min, 1) = 1 then '' else 's' end
      using errcode = '22023';
  end if;
  if v_max is not null and v_qty > v_max then
    raise exception 'Maximum booking is % %', v_max,
      v_unit_word || case when v_max = 1 then '' else 's' end
      using errcode = '22023';
  end if;

  v_gross := round(v_rate * v_qty, 2);

  -- Host-declared blocked dates (110), the listing-wide kind. Checked before
  -- the unit selection so a hotel the host closed for renovation says so,
  -- rather than "fully booked". A block is not a bookings row, so no single
  -- exclusion constraint can cover both tables; a host blocking dates in the
  -- same millisecond a guest commits can lose this check. That window is
  -- accepted deliberately — the cost is one booking the host declines by hand,
  -- and the alternative (storing blocks AS bookings rows under a sentinel
  -- status) would drag them through earnings, commission, payouts and the host
  -- reservations list.
  if exists (
    select 1 from public.listing_availability_blocks blk
    where blk.listing_id = p_listing_id
      and blk.unit_id is null
      and tstzrange(blk.starts_at, blk.ends_at, '[)')
          && tstzrange(p_starts_at, p_ends_at, '[)')
  ) then
    raise exception 'The host has blocked these dates' using errcode = '22023';
  end if;

  -- Same user can't hold two overlapping bookings. Backed by
  -- bookings_no_tenant_overlap, so losing the race here fails at COMMIT rather
  -- than slipping through. Before the unit selection so the guest's own
  -- double-booking is named as such rather than consuming a room first.
  if exists (
    select 1 from public.bookings b
    where b.tenant_id = v_uid
      and b.booking_status in ('pending', 'confirmed', 'active')
      and p_starts_at < b.ends_at
      and b.starts_at < p_ends_at
  ) then
    raise exception 'You already have a booking during this time'
      using errcode = '23P01', hint = 'tenant_overlap';
  end if;

  -- 147: pick a unit. Any active one with no live booking and no per-unit
  -- block over the interval, lowest label first so a hotel fills "101, 102,
  -- …" in order and a single-unit listing has exactly one candidate.
  -- `for update skip locked` is the race rule: a unit another transaction is
  -- in the middle of booking is invisible here, so two guests never pick the
  -- same row, and the loser of the last-room race is refused at once instead
  -- of waiting on a lock it would lose anyway. The `hint` is what the Dart
  -- layer reads to choose the guest-facing sentence (111).
  select u.id into v_unit
    from public.listing_units u
   where u.listing_id = p_listing_id
     and u.is_active
     and not exists (
       select 1 from public.bookings b
       where b.unit_id = u.id
         and b.booking_status in ('pending', 'confirmed', 'active')
         and tstzrange(b.starts_at, b.ends_at, '[)')
             && tstzrange(p_starts_at, p_ends_at, '[)'))
     and not exists (
       select 1 from public.listing_availability_blocks blk
       where blk.unit_id = u.id
         and tstzrange(blk.starts_at, blk.ends_at, '[)')
             && tstzrange(p_starts_at, p_ends_at, '[)'))
   order by u.label nulls last, u.created_at
   for update of u skip locked
   limit 1;

  if v_unit is null then
    select count(*) into v_units from public.listing_units
     where listing_id = p_listing_id and is_active;
    raise exception '%',
      case when v_units > 1 then 'Every room is taken for these dates'
           else 'This time slot is already booked' end
      using errcode = '23P01', hint = 'listing_overlap';
  end if;

  -- Coupon (optional). Reuse the authoritative validator against the SERVER
  -- gross, so the discount can't be inflated against a fake amount either.
  if p_coupon_code is not null and length(trim(p_coupon_code)) > 0 then
    v_res := public.validate_coupon(p_coupon_code, v_gross);
    if (v_res->>'valid')::boolean is not true then
      raise exception '%', coalesce(v_res->>'message', 'Invalid coupon')
        using errcode = '22023';
    end if;
    v_discount  := coalesce((v_res->>'discount_amount')::numeric, 0);
    v_coupon_id := (v_res->>'coupon_id')::uuid;
  end if;

  v_total := greatest(v_gross - v_discount, 0);

  insert into public.bookings (
    listing_id, unit_id, tenant_id, tenant_name,
    starts_at, ends_at, pricing_unit, unit_count,
    total_price, guest_count, booking_status,
    listing_title, listing_image_url, listing_city,
    coupon_code, discount_amount
  ) values (
    p_listing_id, v_unit, v_uid, coalesce(p_tenant_name, ''),
    p_starts_at, p_ends_at, p_pricing_unit::pricing_unit, v_qty,
    v_total, p_guest_count, 'pending',
    v_listing.title, p_listing_image_url, v_listing.city,
    case when v_coupon_id is not null then upper(trim(p_coupon_code)) end,
    case when v_coupon_id is not null then v_discount else 0 end
  ) returning * into v_booking;

  -- Record redemption + bump usage atomically. If limits were exhausted between
  -- validate and here, redeem_coupon raises and the whole booking rolls back.
  if v_coupon_id is not null then
    perform public.redeem_coupon(v_coupon_id, v_booking.id, v_discount);
  end if;

  return to_jsonb(v_booking);
end;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_booking_update_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_is_owner boolean;
  v_is_admin boolean;
  v_is_tenant boolean;
begin
  -- Server-side (service_role / cron) has no auth context; trust it.
  if v_uid is null then
    return new;
  end if;

  select exists (
    select 1 from public.profiles p where p.id = v_uid and p.role = 'admin'
  ) into v_is_admin;
  if v_is_admin then
    return new;
  end if;

  -- 140: a suspended account keeps its access token for up to an hour after
  -- its sessions are deleted. Nothing it does in that hour lands.
  if public.fn_is_suspended(v_uid) then
    raise exception 'This account is suspended'
      using errcode = '42501', hint = 'account_suspended';
  end if;

  -- Financial / identity fields never change after creation for non-admins.
  if new.tenant_id  is distinct from old.tenant_id
     or new.listing_id  is distinct from old.listing_id
     or new.total_price is distinct from old.total_price
     or new.starts_at   is distinct from old.starts_at
     or new.ends_at     is distinct from old.ends_at then
    raise exception
      'Booking amount, dates and parties cannot be modified after creation';
  end if;

  -- 138: and neither does anything else create_marketplace_booking decided.
  -- guest_count is the capacity the host agreed to; unit_count and
  -- pricing_unit are what total_price was computed from; the coupon columns
  -- are what the ledger and the coupon's usage count rest on; the listing_*
  -- and tenant_name copies are what the OTHER party's screens display.
  -- 140: refund_pct / refund_amount are the policy's answer, not an input.
  if new.guest_count       is distinct from old.guest_count
     or new.unit_count        is distinct from old.unit_count
     or new.pricing_unit      is distinct from old.pricing_unit
     or new.coupon_code       is distinct from old.coupon_code
     or new.discount_amount   is distinct from old.discount_amount
     or new.listing_title     is distinct from old.listing_title
     or new.listing_image_url is distinct from old.listing_image_url
     or new.listing_city      is distinct from old.listing_city
     or new.tenant_name       is distinct from old.tenant_name
     or new.created_at        is distinct from old.created_at
     or new.refund_pct        is distinct from old.refund_pct
     or new.refund_amount     is distinct from old.refund_amount then
    raise exception
      'Booking details are fixed once the request is made'
      using errcode = '42501', hint = 'booking_columns_protected';
  end if;

  -- 132: settlement columns are written only by the service role, by admins,
  -- or by the SECURITY DEFINER payment RPCs — never by a client's own table
  -- write. The RPCs announce themselves with a transaction-local flag; see
  -- the header for why neither current_user nor auth.uid() can do this.
  if (new.payment_status is distinct from old.payment_status
      or new.payment_method is distinct from old.payment_method
      or new.paid_at        is distinct from old.paid_at)
     and coalesce(current_setting('musafir.settlement_write', true), '') <> '1' then
    raise exception
      'Payment status is set by the payment gateway or the host''s cash confirmation, not directly'
      using errcode = '42501', hint = 'payment_columns_protected';
  end if;

  -- 138: whoever cancels is the one recorded as cancelling. The lifecycle
  -- notification decides "cancelled by guest" vs "cancelled by host" from this
  -- column, and both the trips screen and the reservations screen print it.
  -- A caller may only ever name themselves; a caller who cancels without
  -- naming anyone is stamped, so the plain-update path notifies the other
  -- party like every other path does.
  if new.cancelled_by is distinct from old.cancelled_by
     and new.cancelled_by is distinct from v_uid then
    raise exception 'cancelled_by must be the account doing the cancelling'
      using errcode = '42501', hint = 'cancelled_by_forged';
  end if;
  if new.booking_status = 'cancelled' and old.booking_status <> 'cancelled' then
    new.cancelled_by := coalesce(new.cancelled_by, v_uid);
    new.cancelled_at := coalesce(new.cancelled_at, now());
  end if;

  select exists (
    select 1 from public.listings l
    where l.id = new.listing_id and l.owner_id = v_uid
  ) into v_is_owner;
  v_is_tenant := (new.tenant_id = v_uid);

  -- Guest: cancellation only, and none of the host's lifecycle fields.
  if v_is_tenant and not v_is_owner then
    if new.host_message      is distinct from old.host_message
       or new.rejection_reason is distinct from old.rejection_reason
       or new.confirmed_at     is distinct from old.confirmed_at
       or new.actual_check_in  is distinct from old.actual_check_in
       or new.completed_at     is distinct from old.completed_at then
      raise exception 'Only the host writes the host''s side of a booking'
        using errcode = '42501', hint = 'host_columns_protected';
    end if;
    if new.booking_status is distinct from old.booking_status then
      if new.booking_status <> 'cancelled' then
        raise exception
          'Guests may only cancel a booking (attempted % -> %)',
          old.booking_status, new.booking_status
          using errcode = '42501', hint = 'booking_transition_forbidden';
      end if;
      if old.booking_status not in ('pending', 'confirmed') then
        raise exception 'Cannot cancel a booking in % state', old.booking_status
          using errcode = '42501', hint = 'booking_transition_forbidden';
      end if;
    end if;
    return new;
  end if;

  -- Host (listing owner) drives accept/reject/check-in/complete/cancel/no-show
  -- — forwards only. This is BookingLifecycleService's table, now enforced:
  --   pending   -> confirmed | rejected | cancelled
  --   confirmed -> active | completed | cancelled | no_show
  --   active    -> completed | cancelled
  -- completed, rejected, cancelled and no_show are terminal. A host who needs
  -- to undo a wrong tap asks the guest to book again; a host who could re-open
  -- a cancelled booking could re-block a guest's calendar and re-post the
  -- earning the guest already walked away from. `confirmed -> completed` stays
  -- allowed because auto_complete_elapsed_bookings takes exactly that step for
  -- a guest who never tapped check-in, and a host finalising by hand is the
  -- same fact.
  if v_is_owner then
    if new.booking_status is distinct from old.booking_status then
      if old.booking_status = 'confirmed' and new.booking_status = 'no_show' then
        if now() < old.starts_at then
          raise exception 'A no-show can only be reported after check-in time (%)',
            old.starts_at
            using errcode = '42501', hint = 'no_show_too_early';
        end if;
      elsif not (
           (old.booking_status = 'pending'
              and new.booking_status in ('confirmed', 'rejected', 'cancelled'))
        or (old.booking_status = 'confirmed'
              and new.booking_status in ('active', 'completed', 'cancelled'))
        or (old.booking_status = 'active'
              and new.booking_status in ('completed', 'cancelled'))
      ) then
        raise exception 'A booking cannot go from % to %',
          old.booking_status, new.booking_status
          using errcode = '42501', hint = 'booking_transition_forbidden';
      end if;
    end if;
    return new;
  end if;

  -- Not tenant, owner, or admin — RLS should already have blocked this.
  raise exception 'Not authorized to update this booking';
end;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_listing_public_location()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- Derived, never client-supplied: whatever `address` a client sends is
  -- discarded in favour of the area-level form.
  new.address   := public.listing_area_address(new.area, new.city, new.postal_code);
  new.latitude  := public.snap_coordinate(new.latitude);
  new.longitude := public.snap_coordinate(new.longitude);

  -- Re-derive the PostGIS columns from the SNAPPED coordinates. The existing
  -- listing_location_trigger / trg_set_listing_geog do this too, but they fire
  -- in trigger-name order and `listing_location_trigger` sorts before this one,
  -- so it would otherwise stamp `location` with the exact point. Doing it here
  -- as well makes the outcome independent of trigger ordering.
  if new.latitude is not null and new.longitude is not null then
    new.location := ST_SetSRID(ST_MakePoint(new.longitude, new.latitude), 4326)::geography;
    new.geog     := ST_SetSRID(ST_MakePoint(new.longitude, new.latitude), 4326)::geography;
  else
    new.location := null;
    new.geog     := null;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.expire_stale_bookings()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    expired_count integer;
    booking_record RECORD;
    listing_record RECORD;
    guest_record RECORD;
    v_hours integer;
    v_window text;
begin
    expired_count := 0;
    -- Read ONCE, outside the loop: a mid-sweep edit must not expire the first
    -- half of the batch on one rule and the second half on another.
    v_hours := public.booking_accept_window_hours();
    v_window := public.fn_humanise_hours(v_hours);

    for booking_record in
        select b.*
        from public.bookings b
        where b.booking_status = 'pending'
          and b.created_at < now() - make_interval(hours => v_hours)
    loop
        update public.bookings
        set booking_status = 'rejected',
            rejection_reason = format(
              'Booking request expired after %s without host response', v_window)
        where id = booking_record.id;

        select l.title, l.owner_id into listing_record
        from public.listings l
        where l.id = booking_record.listing_id;

        select p.full_name into guest_record
        from public.profiles p
        where p.id = booking_record.tenant_id;

        insert into public.notifications (
            user_id, type, title, body, priority, action_url, data
        ) values (
            booking_record.tenant_id,
            'booking_rejected'::notification_type,
            'Booking Request Expired',
            format('Your booking request for %s expired. The host did not respond within %s.',
                coalesce(listing_record.title, 'the property'), v_window),
            'normal'::notification_priority,
            '/trips/' || booking_record.id,
            jsonb_build_object(
                'booking_id', booking_record.id,
                'listing_id', booking_record.listing_id,
                'reason', 'expired',
                'window_hours', v_hours,
                'expired_at', now()
            )
        );

        insert into public.notifications (
            user_id, type, title, body, priority, action_url, data
        ) values (
            listing_record.owner_id,
            'booking_cancelled'::notification_type,
            'Booking Request Expired',
            format('A booking request from %s for %s expired because you did not respond within %s.',
                coalesce(guest_record.full_name, 'a guest'),
                coalesce(listing_record.title, 'your property'),
                v_window),
            'normal'::notification_priority,
            '/host/reservations/' || booking_record.id,
            jsonb_build_object(
                'booking_id', booking_record.id,
                'listing_id', booking_record.listing_id,
                'reason', 'expired',
                'window_hours', v_hours,
                'expired_at', now()
            )
        );

        expired_count := expired_count + 1;
    end loop;

    if expired_count > 0 then
        raise notice 'Expired % pending bookings (window: %)', expired_count, v_window;
    end if;

    return expired_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.expire_stale_payment_attempts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
begin
  update public.payments
     set status = 'abandoned',
         updated_at = now()
   where status = 'initiated'
     and created_at < now() - interval '60 minutes';
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.face_review_required()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Exact 'true' check, the same one start_face_verification makes, so the
  -- switch can never read as "required" while captures are refused.
  select coalesce((select value='true' from public.app_settings where key='face_review_enabled'),false);
$function$;

CREATE OR REPLACE FUNCTION public.face_verification_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.face_verification_attempts;
begin
  if auth.uid() is null then raise exception 'Sign in first' using errcode='42501'; end if;
  select * into a from public.face_verification_attempts where user_id=auth.uid()
    order by created_at desc,id desc limit 1;
  return jsonb_build_object('status',case when a.status='approved' then 'verified'
    when a.status in ('pending','rejected','retry') then a.status else 'none' end,
    'note',a.review_note,'method',a.method,
    'enabled',coalesce((select value='true' from public.app_settings where key='face_review_enabled'),false));
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_alert_paid_cancellation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_title  text;
  v_admin  uuid;
  v_amount text;
  v_total  text;
  v_by     text;
  v_policy text;
begin
  if not (new.booking_status in ('cancelled', 'no_show')
          and old.booking_status not in ('cancelled', 'no_show')
          and new.payment_status = 'paid') then
    return null;
  end if;

  v_title  := coalesce(new.listing_title,
                       (select l.title from public.listings l where l.id = new.listing_id),
                       'a booking');
  v_total  := trim(to_char(coalesce(new.total_price, 0), 'FM999999990.00'));
  v_amount := trim(to_char(coalesce(new.refund_amount, 0), 'FM999999990.00'));
  v_by     := case when new.booking_status = 'no_show' then 'The host reported a no-show on'
                   when new.cancelled_by = new.tenant_id then 'The guest cancelled'
                   else 'The host cancelled' end;
  v_policy := case coalesce(new.refund_pct, 100)
                when 100 then 'full refund'
                when 0 then 'no refund'
                else new.refund_pct || '% refund' end;

  if coalesce(new.refund_amount, 0) > 0 then
    for v_admin in select p.id from public.profiles p where p.role = 'admin' loop
      insert into public.notifications (user_id, type, title, body, priority, action_url, data)
      values (
        v_admin, 'system_alert', 'Refund due: ৳' || v_amount,
        format('%s a paid booking at %s (৳%s). Policy: %s — refund ৳%s from Payouts and mark the booking refunded.',
               v_by, v_title, v_total, v_policy, v_amount),
        'high', '/bookings/' || new.id,
        jsonb_build_object('booking_id', new.id, 'reason', 'paid_cancellation',
                           'amount', new.total_price, 'refund_amount', new.refund_amount,
                           'refund_pct', new.refund_pct, 'cancelled_by', new.cancelled_by)
      );
    end loop;
  end if;

  if new.tenant_id is not null then
    insert into public.notifications (user_id, type, title, body, priority, action_url, data)
    values (
      new.tenant_id, 'system_alert',
      case when coalesce(new.refund_amount, 0) > 0 then 'Your refund is being arranged'
           else 'No refund for this booking' end,
      case when coalesce(new.refund_amount, 0) > 0 then
        format('Your booking at %s was %s after you paid ৳%s. Under the cancellation policy you get ৳%s back (%s). Our team will refund you and be in touch.',
               v_title,
               case when new.booking_status = 'no_show' then 'marked as a no-show' else 'cancelled' end,
               v_total, v_amount, v_policy)
      else
        format('Your booking at %s was %s after you paid ৳%s. Under the cancellation policy no refund is due (%s).',
               v_title,
               case when new.booking_status = 'no_show' then 'marked as a no-show' else 'cancelled' end,
               v_total,
               case when new.booking_status = 'no_show' then 'you did not check in'
                    else 'cancelled after check-in time' end)
      end,
      'high', '/trips/' || new.id,
      jsonb_build_object('booking_id', new.id, 'reason', 'paid_cancellation',
                         'amount', new.total_price, 'refund_amount', new.refund_amount,
                         'refund_pct', new.refund_pct)
    );
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.fn_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old      jsonb := case when tg_op <> 'INSERT' then to_jsonb(old) end;
  v_new      jsonb := case when tg_op <> 'DELETE' then to_jsonb(new) end;
  v_row      jsonb := coalesce(v_new, v_old);
  v_actor    uuid  := auth.uid();
  v_role     text;
  v_source   text  := coalesce(
                        nullif(current_setting('app.audit_source', true), ''),
                        case when auth.uid() is null then 'system' else 'app' end);
  v_category text  := tg_argv[0];
  v_amount   numeric;
  v_currency text;
  v_changed  text[];
begin
  if tg_op = 'UPDATE' then
    select array_agg(k)
      into v_changed
      from jsonb_object_keys(v_new) k
     where (v_new -> k) is distinct from (v_old -> k);
    if v_changed is null then
      return null;
    end if;
  end if;

  if v_actor is not null then
    select role::text into v_role from public.profiles where id = v_actor;
  end if;

  if tg_table_name = 'payments' then
    v_amount   := (v_row ->> 'amount')::numeric;
    v_currency := coalesce(v_row ->> 'currency', 'BDT');
  elsif tg_table_name = 'bookings' then
    v_amount   := (v_row ->> 'total_price')::numeric;
    v_currency := 'BDT';
  elsif tg_table_name = 'disbursements' then
    v_amount   := (v_row ->> 'amount')::numeric;
    v_currency := coalesce(v_row ->> 'currency', 'BDT');
  -- ── New in 101 ────────────────────────────────────────────────────────────
  elsif tg_table_name = 'host_ledger_entries' then
    v_amount   := (v_row ->> 'amount')::numeric;
    v_currency := coalesce(v_row ->> 'currency', 'BDT');
  end if;

  insert into public.audit_log (
    table_name, record_id, action, actor_id, actor_role, source,
    category, amount, currency, changed_cols, old_data, new_data)
  values (
    tg_table_name,
    (v_row ->> 'id')::uuid,
    lower(tg_op),
    v_actor, v_role, v_source,
    v_category, v_amount, v_currency, v_changed, v_old, v_new);

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception 'audit_log is append-only (% blocked)', tg_op
    using errcode = '42501';
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_block_unit_consistent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.unit_id is not null and not exists (
    select 1 from public.listing_units u where u.id = new.unit_id and u.listing_id = new.listing_id
  ) then
    raise exception 'The unit does not belong to this listing'
      using errcode = '22023', hint = 'unit_mismatch';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.fn_booking_unit_consistent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_listing uuid; v_n int;
begin
  if tg_op = 'UPDATE' then
    if new.unit_id is distinct from old.unit_id
       and coalesce(current_setting('musafir.unit_reassign', true), '') <> 'on' then
      raise exception 'A booking cannot be moved to another unit here'
        using errcode = '42501', hint = 'booking_columns_protected';
    end if;
    if new.unit_id is not distinct from old.unit_id
       and new.listing_id is not distinct from old.listing_id then
      return new;
    end if;
  end if;

  if new.unit_id is null then
    -- (array_agg)[1], not min(): there is no min(uuid) in core Postgres.
    select count(*), (array_agg(id))[1] into v_n, new.unit_id
      from public.listing_units where listing_id = new.listing_id;
    if v_n <> 1 then
      raise exception 'This listing has % units; a booking must name one', v_n
        using errcode = '22023', hint = 'unit_required';
    end if;
    return new;
  end if;

  select listing_id into v_listing from public.listing_units where id = new.unit_id;
  if v_listing is distinct from new.listing_id then
    raise exception 'The unit does not belong to this listing'
      using errcode = '22023', hint = 'unit_mismatch';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.fn_caller_booked_listing(p_listing_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select auth.uid() is not null and exists (
    select 1 from public.bookings b
    where b.listing_id = p_listing_id and b.tenant_id = auth.uid()
  );
$function$;

CREATE OR REPLACE FUNCTION public.fn_canonical_bd_phone(p_raw text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  n text;
begin
  if p_raw is null then
    return null;
  end if;

  n := regexp_replace(p_raw, '[[:space:]()\-]', '', 'g');

  if left(n, 4) = '+880' then
    n := '0' || substr(n, 5);
  elsif left(n, 3) = '880' then
    n := '0' || substr(n, 4);
  elsif left(n, 1) = '+' then
    n := substr(n, 2);
  end if;

  -- The bare-10-digit case the login screen invites, because it renders "+880"
  -- as a decorative prefix. See otp.ts for the four accounts this cost.
  if n ~ '^1[3-9][0-9]{8}$' then
    n := '0' || n;
  end if;

  -- The gate. 013-019 are the assigned prefixes; anything else is not a number
  -- we are willing to pay to send to.
  if n !~ '^01[3-9][0-9]{8}$' then
    return null;
  end if;

  return n;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_deactivate_device_tokens()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.revoked_at is not null and old.revoked_at is null
     and new.device_id is not null then
    update public.fcm_tokens
       set is_active = false, updated_at = now()
     where user_id = new.user_id
       and device_id = new.device_id;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_enforce_device_limit(p_user_id uuid, p_keep uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_limit integer := public.max_devices_per_user();
  v_row record;
  v_evicted integer := 0;
  v_names text[] := '{}';
begin
  if v_limit <= 0 then
    return 0;
  end if;

  for v_row in
    select id,
           coalesce(nullif(label, ''), nullif(model, ''),
                    case platform
                      when 'android' then 'an Android phone'
                      when 'ios' then 'an iPhone'
                      else 'a device'
                    end) as name
      from (
        select id, label, model, platform,
               row_number() over (
                 order by (id = p_keep) desc nulls last, last_seen_at desc, id desc
               ) as rn
          from public.user_devices
         where user_id = p_user_id
           and revoked_at is null
           and platform <> 'web'
      ) ranked
     where rn > v_limit
  loop
    perform public.fn_revoke_device_row(v_row.id);
    v_evicted := v_evicted + 1;
    v_names := v_names || v_row.name;
  end loop;

  if v_evicted > 0 then
    -- Never allowed to fail the login it is reporting on. A notification that
    -- raises here would turn "you reached your device limit" into "you cannot
    -- sign in", which is the exact outcome the evict-don't-refuse rule exists
    -- to prevent.
    begin
      insert into public.notifications (user_id, type, title, body, data)
      values (
        p_user_id,
        'security_alert',
        'Signed out of another device',
        case when v_evicted = 1
             then 'You reached your device limit, so ' || v_names[1] ||
                  ' was signed out.'
             else 'You reached your device limit, so ' || v_evicted ||
                  ' devices were signed out.'
        end,
        jsonb_build_object('reason', 'device_limit', 'evicted', v_evicted)
      );
    exception when others then
      raise notice 'device-limit notification failed: %', sqlerrm;
    end;
  end if;

  return v_evicted;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_freeze_conversation_participants()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_admin() then
    return new;
  end if;
  if new.participant_one_id is distinct from old.participant_one_id
     or new.participant_two_id is distinct from old.participant_two_id then
    raise exception 'The two people in a conversation cannot be changed'
      using errcode = '42501', hint = 'participants_frozen';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.fn_freeze_listing_reputation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_admin()
     or coalesce(current_setting('musafir.rating_write', true), '') = '1' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    -- A new listing starts with no reputation, whatever the client sent.
    new.rating := null;
    new.review_count := 0;
    new.is_superhost := false;
    return new;
  end if;
  if new.rating       is distinct from old.rating
     or new.review_count is distinct from old.review_count
     or new.is_superhost is distinct from old.is_superhost then
    raise exception 'A listing''s rating and badges come from reviews, not from its owner'
      using errcode = '42501', hint = 'reputation_columns_protected';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.fn_guard_disbursement_transitions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.status is distinct from new.status then
    if not ((old.status = 'pending' and new.status in ('sent', 'failed'))
            or (old.status = 'sent' and new.status = 'failed')) then
      raise exception 'a % disbursement cannot become % — record a new disbursement instead',
        old.status, new.status using errcode = '42501';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_guard_payout_method_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.channel        is distinct from old.channel
     or new.user_id     is distinct from old.user_id
     or new.account_name is distinct from old.account_name
     or new.account_number is distinct from old.account_number
     or new.bank_name   is distinct from old.bank_name
     or new.branch_name is distinct from old.branch_name
     or new.routing_number is distinct from old.routing_number then
    raise exception 'payout account details are immutable — add a new method and retire this one'
      using errcode = '42501';
  end if;

  -- Verification is granted, never regained by accident: once retired, a
  -- method cannot come back to life and start receiving money again.
  if old.retired_at is not null and new.retired_at is null then
    raise exception 'a retired payout method cannot be reinstated'
      using errcode = '42501';
  end if;

  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_guard_suspension_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_admin() then
    return new;
  end if;
  if new.suspended_at     is distinct from old.suspended_at
     or new.suspended_reason is distinct from old.suspended_reason
     or new.suspended_by     is distinct from old.suspended_by then
    raise exception 'suspension is set by an admin, not by the account'
      using errcode = '42501', hint = 'suspension_columns_protected';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_guard_verification_verdicts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_admin() then
    return new;
  end if;

  -- 133: role is a privilege, not a profile field. `admin` is never reachable
  -- from a client, and the only self-service move is starting to host.
  if new.role is distinct from old.role then
    if new.role = 'admin' then
      raise exception 'the admin role is granted by an admin, not by the user'
        using errcode = '42501', hint = 'role_change_forbidden';
    end if;
    if not (old.role = 'tenant' and new.role = 'owner') then
      raise exception 'that role change is admin-only (% -> %)', old.role, new.role
        using errcode = '42501', hint = 'role_change_forbidden';
    end if;
  end if;

  if new.address_verification_status = 'verified'
     and old.address_verification_status is distinct from 'verified' then
    raise exception 'address verification is granted by an admin visit, not by the host'
      using errcode = '42501';
  end if;

  if new.verification_status = 'verified'
     and old.verification_status is distinct from 'verified' then
    raise exception 'identity verification is granted by an admin, not by the user'
      using errcode = '42501';
  end if;

  if new.nid_verified and not coalesce(old.nid_verified, false) then
    raise exception 'nid_verified is set by an admin, not by the user'
      using errcode = '42501';
  end if;

  if new.address_verified_at is distinct from old.address_verified_at
     or new.address_verified_by is distinct from old.address_verified_by
     or new.address_visit_notes is distinct from old.address_visit_notes
     or new.address_rejection_reason is distinct from old.address_rejection_reason then
    raise exception 'address verification audit fields are admin-only'
      using errcode = '42501';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_host_ledger_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception 'ledger entries are append-only — post an adjustment instead'
    using errcode = '42501';
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_humanise_hours(p_hours integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_hours >= 48 and p_hours % 24 = 0
      then (p_hours / 24)::text || ' days'
    when p_hours = 1 then '1 hour'
    else p_hours::text || ' hours'
  end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_identity_phone(p_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  select public.fn_canonical_bd_phone(
           substring(u.email from '^phone\.([0-9]+)@musaafir\.app$'))
  from auth.users u
  where u.id = p_user_id;
$function$;

CREATE OR REPLACE FUNCTION public.fn_is_suspended(p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p_user_id is not null and exists (
    select 1 from public.profiles p where p.id = p_user_id and p.suspended_at is not null
  );
$function$;

CREATE OR REPLACE FUNCTION public.fn_listing_default_unit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.listing_units (listing_id) values (new.id);
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.fn_messages_block_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_other uuid;
begin
  -- Automated sends (pre-check-in, checkout, map, contacts) run with no uid
  -- on a booking that exists; they are the host's own words to their guest
  -- and must be delivered regardless.
  if auth.uid() is null then
    return new;
  end if;
  select case when c.participant_one_id = new.sender_id
              then c.participant_two_id else c.participant_one_id end
    into v_other
    from public.conversations c where c.id = new.conversation_id;
  if public.fn_users_blocked(new.sender_id, v_other) then
    raise exception 'You cannot message this user'
      using errcode = '42501', hint = 'blocked';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.fn_msisdn(p_canonical text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_canonical is null then null
    else '880' || substr(p_canonical, 2)
  end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_notification_category(p_type notification_type)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_type
    when 'booking_request'    then 'booking'
    when 'booking_confirmed'  then 'booking'
    when 'booking_cancelled'  then 'booking'
    when 'booking_reminder'   then 'booking'
    when 'booking_rejected'   then 'booking'
    when 'check_in_reminder'  then 'booking'
    when 'check_out_reminder' then 'booking'
    when 'checked_in'         then 'booking'
    when 'payment_received'   then 'payment'
    when 'payment_failed'     then 'payment'
    when 'refund_processed'   then 'payment'
    when 'review_received'    then 'review'
    when 'review_reminder'    then 'review'
    when 'review_prompt'      then 'review'
    when 'promotion_available' then 'promotion'
    when 'discount_expiring'  then 'promotion'
    when 'referral_reward'    then 'promotion'
    when 'new_message'        then 'message'
    when 'message_read'       then 'message'
    when 'system_alert'       then 'system'
    when 'account_update'     then 'system'
    when 'security_alert'     then 'system'
  end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_post_booking_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_host   uuid;
  v_pct    numeric;
  v_net    numeric;
  v_comm   numeric;
  v_method text;
  v_share  numeric;
begin
  -- ── Became paid ────────────────────────────────────────────────────────────
  if new.payment_status = 'paid'
     and (tg_op = 'INSERT' or old.payment_status is distinct from 'paid') then

    select l.owner_id into v_host from public.listings l where l.id = new.listing_id;
    -- An orphaned listing is a data bug, but raising here would abort the
    -- guest's settlement inside the IPN. Skip; the booking page will show the
    -- missing entry.
    if v_host is null then return null; end if;

    v_pct  := coalesce(
      (select nullif(btrim(value), '')::numeric
         from public.app_settings
        where key = 'platform_commission_pct'),
      15);
    v_net  := coalesce(new.total_price, 0);
    v_comm := round(v_net * v_pct / 100.0, 2);

    -- The guest's recorded choice (086) is authoritative; older rows fall back
    -- to the settled payments row (mark_cash_payment writes card_type 'cash'
    -- BEFORE flipping the status, so it is visible here); default online.
    v_method := coalesce(
      new.payment_method,
      (select case when p.card_type = 'cash' then 'cash' else 'online' end
         from public.payments p
        where p.booking_id = new.id and p.status = 'paid'
        order by coalesce(p.validated_at, p.created_at)
        limit 1),
      'online');

    if v_method = 'cash' then
      -- Host already holds the guest's money; they owe the platform its cut.
      if v_comm > 0 then
        insert into public.host_ledger_entries
          (host_id, booking_id, entry_type, amount,
           booking_net, commission_rate_pct, commission_amount)
        select v_host, new.id, 'booking_cash', -v_comm, v_net, v_pct, v_comm
         where not exists (
           select 1 from public.host_ledger_entries e
            where e.booking_id = new.id
              and e.entry_type in ('booking_online', 'booking_cash'));
      end if;
    else
      -- Platform holds the guest's money; it owes the host the rest.
      if v_net - v_comm > 0 then
        insert into public.host_ledger_entries
          (host_id, booking_id, entry_type, amount,
           booking_net, commission_rate_pct, commission_amount)
        select v_host, new.id, 'booking_online', v_net - v_comm, v_net, v_pct, v_comm
         where not exists (
           select 1 from public.host_ledger_entries e
            where e.booking_id = new.id
              and e.entry_type in ('booking_online', 'booking_cash'));
      end if;
    end if;
  end if;

  -- ── Paid → refunded: reverse the refunded share of whatever was posted ────
  if tg_op = 'UPDATE'
     and new.payment_status = 'refunded'
     and old.payment_status = 'paid' then
    -- null = a refund marked on a booking that closed before 140 stamped
    -- anything, or one refunded by hand while still open: whole thing back,
    -- which is what the reversal always did.
    v_share := coalesce(new.refund_pct, 100) / 100.0;
    if v_share > 0 then
      insert into public.host_ledger_entries
        (host_id, booking_id, entry_type, amount,
         booking_net, commission_rate_pct, commission_amount, note)
      select e.host_id, e.booking_id, 'booking_refund_reversal',
             -round(e.amount * v_share, 2), e.booking_net, e.commission_rate_pct,
             -round(e.commission_amount * v_share, 2),
             case when v_share < 1 then format('%s%% refund under policy', new.refund_pct) end
        from public.host_ledger_entries e
       where e.booking_id = new.id
         and e.entry_type in ('booking_online', 'booking_cash')
         and round(e.amount * v_share, 2) <> 0
         and not exists (
           select 1 from public.host_ledger_entries r
            where r.booking_id = new.id
              and r.entry_type = 'booking_refund_reversal');
    end if;
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_post_disbursement_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.kind <> 'host_payout' then
    return null;
  end if;

  if new.status = 'sent'
     and (tg_op = 'INSERT' or old.status is distinct from 'sent') then
    insert into public.host_ledger_entries
      (host_id, disbursement_id, booking_id, entry_type, amount, reference, note)
    select new.user_id, new.id, new.booking_id, 'payout', -new.amount,
           new.reference, new.note
     where not exists (
       select 1 from public.host_ledger_entries e
        where e.disbursement_id = new.id and e.entry_type = 'payout');
  end if;

  if tg_op = 'UPDATE' and new.status = 'failed' and old.status = 'sent' then
    insert into public.host_ledger_entries
      (host_id, disbursement_id, booking_id, entry_type, amount, note)
    select new.user_id, new.id, new.booking_id, 'payout_reversal', new.amount,
           new.failure_reason
     where exists (
       select 1 from public.host_ledger_entries e
        where e.disbursement_id = new.id and e.entry_type = 'payout')
       and not exists (
         select 1 from public.host_ledger_entries e
          where e.disbursement_id = new.id and e.entry_type = 'payout_reversal');
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_rate_limit_hit(p_bucket text, p_limit integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_start timestamptz;
  v_hits  integer;
begin
  perform public.fn_require_service_role();
  if p_limit < 1 or p_window_seconds < 1 or coalesce(btrim(p_bucket), '') = '' then
    raise exception 'fn_rate_limit_hit: bad arguments' using errcode = '22023';
  end if;

  v_start := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);

  insert into public.edge_rate_limits (bucket, window_start, hits)
  values (p_bucket, v_start, 1)
  on conflict (bucket, window_start) do update set hits = edge_rate_limits.hits + 1
  returning hits into v_hits;

  return jsonb_build_object(
    'allowed', v_hits <= p_limit,
    'hits', v_hits,
    'limit', p_limit,
    'retry_after_seconds',
      greatest(1, ceil(extract(epoch from (v_start + make_interval(secs => p_window_seconds) - now())))::integer));
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_refresh_listing_rating()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_listing uuid;
begin
  v_listing := case when tg_op = 'DELETE' then old.listing_id else new.listing_id end;
  if v_listing is null then return null; end if;
  perform set_config('musafir.rating_write', '1', true);
  update public.listings l
     set rating = (select round(avg(r.overall_rating), 2) from public.reviews r
                    where r.listing_id = v_listing and r.review_type = 'guest_to_host'
                      and r.is_revealed),
         review_count = (select count(*) from public.reviews r
                          where r.listing_id = v_listing and r.review_type = 'guest_to_host'
                            and r.is_revealed)
   where l.id = v_listing;
  perform set_config('musafir.rating_write', '0', true);
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.fn_refund_policy_pct(p_status booking_status, p_cancelled_by uuid, p_tenant_id uuid, p_starts_at timestamp with time zone, p_at timestamp with time zone DEFAULT now())
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_window_hours integer;
  v_late_pct     integer;
  v_raw          text;
begin
  -- A guest who did not turn up is the late-cancellation rule taken to its
  -- end: nothing back. Same answer as cancelling after check-in time.
  if p_status = 'no_show' then
    return 0;
  end if;
  if p_status <> 'cancelled' then
    return null;
  end if;

  -- Anyone but the guest cancelling (the host, an admin, a sweep) means the
  -- guest is owed everything: they did not choose this.
  if p_cancelled_by is null or p_cancelled_by is distinct from p_tenant_id then
    return 100;
  end if;

  select value into v_raw from public.app_settings where key = 'refund_full_window_hours';
  v_window_hours := case when btrim(coalesce(v_raw, '')) ~ '^[0-9]+$'
                         then btrim(v_raw)::integer else 48 end;
  select value into v_raw from public.app_settings where key = 'refund_late_pct';
  v_late_pct := case when btrim(coalesce(v_raw, '')) ~ '^[0-9]+$'
                     then least(btrim(v_raw)::integer, 100) else 50 end;

  if p_at >= p_starts_at then
    return 0;
  end if;
  if p_starts_at - p_at >= make_interval(hours => v_window_hours) then
    return 100;
  end if;
  return v_late_pct;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_refuse_suspended_writer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is not null
     and public.fn_is_suspended(v_uid)
     and not public.is_admin(v_uid) then
    raise exception 'This account is suspended'
      using errcode = '42501', hint = 'account_suspended';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_render_sms_body(p_body text, p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select replace(
           replace(coalesce(p_body, ''), '{{name}}', coalesce(nullif(trim(p_name), ''), 'there')),
           '{{first_name}}',
           coalesce(nullif(split_part(trim(coalesce(p_name, '')), ' ', 1), ''), 'there')
         );
$function$;

CREATE OR REPLACE FUNCTION public.fn_require_service_role()
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
begin
  if current_setting('request.jwt.claims', true)::jsonb ->> 'role'
     is distinct from 'service_role' then
    raise exception 'Only service_role can execute this function'
      using errcode = '42501';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_revoke_device_row(p_row_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_session uuid;
  v_user uuid;
  v_killed boolean := false;
begin
  update public.user_devices
     set revoked_at = now()
   where id = p_row_id
     and revoked_at is null
  returning session_id, user_id into v_session, v_user;

  if not found then
    return false;
  end if;

  -- Scoped to the owner as well as the id: a session_id copied onto the wrong
  -- row by some future bug must not become a way to end a stranger's session.
  if v_session is not null then
    delete from auth.sessions
     where id = v_session
       and user_id = v_user;
    v_killed := found;
  end if;

  -- False means the row is marked revoked but no live session was ended —
  -- either it had already expired, or `session_id` was never captured. The
  -- caller says so rather than claiming a sign-out that did not happen.
  return v_killed;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_sms_encoding(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when coalesce(p_text, '') ~ '^[ -~\r\n]*$' then 'gsm7' else 'ucs2' end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_sms_segments(p_text text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_len integer := length(coalesce(p_text, ''));
  v_gsm boolean := public.fn_sms_encoding(p_text) = 'gsm7';
  v_single integer;
  v_multi integer;
begin
  if v_len = 0 then
    return 0;
  end if;

  v_single := case when v_gsm then 160 else 70 end;
  -- Concatenated parts give up header room, which is why this is not simply
  -- ceil(len / single) — a 161-character GSM-7 message is two 153s, not 160+1.
  v_multi  := case when v_gsm then 153 else 67 end;

  if v_len <= v_single then
    return 1;
  end if;
  return ceil(v_len::numeric / v_multi)::integer;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_spatial_ref_sys_readonly()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- current_user, not session_user. PostgREST connects as `authenticator` and
  -- then SET ROLEs to anon/authenticated/service_role, so session_user is
  -- `authenticator` for every API request and would tell us nothing about who
  -- is actually asking. current_user is the role the statement runs as, which
  -- is the thing being gated — and it also means an impersonation test
  -- (`set local role anon`) exercises the same path a real request does.
  if current_user in ('postgres', 'supabase_admin')
     or coalesce((select rolsuper from pg_roles
                   where rolname = current_user), false)
  then
    -- Platform maintenance still has to work: `alter extension postgis update`
    -- rewrites this table, and a restore repopulates it. Both run as an owner
    -- or a superuser, neither of which is reachable through PostgREST.
    if tg_level = 'STATEMENT' then
      return null;  -- ignored for BEFORE TRUNCATE; OLD/NEW are unassigned here
    end if;
    return case tg_op when 'DELETE' then old else new end;
  end if;

  raise exception using
    errcode = '42501',
    message = format(
      'spatial_ref_sys is read-only reference data (attempted %s as %s)',
      tg_op, current_user),
    hint = 'PostGIS reference data is maintained by the platform, not the API.';
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_stamp_refund_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_pct integer;
begin
  if new.booking_status in ('cancelled', 'no_show')
     and old.booking_status not in ('cancelled', 'no_show')
     and new.payment_status = 'paid' then
    v_pct := public.fn_refund_policy_pct(
      new.booking_status,
      -- enforce_booking_update_rules has already stamped cancelled_by for a
      -- caller who omitted it; a no-show carries no canceller.
      new.cancelled_by, new.tenant_id, new.starts_at, now());
    new.refund_pct    := v_pct;
    new.refund_amount := round(coalesce(new.total_price, 0) * v_pct / 100.0, 2);
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_touch_disbursements()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_users_blocked(p_a uuid, p_b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p_a is not null and p_b is not null and exists (
    select 1 from public.user_blocks ub
    where (ub.blocker_id = p_a and ub.blocked_id = p_b)
       or (ub.blocker_id = p_b and ub.blocked_id = p_a)
  );
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_app_setting()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  case new.key
    when 'search_radius_tiers_m' then
      perform public.fn_validate_setting_search_radius_tiers(new.value);
    when 'search_landmark_radius_m', 'search_nearest_fallback_limit' then
      perform public.fn_validate_setting_search_scalar(new.key, new.value);
    when 'payout_channels_enabled' then
      perform public.fn_validate_setting_payout_channels(new.value);
    when 'address_disclosure_grace_days' then
      perform public.fn_validate_setting_address_grace(new.value);
    when 'platform_commission_pct' then
      perform public.fn_validate_setting_commission_pct(new.value);
    when 'active_theme' then
      perform public.fn_validate_setting_active_theme(new.value);
    when 'booking_accept_window_hours' then
      perform public.fn_validate_setting_booking_accept_hours(new.value);
    when 'android_min_version_code' then
      perform public.fn_validate_setting_android_min_version_code(new.value);
    when 'max_devices_per_user' then
      perform public.fn_validate_setting_max_devices(new.value);
    when 'sms_bulk_max_recipients' then
      perform public.fn_validate_setting_sms_max_recipients(new.value);
    when 'notification_bulk_max_recipients' then
      perform public.fn_validate_setting_notification_max_recipients(new.value);
    when 'refund_full_window_hours' then
      perform public.fn_validate_setting_refund_window_hours(new.value);
    when 'refund_late_pct' then
      perform public.fn_validate_setting_refund_late_pct(new.value);
    when 'hourly_policy' then
      perform public.fn_validate_setting_hourly_policy(new.value);
    else
      null;
  end case;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_active_theme(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v text := lower(btrim(coalesce(p_value, '')));
begin
  -- Empty is refused rather than treated as "the default". The app does read an
  -- absent row as the default, but an admin who cleared the field almost
  -- certainly meant to type something, and silently reverting their theme is a
  -- worse outcome than telling them.
  if v = '' then
    raise exception 'active_theme cannot be empty — name a theme, e.g. ocean_teal'
      using errcode = '22023';
  end if;
  if v not in ('ocean_teal', 'indigo_crimson', 'crimson_ember', 'coral_ink') then
    raise exception 'unknown theme "%"; valid: ocean_teal, indigo_crimson, crimson_ember, coral_ink', v
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_address_grace(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if btrim(coalesce(p_value, '')) !~ '^[0-9]+$' then
    raise exception 'address_disclosure_grace_days must be a whole number of days'
      using errcode = '22023';
  end if;
  n := btrim(p_value)::integer;
  -- 0 is allowed and means "revoke at checkout". The ceiling exists because a
  -- value in the thousands is indistinguishable from the permanent disclosure
  -- migration 103 exists to remove.
  if n > 365 then
    raise exception 'address_disclosure_grace_days: % is longer than a year; use a shorter window', n
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_android_min_version_code(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare n bigint;
begin
  if btrim(coalesce(p_value, '')) !~ '^[0-9]+$' then
    raise exception 'android_min_version_code must be a whole versionCode (0 disables forced updates)'
      using errcode = '22023';
  end if;
  n := btrim(p_value)::bigint;
  -- 2100000000 is Play's own ceiling for a versionCode, so a larger number
  -- cannot name a real release and could only ever be a typo. Rejected at the
  -- keystroke rather than clamped, because silently storing a different number
  -- than the admin typed is the wrong answer for a setting this sharp.
  if n > 2100000000 then
    raise exception 'android_min_version_code: % is above Play''s maximum versionCode (2100000000)', n
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_booking_accept_hours(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if btrim(coalesce(p_value, '')) !~ '^[0-9]+$' then
    raise exception 'booking_accept_window_hours must be a whole number of hours'
      using errcode = '22023';
  end if;
  n := btrim(p_value)::integer;
  -- Floor of 1: zero would expire a request in the same sweep that created it,
  -- so hosts would be "declining" bookings they were never shown. Ceiling of
  -- 168 (7 days): past that the guest's own dates have usually come and gone,
  -- and the request is dead of old age rather than of the host's silence.
  if n < 1 or n > 168 then
    raise exception 'booking_accept_window_hours: % is outside 1–168 hours (1 hour to 7 days)', n
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_commission_pct(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if btrim(coalesce(p_value, '')) !~ '^[0-9]{1,3}(\.[0-9]{1,2})?$' then
    raise exception 'platform_commission_pct must be a number like 15 or 12.5'
      using errcode = '22023';
  end if;
  if btrim(p_value)::numeric > 100 then
    raise exception 'platform_commission_pct: % is outside 0–100', btrim(p_value)
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_hourly_policy(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_doc    jsonb;
  v_key    text;
  v_entry  jsonb;
  v_min    integer;
  v_slot   jsonb;
  v_prev   integer;
  v_n      integer;
begin
  begin
    v_doc := p_value::jsonb;
  exception when others then
    raise exception 'hourly_policy must be a JSON object' using errcode = '22023';
  end;
  if jsonb_typeof(v_doc) <> 'object' then
    raise exception 'hourly_policy must be a JSON object' using errcode = '22023';
  end if;

  for v_key, v_entry in select * from jsonb_each(v_doc) loop
    -- The enum plus 'hotel', which 149 adds; until then the literal keeps the
    -- default row storable. IMMUTABLE forbids enum_range here, so the list is
    -- spelled out -- a new listing type must be added to it.
    if v_key not in ('seat', 'room', 'fullHouse', 'turf', 'hotel') then
      raise exception 'hourly_policy: "%" is not a listing type', v_key
        using errcode = '22023';
    end if;
    if jsonb_typeof(v_entry) <> 'object' then
      raise exception 'hourly_policy: % must be an object', v_key using errcode = '22023';
    end if;
    if jsonb_typeof(v_entry -> 'enabled') is distinct from 'boolean' then
      raise exception 'hourly_policy: %.enabled must be true or false', v_key
        using errcode = '22023';
    end if;
    if jsonb_typeof(v_entry -> 'min_hours') is distinct from 'number'
       or (v_entry ->> 'min_hours') !~ '^[0-9]+$' then
      raise exception 'hourly_policy: %.min_hours must be a whole number of hours', v_key
        using errcode = '22023';
    end if;
    v_min := (v_entry ->> 'min_hours')::integer;
    if v_min < 1 or v_min > 168 then
      raise exception 'hourly_policy: %.min_hours is % — must be 1 to 168', v_key, v_min
        using errcode = '22023';
    end if;
    if v_entry ? 'slots' and jsonb_typeof(v_entry -> 'slots') <> 'null' then
      if jsonb_typeof(v_entry -> 'slots') <> 'array'
         or jsonb_array_length(v_entry -> 'slots') = 0 then
        raise exception 'hourly_policy: %.slots must be null or a list of hours', v_key
          using errcode = '22023';
      end if;
      v_prev := null;
      for v_slot in select * from jsonb_array_elements(v_entry -> 'slots') loop
        if jsonb_typeof(v_slot) <> 'number' or (v_slot #>> '{}') !~ '^[0-9]+$' then
          raise exception 'hourly_policy: %.slots holds "%", not a whole number of hours',
            v_key, v_slot #>> '{}' using errcode = '22023';
        end if;
        v_n := (v_slot #>> '{}')::integer;
        -- A slot below the floor could never be booked; one above a week is a
        -- nightly stay wearing the wrong hat.
        if v_n < v_min or v_n > 168 then
          raise exception 'hourly_policy: %.slots: % h is outside %–168 h', v_key, v_n, v_min
            using errcode = '22023';
        end if;
        -- Ascending and distinct, so the guest's chips read in order and no
        -- duration is offered twice.
        if v_prev is not null and v_n <= v_prev then
          raise exception 'hourly_policy: %.slots must ascend (% came after %)', v_key, v_n, v_prev
            using errcode = '22023';
        end if;
        v_prev := v_n;
      end loop;
    end if;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_max_devices(p_value text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  if p_value !~ '^[0-9]+$' then
    raise exception 'max_devices_per_user must be a whole number'
      using errcode = '22023';
  end if;

  -- The ceiling is not arbitrary: it is high enough that no honest user meets
  -- it and low enough that a typo cannot make the setting meaningless.
  if p_value::int > 20 then
    raise exception 'max_devices_per_user must be 20 or fewer'
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_notification_max_recipients(p_value text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  if p_value !~ '^[0-9]{1,6}$' then
    raise exception 'notification_bulk_max_recipients must be a whole number (0 disables bulk notifications)'
      using errcode = '22023';
  end if;
  if p_value::integer > 100000 then
    raise exception 'notification_bulk_max_recipients cannot exceed 100000'
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_payout_channels(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare part text;
begin
  if coalesce(btrim(p_value), '') = '' then
    raise exception 'payout_channels_enabled cannot be empty — stop offering a channel by naming the others, not by clearing the list'
      using errcode = '22023';
  end if;
  foreach part in array string_to_array(p_value, ',') loop
    begin
      perform btrim(part)::public.payout_channel;
    exception when others then
      raise exception 'unknown payout channel "%"; valid: bkash, nagad, rocket, bank',
        btrim(part) using errcode = '22023';
    end;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_refund_late_pct(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if btrim(coalesce(p_value, '')) !~ '^[0-9]+$' then
    raise exception 'refund_late_pct must be a whole-number percentage'
      using errcode = '22023';
  end if;
  n := btrim(p_value)::integer;
  if n > 100 then
    raise exception 'refund_late_pct: % is more than 100', n using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_refund_window_hours(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if btrim(coalesce(p_value, '')) !~ '^[0-9]+$' then
    raise exception 'refund_full_window_hours must be a whole number of hours'
      using errcode = '22023';
  end if;
  n := btrim(p_value)::integer;
  -- 0 is a real policy ("full refund right up to check-in"); 720 hours is
  -- thirty days, past which the window is longer than most stays are booked
  -- ahead and every cancellation would be a partial one.
  if n > 720 then
    raise exception 'refund_full_window_hours: % is more than 720 hours (30 days)', n
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_search_radius_tiers(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare parts text[]; part text; n integer; prev integer := null;
begin
  parts := string_to_array(coalesce(p_value, ''), ',');
  if array_length(parts, 1) is null then
    raise exception 'search_radius_tiers_m needs at least one radius in metres'
      using errcode = '22023';
  end if;
  if array_length(parts, 1) > 6 then
    raise exception 'search_radius_tiers_m allows at most 6 tiers (got %)',
      array_length(parts, 1) using errcode = '22023';
  end if;
  foreach part in array parts loop
    if btrim(part) !~ '^[0-9]+$' then
      raise exception 'search_radius_tiers_m: "%" is not a whole number of metres',
        btrim(part) using errcode = '22023';
    end if;
    n := btrim(part)::integer;
    if n < 100 or n > 200000 then
      raise exception 'search_radius_tiers_m: % m is outside 100–200000 m', n
        using errcode = '22023';
    end if;
    -- Ascending order is load-bearing: the RPC takes the smallest tier that
    -- contains a match, so an unsorted list would pick the wrong ring.
    if prev is not null and n <= prev then
      raise exception 'search_radius_tiers_m must ascend (% came after %)', n, prev
        using errcode = '22023';
    end if;
    prev := n;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_search_scalar(p_key text, p_value text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if btrim(coalesce(p_value, '')) !~ '^[0-9]+$' then
    raise exception '% must be a whole number', p_key using errcode = '22023';
  end if;
  n := btrim(p_value)::integer;
  if p_key = 'search_landmark_radius_m' and (n < 100 or n > 200000) then
    raise exception 'search_landmark_radius_m: % m is outside 100–200000 m', n
      using errcode = '22023';
  end if;
  if p_key = 'search_nearest_fallback_limit' and (n < 1 or n > 100) then
    raise exception 'search_nearest_fallback_limit: % is outside 1–100', n
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_validate_setting_sms_max_recipients(p_value text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  if p_value !~ '^[0-9]{1,6}$' then
    raise exception 'sms_bulk_max_recipients must be a whole number of recipients (0 disables bulk SMS)'
      using errcode = '22023';
  end if;
  if p_value::integer > 100000 then
    raise exception 'sms_bulk_max_recipients cannot exceed 100000'
      using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_auth_user_id_by_email(p_email text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select id from auth.users where email = p_email limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.get_booking_contacts(p_booking_id uuid)
 RETURNS TABLE(guest_name text, guest_phone text, host_name text, host_phone text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant UUID;
    v_host UUID;
    v_status TEXT;
begin
    select b.tenant_id, l.owner_id, b.booking_status::text
    into v_tenant, v_host, v_status
    from public.bookings b
    join public.listings l on l.id = b.listing_id
    where b.id = p_booking_id;

    if v_tenant is null then return; end if;

    -- Only the two participants may read contacts.
    if auth.uid() is null or auth.uid() not in (v_tenant, v_host) then
        raise exception 'Not authorized';
    end if;

    -- Contacts are revealed only once the booking is locked in.
    if v_status not in ('confirmed', 'active', 'completed') then
        return;
    end if;

    return query
    select coalesce(b.tenant_name, gp.full_name, 'Guest'),
           coalesce(public.fn_identity_phone(gp.id), gp.mobile),
           coalesce(hp.full_name, 'Host'),
           coalesce(public.fn_identity_phone(hp.id), hp.mobile)
    from public.bookings b
    join public.listings l on l.id = b.listing_id
    left join public.profiles gp on gp.id = b.tenant_id
    left join public.profiles hp on hp.id = l.owner_id
    where b.id = p_booking_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_conversation_participants(p_conversation_id uuid)
 RETURNS TABLE(user_id uuid, role text, joined_at timestamp with time zone, user_name text, avatar_url text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    cp.user_id,
    cp.role,
    cp.joined_at,
    p.full_name as user_name,
    p.avatar_url
  FROM public.conversation_participants cp
  LEFT JOIN public.profiles p ON p.id = cp.user_id
  WHERE cp.conversation_id = p_conversation_id
    AND cp.is_active = true
  ORDER BY cp.joined_at;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_host_leaderboard(p_period text DEFAULT 'all_time'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(rank bigint, host_id uuid, name text, avatar_url text, score numeric, rating numeric, review_count bigint, completed_bookings bigint, prev_rank bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT * FROM public.host_leaderboard_ranked(p_period)
  ORDER BY rank
  LIMIT GREATEST(p_limit, 0) OFFSET GREATEST(p_offset, 0);
$function$;

CREATE OR REPLACE FUNCTION public.get_host_rank(p_host_id uuid, p_period text DEFAULT 'all_time'::text)
 RETURNS TABLE(rank bigint, host_id uuid, name text, avatar_url text, score numeric, rating numeric, review_count bigint, completed_bookings bigint, prev_rank bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT * FROM public.host_leaderboard_ranked(p_period)
  WHERE host_id = p_host_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_listing_owner(p_listing_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT l.owner_id
    FROM public.listings l
    WHERE l.id = p_listing_id
    AND (
        l.is_active
        OR EXISTS (
            SELECT 1 FROM public.bookings b
            WHERE b.listing_id = l.id
            AND b.tenant_id = auth.uid()
        )
    );
$function$;

CREATE OR REPLACE FUNCTION public.get_or_create_conversation(user_one uuid, user_two uuid, p_booking_id uuid DEFAULT NULL::uuid, p_listing_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  conv_id uuid;
begin
  -- Enforce participant membership ONLY for a real authenticated user. A NULL
  -- auth.uid() means a trusted SECURITY DEFINER / cron caller (anon has no
  -- EXECUTE grant, so it can never reach here unauthenticated).
  if auth.uid() is not null and auth.uid() not in (user_one, user_two) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  -- 138: same wall as create_marketplace_booking. Only for a real caller —
  -- the cron-driven automated messages (pre-check-in, checkout) run with a
  -- null uid on a booking that already exists and must still be delivered.
  if auth.uid() is not null
     and (public.fn_is_suspended(user_one) or public.fn_is_suspended(user_two)) then
    raise exception 'This account is suspended'
      using errcode = '42501', hint = 'account_suspended';
  end if;

  if auth.uid() is not null and public.fn_users_blocked(user_one, user_two) then
    raise exception 'You cannot message this user'
      using errcode = '42501', hint = 'blocked';
  end if;

  select id into conv_id from public.conversations
  where least(participant_one_id, participant_two_id) = least(user_one, user_two)
    and greatest(participant_one_id, participant_two_id) = greatest(user_one, user_two)
  limit 1;

  if conv_id is null then
    insert into public.conversations (participant_one_id, participant_two_id, booking_id, listing_id)
    values (user_one, user_two, p_booking_id, p_listing_id)
    returning id into conv_id;
  elsif p_booking_id is not null or p_listing_id is not null then
    -- The single thread follows the latest booking/listing context.
    update public.conversations
    set booking_id = coalesce(p_booking_id, booking_id),
        listing_id = coalesce(p_listing_id, listing_id),
        status = 'active',
        updated_at = now()
    where id = conv_id;
  end if;

  return conv_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_unread_count(p_conversation_id uuid, p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  last_read_at TIMESTAMPTZ;
  unread INTEGER;
BEGIN
  SELECT rc.last_read_at INTO last_read_at
  FROM public.read_cursors rc
  WHERE rc.conversation_id = p_conversation_id AND rc.user_id = p_user_id;

  IF last_read_at IS NULL THEN
    SELECT COUNT(*) INTO unread
    FROM public.messages m
    WHERE m.conversation_id = p_conversation_id
      AND m.sender_id != p_user_id
      AND m.deleted_at IS NULL;
  ELSE
    SELECT COUNT(*) INTO unread
    FROM public.messages m
    WHERE m.conversation_id = p_conversation_id
      AND m.sender_id != p_user_id
      AND m.created_at > last_read_at
      AND m.deleted_at IS NULL;
  END IF;

  RETURN COALESCE(unread, 0);
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_unread_notification_count(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if auth.uid() is not null and auth.uid() <> p_user_id then
    raise exception 'Not authorized';
  end if;
  return (
    select count(*)::integer
    from notifications
    where user_id = p_user_id and status = 'unread'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_nid_document_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user not in ('postgres','service_role','supabase_admin') and not public.is_admin()
    and ((tg_op<>'DELETE' and new.document_type in ('nid_front','nid_back'))
      or (tg_op<>'INSERT' and old.document_type in ('nid_front','nid_back'))) then
    raise exception 'Use the NID submission flow' using errcode='42501';
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mobile TEXT;
BEGIN
  -- Get mobile from metadata, phone, or generate a unique placeholder
  v_mobile := COALESCE(
    new.raw_user_meta_data ->> 'mobile',
    new.phone,
    'pending_' || new.id::text  -- Unique placeholder using user ID
  );

  INSERT INTO public.profiles (
    id,
    role,
    full_name,
    mobile,
    registration_method,
    phone_verified,
    nid,
    nid_verified
  )
  VALUES (
    new.id,
    COALESCE((new.raw_user_meta_data ->> 'role')::public.app_role, 'tenant'),
    COALESCE(new.raw_user_meta_data ->> 'full_name', 'New User'),
    v_mobile,
    COALESCE(new.raw_user_meta_data ->> 'registration_method', 'phone'),
    CASE WHEN new.phone IS NOT NULL OR new.raw_user_meta_data ->> 'mobile' IS NOT NULL THEN TRUE ELSE FALSE END,
    new.raw_user_meta_data ->> 'nid',
    COALESCE((new.raw_user_meta_data ->> 'nid_verified')::boolean, FALSE)
  )
  ON CONFLICT (id) DO UPDATE SET
    full_name = COALESCE(EXCLUDED.full_name, profiles.full_name),
    mobile = COALESCE(EXCLUDED.mobile, profiles.mobile),
    updated_at = timezone('utc', now());
  RETURN new;
END;
$function$;

CREATE OR REPLACE FUNCTION public.has_approved_face_or_identity(p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Signature kept: create_marketplace_booking and can_publish_listings call it.
  select exists(select 1 from public.profiles where id=p_user_id
    and verification_status='verified' and nid_verified)
    and (not public.face_review_required()
      or coalesce((select status='approved' from public.face_verification_attempts
        where user_id=p_user_id order by created_at desc,id desc limit 1),false));
$function$;

CREATE OR REPLACE FUNCTION public.host_leaderboard_ranked(p_period text)
 RETURNS TABLE(rank bigint, host_id uuid, name text, avatar_url text, score numeric, rating numeric, review_count bigint, completed_bookings bigint, prev_rank bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH params AS (
    SELECT
      CASE WHEN p_period = 'monthly'
        THEN date_trunc('month', timezone('utc', now())) END AS start_ts,
      CASE WHEN p_period = 'monthly'
        THEN to_char(
          date_trunc('month', timezone('utc', now())) - interval '1 month',
          'YYYY-MM') END AS prev_period
  ),
  rev AS (
    SELECT r.reviewee_id AS host_id, COUNT(*) AS review_count,
           AVG(r.overall_rating) AS avg_rating
    FROM public.reviews r, params
    WHERE r.review_type = 'guest_to_host'
      AND (params.start_ts IS NULL OR r.created_at >= params.start_ts)
    GROUP BY r.reviewee_id
  ),
  bk AS (
    SELECT l.owner_id AS host_id, COUNT(*) AS completed_bookings
    FROM public.bookings b
    JOIN public.listings l ON l.id = b.listing_id, params
    WHERE b.booking_status = 'completed'
      AND (params.start_ts IS NULL OR b.ends_at >= params.start_ts)
    GROUP BY l.owner_id
  ),
  gmean AS (
    SELECT COALESCE(AVG(r.overall_rating), 4.5) AS m
    FROM public.reviews r, params
    WHERE r.review_type = 'guest_to_host'
      AND (params.start_ts IS NULL OR r.created_at >= params.start_ts)
  ),
  scored AS (
    SELECT
      p.id AS host_id, p.full_name AS name, p.avatar_url,
      COALESCE(rev.review_count, 0) AS review_count,
      COALESCE(rev.avg_rating, 0) AS avg_rating,
      COALESCE(bk.completed_bookings, 0) AS completed_bookings,
      COALESCE(p.response_rate, 0) AS response_rate,
      ((5 * gmean.m) + COALESCE(rev.avg_rating, 0) * COALESCE(rev.review_count, 0))
        / (5 + COALESCE(rev.review_count, 0)) AS bayes
    FROM public.profiles p
    CROSS JOIN gmean
    LEFT JOIN rev ON rev.host_id = p.id
    LEFT JOIN bk ON bk.host_id = p.id
    WHERE p.is_host = TRUE
      AND COALESCE(p.leaderboard_opt_out, FALSE) = FALSE
      AND COALESCE(bk.completed_bookings, 0) >= 1
  ),
  ranked AS (
    SELECT
      ROW_NUMBER() OVER (
        ORDER BY score_calc DESC, review_count DESC, completed_bookings DESC
      ) AS rank,
      host_id, name, avatar_url, score_calc AS score,
      ROUND(avg_rating, 1) AS rating, review_count, completed_bookings
    FROM (
      SELECT host_id, name, avatar_url, review_count, completed_bookings, avg_rating,
        ROUND(
            50 * (bayes / 5.0)
          + 30 * (LEAST(completed_bookings, 50)::numeric / 50.0)
          + 20 * (response_rate / 100.0)
        , 1) AS score_calc
      FROM scored
    ) s
  )
  SELECT
    r.rank, r.host_id, r.name, r.avatar_url, r.score, r.rating,
    r.review_count, r.completed_bookings,
    snap.rank AS prev_rank
  FROM ranked r
  CROSS JOIN params
  LEFT JOIN public.host_leaderboard_snapshots snap
    ON snap.host_id = r.host_id AND snap.period = params.prev_period;
$function$;

CREATE OR REPLACE FUNCTION public.hourly_booking_check(p_listing_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_l       public.listings%rowtype;
  v_policy  jsonb;
  v_hours   integer;
  v_floor   integer;
  v_slots   integer[];
  v_start_l timestamp;
  v_end_l   timestamp;
  v_end_t   time;
begin
  select * into v_l from public.listings where id = p_listing_id;
  if not found then
    raise exception 'Listing not found' using errcode = 'P0002';
  end if;
  v_policy := public.hourly_policy_for(v_l.listing_type::text);

  if not coalesce((v_policy ->> 'enabled')::boolean, true) then
    raise exception 'Hourly bookings are not offered for this kind of listing'
      using errcode = '22023', hint = 'hourly_disabled';
  end if;

  -- Same derivation as the RPC: whole hours from the interval, rounded, so a
  -- client cannot send 5h59m and call it 5.
  v_hours := round(extract(epoch from (p_ends_at - p_starts_at)) / 3600.0);

  v_floor := greatest(coalesce((v_policy ->> 'min_hours')::integer, 1),
                      coalesce(v_l.min_hours, 1));
  if v_hours < v_floor then
    raise exception 'Minimum booking is % hour%', v_floor, case when v_floor = 1 then '' else 's' end
      using errcode = '22023', hint = 'hourly_min';
  end if;
  if v_l.max_hours is not null and v_hours > v_l.max_hours then
    raise exception 'Maximum booking is % hour%', v_l.max_hours, case when v_l.max_hours = 1 then '' else 's' end
      using errcode = '22023', hint = 'hourly_max';
  end if;

  -- The host's list wins outright when set; otherwise the platform's. Not
  -- intersected: a host narrowing [6,12] to [6] is the common case and an
  -- intersection would make a host offering [4] on a slotted type silently
  -- offer nothing.
  if v_l.hourly_slots is not null then
    v_slots := v_l.hourly_slots;
  elsif jsonb_typeof(v_policy -> 'slots') = 'array' then
    select array_agg(x::integer order by x::integer) into v_slots
      from jsonb_array_elements_text(v_policy -> 'slots') as x;
  end if;
  if v_slots is not null and not (v_hours = any(v_slots)) then
    raise exception 'Choose one of the offered durations: % hours',
      array_to_string(v_slots, ', ')
      using errcode = '22023', hint = 'hourly_slot';
  end if;

  -- Day-use window, on one Asia/Dhaka calendar day. A stay ending exactly at
  -- midnight is "24:00" of the day it started, which `time` can hold.
  if v_l.hourly_window_start is not null then
    v_start_l := p_starts_at at time zone 'Asia/Dhaka';
    v_end_l   := p_ends_at   at time zone 'Asia/Dhaka';
    v_end_t   := case when v_end_l::time = time '00:00' and v_end_l::date = v_start_l::date + 1
                      then time '24:00' else v_end_l::time end;
    if (v_end_l::date <> v_start_l::date and v_end_t <> time '24:00')
       or v_start_l::time < v_l.hourly_window_start
       or v_end_t > v_l.hourly_window_end then
      raise exception 'Hourly stays here run between % and %',
        to_char(v_l.hourly_window_start, 'HH24:MI'), to_char(v_l.hourly_window_end, 'HH24:MI')
        using errcode = '22023', hint = 'hourly_window';
    end if;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.hourly_policy_defaults()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select '{
    "seat":      {"enabled": true, "min_hours": 1, "slots": null},
    "room":      {"enabled": true, "min_hours": 1, "slots": null},
    "fullHouse": {"enabled": true, "min_hours": 3, "slots": null},
    "turf":      {"enabled": true, "min_hours": 1, "slots": null},
    "hotel":     {"enabled": true, "min_hours": 6, "slots": [6, 12]}
  }'::jsonb
$function$;

CREATE OR REPLACE FUNCTION public.hourly_policy_for(p_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_raw   text;
  v_doc   jsonb;
  v_entry jsonb;
begin
  select value into v_raw from public.app_settings where key = 'hourly_policy';
  if v_raw is not null then
    begin
      v_doc := v_raw::jsonb;
    exception when others then
      v_doc := null;
    end;
  end if;
  v_entry := case when jsonb_typeof(v_doc) = 'object' then v_doc -> p_type end;
  if v_entry is null or jsonb_typeof(v_entry) <> 'object' then
    v_entry := public.hourly_policy_defaults() -> p_type;
  end if;
  -- An unknown type (should not happen -- listing_type is an enum) gets the
  -- loosest sane policy rather than an error.
  return coalesce(v_entry, '{"enabled": true, "min_hours": 1, "slots": null}'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_admin(p_uid uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.profiles where id = p_uid and role = 'admin'
  );
$function$;

CREATE OR REPLACE FUNCTION public.is_booking_available(p_listing_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.listing_rooms_left(p_listing_id, p_starts_at, p_ends_at) > 0;
$function$;

CREATE OR REPLACE FUNCTION public.is_conversation_member(p_conversation_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from public.conversation_participants cp
    where cp.conversation_id = p_conversation_id
      and cp.user_id = p_user_id
      and cp.is_active = true
  );
$function$;

CREATE OR REPLACE FUNCTION public.listing_area_address(p_area text, p_city text, p_postal_code text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select nullif(
    concat_ws(', ',
      nullif(btrim(coalesce(p_area, '')), ''),
      nullif(btrim(concat_ws(' ',
        nullif(btrim(coalesce(p_city, '')), ''),
        nullif(btrim(coalesce(p_postal_code, '')), '')
      )), '')
    ),
  '');
$function$;

CREATE OR REPLACE FUNCTION public.listing_blocked_ranges(p_listing_id uuid)
 RETURNS TABLE(starts_at timestamp with time zone, ends_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select blk.starts_at, blk.ends_at
  from public.listing_availability_blocks blk
  where blk.listing_id = p_listing_id
    and blk.ends_at > timezone('utc', now())
  order by blk.starts_at;
$function$;

CREATE OR REPLACE FUNCTION public.listing_rooms_left(p_listing_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when exists (
      select 1 from public.listing_availability_blocks blk
      where blk.listing_id = p_listing_id and blk.unit_id is null
        and tstzrange(blk.starts_at, blk.ends_at, '[)') && tstzrange(p_starts_at, p_ends_at, '[)'))
    then 0
    else (
      select count(*)::int from public.listing_units u
      where u.listing_id = p_listing_id and u.is_active
        and not exists (
          select 1 from public.bookings b
          where b.unit_id = u.id
            and b.booking_status in ('pending', 'confirmed', 'active')
            and tstzrange(b.starts_at, b.ends_at, '[)') && tstzrange(p_starts_at, p_ends_at, '[)'))
        and not exists (
          select 1 from public.listing_availability_blocks blk
          where blk.unit_id = u.id
            and tstzrange(blk.starts_at, blk.ends_at, '[)') && tstzrange(p_starts_at, p_ends_at, '[)')))
  end;
$function$;

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  affected_rows integer;
begin
  if auth.uid() is not null and auth.uid() <> p_user_id then
    raise exception 'Not authorized';
  end if;
  update notifications
  set status = 'read', read_at = now()
  where user_id = p_user_id and status = 'unread';
  get diagnostics affected_rows = row_count;
  return affected_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION public.mark_cash_payment(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_tenant uuid;
  v_listing uuid;
  v_total numeric;
  v_pay_status text;
  v_owner uuid;
  v_title text;
begin
  if v_uid is null then raise exception 'Not authenticated'; end if;

  select tenant_id, listing_id, total_price, payment_status
    into v_tenant, v_listing, v_total, v_pay_status
    from public.bookings where id = p_booking_id;
  if v_tenant is null then raise exception 'Booking not found'; end if;

  select owner_id, title into v_owner, v_title
    from public.listings where id = v_listing;
  if v_owner is null or v_owner <> v_uid then
    raise exception 'Only the host can confirm a cash payment' using errcode = '42501';
  end if;

  -- Idempotent: already settled (online or a prior cash confirm) → no-op.
  if v_pay_status = 'paid' then return; end if;

  insert into public.payments (
    booking_id, user_id, tran_id, amount, currency, status,
    card_type, validated_at, gateway_response
  ) values (
    p_booking_id, v_tenant, 'CASH-' || p_booking_id::text,
    coalesce(v_total, 0), 'BDT', 'paid',
    'cash', now(), jsonb_build_object('method', 'cash', 'confirmed_by', v_uid)
  )
  on conflict (tran_id) do nothing;

  -- 132: see set_booking_payment_method.
  perform set_config('musafir.settlement_write', '1', true);
  update public.bookings set payment_status = 'paid' where id = p_booking_id;
  perform set_config('musafir.settlement_write', '0', true);

  -- Let the guest see the confirmation live (reliable notifications channel).
  insert into public.notifications (user_id, type, title, body, action_url)
  values (
    v_tenant, 'payment_received', 'Cash payment confirmed',
    'The host confirmed your cash payment for ' || coalesce(v_title, 'your booking') || '.',
    '/trips'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.max_devices_per_user()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_raw text;
begin
  select value into v_raw from public.app_settings
   where key = 'max_devices_per_user';

  if v_raw is null or v_raw !~ '^[0-9]+$' then
    return 0;
  end if;

  if v_raw::int > 20 then
    return 0;
  end if;

  return v_raw::int;
end;
$function$;

CREATE OR REPLACE FUNCTION public.migrate_conversation_participants()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  migrated INTEGER := 0;
  conv RECORD;
BEGIN
  FOR conv IN SELECT id, participant_one_id, participant_two_id FROM public.conversations LOOP
    -- Insert participant one if not exists
    INSERT INTO public.conversation_participants (conversation_id, user_id, role)
    VALUES (conv.id, conv.participant_one_id, 'guest')
    ON CONFLICT (conversation_id, user_id) DO NOTHING;

    -- Insert participant two if not exists
    INSERT INTO public.conversation_participants (conversation_id, user_id, role)
    VALUES (conv.id, conv.participant_two_id, 'guest')
    ON CONFLICT (conversation_id, user_id) DO NOTHING;

    migrated := migrated + 1;
  END LOOP;

  RETURN migrated;
END;
$function$;

CREATE OR REPLACE FUNCTION public.nearby_landmarks(p_lat double precision, p_lng double precision, p_limit integer DEFAULT 5, p_type text DEFAULT NULL::text)
 RETURNS SETOF jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select to_jsonb(x) from (
    select id, name, type, city, area, latitude, longitude,
           ST_Distance(geog, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography) as distance_m
    from public.landmarks
    where is_active and (p_type is null or type = p_type)
    order by geog <-> ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
    limit greatest(coalesce(p_limit, 5), 0)
  ) x;
$function$;

CREATE OR REPLACE FUNCTION public.nid_verification_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.profiles;
begin
  if auth.uid() is null then raise exception 'Sign in first' using errcode='42501'; end if;
  select * into strict p from public.profiles where id=auth.uid();
  return jsonb_build_object('status',case when p.verification_status='verified' and not coalesce(p.nid_verified,false)
    then 'none' else p.verification_status::text end,
    'document_type',p.id_document_type,
    'note',(select rejection_reason from public.owner_documents where user_id=p.id
      and document_type in ('nid_front','nid_back') and rejection_reason is not null order by uploaded_at desc limit 1));
end;
$function$;

CREATE OR REPLACE FUNCTION public.normalise_bd_msisdn(p_raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when d ~ '^8801[3-9][0-9]{8}$' then '0' || right(d, 10)
    when d ~ '^1[3-9][0-9]{8}$'    then '0' || d
    else d
  end
  from (select regexp_replace(coalesce(p_raw, ''), '[^0-9]', '', 'g') as d) s;
$function$;

CREATE OR REPLACE FUNCTION public.notification_bulk_max_recipients()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v text;
begin
  select value into v from public.app_settings
   where key = 'notification_bulk_max_recipients';
  if v is null or v !~ '^[0-9]{1,6}$' then
    return 2000;
  end if;
  return least(v::integer, 100000);
end;
$function$;

CREATE OR REPLACE FUNCTION public.notify_on_booking_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_host_id UUID;
    v_guest_id UUID;
    v_listing_title TEXT;
    v_guest_name TEXT;
    v_starts_at TEXT;
    v_ends_at TEXT;
BEGIN
    -- Get listing owner (host) and title
    SELECT l.owner_id, l.title
    INTO v_host_id, v_listing_title
    FROM public.listings l
    WHERE l.id = NEW.listing_id;

    -- Get guest name from profiles
    SELECT COALESCE(p.full_name, p.mobile, 'A guest')
    INTO v_guest_name
    FROM public.profiles p
    WHERE p.id = NEW.tenant_id;

    v_guest_id := NEW.tenant_id;

    -- Format dates
    v_starts_at := to_char(NEW.starts_at, 'Mon DD, YYYY');
    v_ends_at := to_char(NEW.ends_at, 'Mon DD, YYYY');

    -- Determine notification type based on operation
    IF TG_OP = 'INSERT' THEN
        -- New booking request - notify host
        INSERT INTO public.notifications (user_id, type, title, body, priority, data, action_url, group_key)
        VALUES (
            v_host_id,
            'booking_request',
            'New Booking Request',
            v_guest_name || ' wants to book "' || v_listing_title || '" from ' || v_starts_at || ' to ' || v_ends_at,
            'high',
            jsonb_build_object(
                'booking_id', NEW.id,
                'listing_id', NEW.listing_id,
                'tenant_id', NEW.tenant_id,
                'guest_name', v_guest_name,
                'starts_at', NEW.starts_at,
                'ends_at', NEW.ends_at,
                'total_price', NEW.total_price
            ),
            '/host/reservations/' || NEW.id,
            'booking_' || NEW.id
        );

        RAISE NOTICE 'Created booking notification for host %', v_host_id;

    ELSIF TG_OP = 'UPDATE' THEN
        -- Status changed
        IF OLD.booking_status IS DISTINCT FROM NEW.booking_status THEN
            CASE NEW.booking_status
                WHEN 'confirmed' THEN
                    -- Notify guest of confirmation
                    INSERT INTO public.notifications (user_id, type, title, body, priority, data, action_url, group_key)
                    VALUES (
                        v_guest_id,
                        'booking_confirmed',
                        'Booking Confirmed!',
                        'Your booking at "' || v_listing_title || '" has been confirmed. Check-in: ' || v_starts_at,
                        'high',
                        jsonb_build_object(
                            'booking_id', NEW.id,
                            'listing_id', NEW.listing_id,
                            'starts_at', NEW.starts_at,
                            'ends_at', NEW.ends_at
                        ),
                        '/trips/' || NEW.id,
                        'booking_' || NEW.id
                    );

                WHEN 'cancelled' THEN
                    -- Notify guest
                    INSERT INTO public.notifications (user_id, type, title, body, priority, data, action_url, group_key)
                    VALUES (
                        v_guest_id,
                        'booking_cancelled',
                        'Booking Cancelled',
                        'Your booking at "' || v_listing_title || '" has been cancelled',
                        'high',
                        jsonb_build_object('booking_id', NEW.id, 'listing_id', NEW.listing_id),
                        '/trips/' || NEW.id,
                        'booking_' || NEW.id
                    );

                    -- Also notify host
                    INSERT INTO public.notifications (user_id, type, title, body, priority, data, action_url, group_key)
                    VALUES (
                        v_host_id,
                        'booking_cancelled',
                        'Booking Cancelled',
                        'A booking for "' || v_listing_title || '" has been cancelled',
                        'normal',
                        jsonb_build_object('booking_id', NEW.id, 'listing_id', NEW.listing_id),
                        '/host/reservations/' || NEW.id,
                        'booking_' || NEW.id
                    );

                WHEN 'completed' THEN
                    -- Notify guest to leave a review
                    INSERT INTO public.notifications (user_id, type, title, body, priority, data, action_url, group_key)
                    VALUES (
                        v_guest_id,
                        'review_reminder',
                        'How was your stay?',
                        'Share your experience at "' || v_listing_title || '"',
                        'normal',
                        jsonb_build_object('booking_id', NEW.id, 'listing_id', NEW.listing_id),
                        '/review/' || NEW.id,
                        'booking_' || NEW.id
                    );

                ELSE
                    -- No notification for other status changes
                    NULL;
            END CASE;
        END IF;
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error but don't fail the booking
        RAISE WARNING 'Notification trigger error: %', SQLERRM;
        RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.notify_on_booking_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    listing_record RECORD;
    guest_record RECORD;
    notification_title text;
    notification_body text;
    notification_type text;
    notification_priority text;
    target_user_id uuid;
    action_url text;
BEGIN
    SELECT l.title, l.owner_id INTO listing_record
    FROM public.listings l
    WHERE l.id = NEW.listing_id;

    SELECT p.full_name INTO guest_record
    FROM public.profiles p
    WHERE p.id = NEW.tenant_id;

    CASE
        WHEN TG_OP = 'INSERT' AND NEW.booking_status = 'pending' THEN
            notification_title := 'New Booking Request';
            notification_body := format('%s wants to book %s',
                COALESCE(guest_record.full_name, 'A guest'),
                COALESCE(listing_record.title, 'your property'));
            notification_type := 'booking_request';
            notification_priority := 'high';
            target_user_id := listing_record.owner_id;
            action_url := '/host/reservations/' || NEW.id;

        WHEN TG_OP = 'UPDATE' AND OLD.booking_status = 'pending' AND NEW.booking_status = 'confirmed' THEN
            notification_title := 'Booking Confirmed!';
            notification_body := format('Your booking at %s has been confirmed',
                COALESCE(listing_record.title, 'the property'));
            notification_type := 'booking_confirmed';
            notification_priority := 'high';
            target_user_id := NEW.tenant_id;
            action_url := '/trips/' || NEW.id;

        WHEN TG_OP = 'UPDATE' AND OLD.booking_status = 'pending' AND NEW.booking_status = 'rejected' THEN
            notification_title := 'Booking Declined';
            notification_body := CASE
                WHEN NEW.rejection_reason IS NOT NULL THEN
                    format('Your booking was declined: %s', NEW.rejection_reason)
                ELSE
                    format('Your booking at %s was declined', COALESCE(listing_record.title, 'the property'))
            END;
            notification_type := 'booking_rejected';
            notification_priority := 'normal';
            target_user_id := NEW.tenant_id;
            action_url := '/trips/' || NEW.id;

        WHEN TG_OP = 'UPDATE' AND OLD.booking_status = 'confirmed' AND NEW.booking_status = 'active' THEN
            notification_title := 'Enjoy Your Stay!';
            notification_body := format('You are now checked in at %s',
                COALESCE(listing_record.title, 'the property'));
            notification_type := 'checked_in';
            notification_priority := 'normal';
            target_user_id := NEW.tenant_id;
            action_url := '/trips/' || NEW.id;

        WHEN TG_OP = 'UPDATE' AND OLD.booking_status = 'active' AND NEW.booking_status = 'completed' THEN
            notification_title := 'How Was Your Stay?';
            notification_body := format('Your stay at %s is complete. Leave a review!',
                COALESCE(listing_record.title, 'the property'));
            notification_type := 'review_prompt';
            notification_priority := 'normal';
            target_user_id := NEW.tenant_id;
            action_url := '/review/' || NEW.id || '/guest';

            INSERT INTO public.notifications (
                user_id, type, title, body, priority, action_url, data
            ) VALUES (
                target_user_id,
                notification_type::notification_type,
                notification_title,
                notification_body,
                notification_priority::notification_priority,
                action_url,
                jsonb_build_object(
                    'booking_id', NEW.id,
                    'listing_id', NEW.listing_id,
                    'listing_title', listing_record.title
                )
            );

            notification_title := 'Leave a Guest Review';
            notification_body := format('Your guest %s has checked out. Leave a review!',
                COALESCE(guest_record.full_name, 'your guest'));
            target_user_id := listing_record.owner_id;
            action_url := '/review/' || NEW.id || '/host';

        -- 140: the host reported that the guest never arrived. The guest is
        -- told in plain words; there is no review window and (see the refund
        -- policy) nothing comes back, which fn_alert_paid_cancellation says
        -- separately when the booking was paid.
        WHEN TG_OP = 'UPDATE' AND OLD.booking_status = 'confirmed' AND NEW.booking_status = 'no_show' THEN
            notification_title := 'Marked as a no-show';
            notification_body := format('The host reported that you did not arrive for your booking at %s. If that is wrong, reply to the host from Messages.',
                COALESCE(listing_record.title, 'the property'));
            notification_type := 'booking_cancelled';
            notification_priority := 'high';
            target_user_id := NEW.tenant_id;
            action_url := '/trips/' || NEW.id;

        WHEN TG_OP = 'UPDATE' AND NEW.booking_status = 'cancelled' AND NEW.cancelled_by = NEW.tenant_id THEN
            notification_title := 'Booking Cancelled';
            notification_body := format('%s cancelled their booking at %s',
                COALESCE(guest_record.full_name, 'A guest'),
                COALESCE(listing_record.title, 'your property'));
            notification_type := 'booking_cancelled';
            notification_priority := 'high';
            target_user_id := listing_record.owner_id;
            action_url := '/host/reservations/' || NEW.id;

        WHEN TG_OP = 'UPDATE' AND NEW.booking_status = 'cancelled' AND NEW.cancelled_by != NEW.tenant_id THEN
            notification_title := 'Booking Cancelled by Host';
            notification_body := format('Your booking at %s was cancelled by the host',
                COALESCE(listing_record.title, 'the property'));
            notification_type := 'booking_cancelled';
            notification_priority := 'high';
            target_user_id := NEW.tenant_id;
            action_url := '/trips/' || NEW.id;

        ELSE
            RETURN NEW;
    END CASE;

    INSERT INTO public.notifications (
        user_id, type, title, body, priority, action_url, data
    ) VALUES (
        target_user_id,
        notification_type::notification_type,
        notification_title,
        notification_body,
        notification_priority::notification_priority,
        action_url,
        jsonb_build_object(
            'booking_id', NEW.id,
            'listing_id', NEW.listing_id,
            'tenant_id', NEW.tenant_id,
            'listing_title', listing_record.title,
            'guest_name', guest_record.full_name,
            'check_in', NEW.starts_at,
            'check_out', NEW.ends_at,
            'total_price', NEW.total_price
        )
    );

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.notify_on_review_revealed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    booking_record RECORD;
    listing_record RECORD;
BEGIN
    -- Only trigger when review is revealed
    IF NEW.is_revealed = true AND (OLD.is_revealed = false OR OLD IS NULL) THEN
        -- Get booking and listing info
        SELECT b.*, l.title AS listing_title, l.owner_id
        INTO booking_record
        FROM public.bookings b
        LEFT JOIN public.listings l ON l.id = b.listing_id
        WHERE b.id = NEW.booking_id;

        -- Notify the reviewee that they received a review
        INSERT INTO public.notifications (
            user_id, type, title, body, priority, action_url, data
        ) VALUES (
            NEW.reviewee_id,
            'review_received'::notification_type,
            'New Review',
            CASE
                WHEN NEW.review_type = 'guest_to_host' THEN
                    format('You received a %s star review for %s',
                        NEW.overall_rating,
                        COALESCE(booking_record.listing_title, 'your property'))
                ELSE
                    format('You received a %s star review from a host', NEW.overall_rating)
            END,
            'normal'::notification_priority,
            CASE
                WHEN NEW.review_type = 'guest_to_host' THEN '/listing/' || NEW.listing_id || '/reviews'
                ELSE '/profile/reviews'
            END,
            jsonb_build_object(
                'review_id', NEW.id,
                'booking_id', NEW.booking_id,
                'rating', NEW.overall_rating,
                'review_type', NEW.review_type
            )
        );
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.notify_recipient_on_new_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_recipient_id UUID;
    v_sender_name TEXT;
    v_preview TEXT;
BEGIN
    -- The recipient is the conversation participant who isn't the sender.
    SELECT CASE
             WHEN c.participant_one_id = NEW.sender_id THEN c.participant_two_id
             ELSE c.participant_one_id
           END
    INTO v_recipient_id
    FROM public.conversations c
    WHERE c.id = NEW.conversation_id;

    IF v_recipient_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(p.full_name, 'New message')
    INTO v_sender_name
    FROM public.profiles p
    WHERE p.id = NEW.sender_id;

    v_preview := CASE
        WHEN NEW.content_type = 'text' THEN LEFT(NEW.content, 140)
        WHEN NEW.content_type = 'booking_card' THEN LEFT(NEW.content, 140)
        WHEN NEW.content_type = 'image' THEN '📷 Sent a photo'
        WHEN NEW.content_type = 'location' THEN '📍 Shared a location'
        WHEN NEW.content_type = 'file' THEN '📎 Sent a file'
        ELSE 'Sent a message'
    END;

    -- The on_notification_send_push trigger (migration 015) picks this row
    -- up and delivers the FCM push.
    INSERT INTO public.notifications (
        user_id,
        type,
        title,
        body,
        data,
        group_key,
        action_url
    ) VALUES (
        v_recipient_id,
        'new_message',
        COALESCE(v_sender_name, 'New message'),
        v_preview,
        jsonb_build_object(
            'conversation_id', NEW.conversation_id,
            'message_id', NEW.id,
            'sender_id', NEW.sender_id
        ),
        'conversation_' || NEW.conversation_id,
        '/messages/' || NEW.conversation_id
    );

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Never block the message insert because notifying failed.
        RAISE WARNING 'new-message notification error: %', SQLERRM;
        RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.orphan_face_evidence()
 RETURNS TABLE(name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.fn_require_service_role();
  return query select o.name from storage.objects o where o.bucket_id='face-evidence'
    and not exists(select 1 from public.face_verification_attempts a
      where a.id::text=split_part(o.name,'/',2) and a.user_id::text=split_part(o.name,'/',1))
    limit 100;
end;
$function$;

CREATE OR REPLACE FUNCTION public.otp_log_attempts(p_id uuid, p_attempts integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.otp_attempts set attempts = p_attempts where id = p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.otp_log_send(p_phone text, p_otp_hash text, p_expires_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  insert into public.otp_attempts (phone, otp_hash, expires_at)
  values (p_phone, p_otp_hash, p_expires_at)
  returning id into v_id;
  return v_id;
end $function$;

CREATE OR REPLACE FUNCTION public.otp_log_verified(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.otp_attempts
  set verified_at = now(), is_used = true
  where id = p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.reap_edge_rate_limits()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  delete from public.edge_rate_limits where window_start < now() - interval '1 day';
  get diagnostics n = row_count;
  return n;
end;
$function$;

CREATE OR REPLACE FUNCTION public.reap_stale_devices()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted integer;
begin
  with gone as (
    delete from public.user_devices
     where (revoked_at is not null and revoked_at < now() - interval '180 days')
        or (revoked_at is null and last_seen_at < now() - interval '365 days')
    returning 1
  )
  select count(*) into v_deleted from gone;

  return v_deleted;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_disbursement(p_user_id uuid, p_payout_method_id uuid, p_amount numeric, p_kind text, p_booking_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_status text DEFAULT 'sent'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin uuid := auth.uid();
  v_id    uuid;
begin
  if not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if p_kind not in ('host_payout', 'guest_refund') then
    raise exception 'kind must be host_payout or guest_refund' using errcode = '22023';
  end if;
  if p_status not in ('pending', 'sent') then
    raise exception 'a new disbursement is pending or sent' using errcode = '22023';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'amount must be positive' using errcode = '22023';
  end if;

  -- Defence 2, at the point where it costs money: the method must belong to
  -- the recipient, be verified by a human, and still be live.
  if not exists (
    select 1 from public.payout_methods
     where id = p_payout_method_id
       and user_id = p_user_id
       and status = 'verified'
       and retired_at is null
  ) then
    raise exception 'that payout method is not a verified, live method for this user'
      using errcode = '22023';
  end if;

  -- If a booking is named, the recipient must actually be a party to it — the
  -- guest for a refund, the host for a payout. Catches the fat-finger of
  -- pasting the wrong booking id far more cheaply than a reconciliation does.
  if p_booking_id is not null then
    if p_kind = 'guest_refund' then
      if not exists (select 1 from public.bookings b
                      where b.id = p_booking_id and b.tenant_id = p_user_id) then
        raise exception 'that booking does not belong to this guest' using errcode = '22023';
      end if;
    else
      if not exists (select 1 from public.bookings b
                       join public.listings l on l.id = b.listing_id
                      where b.id = p_booking_id and l.owner_id = p_user_id) then
        raise exception 'that booking is not on this host''s listing' using errcode = '22023';
      end if;
    end if;
  end if;

  insert into public.disbursements (
    user_id, payout_method_id, booking_id, kind, amount,
    status, reference, note, created_by, sent_at
  ) values (
    p_user_id, p_payout_method_id, p_booking_id, p_kind, p_amount,
    p_status, nullif(btrim(p_reference), ''), nullif(btrim(p_note), ''),
    v_admin, case when p_status = 'sent' then now() end
  )
  returning id into v_id;

  return v_id;
exception
  when unique_violation then
    raise exception 'this booking has already been settled — check the payout history'
      using errcode = '23505';
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_face_evidence_deleted(p_attempt_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.fn_require_service_role();
  update public.face_verification_attempts set media_deleted_at=now(),
    status=case when status in ('draft','pending') then 'superseded' else status end
    where id=p_attempt_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_host_ledger_entry(p_host_id uuid, p_entry_type text, p_amount numeric, p_note text DEFAULT NULL::text, p_reference text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin  uuid := auth.uid();
  v_amount numeric := round(coalesce(p_amount, 0), 2);
  v_id     uuid;
begin
  if not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if p_entry_type not in ('collection', 'adjustment') then
    raise exception 'entry type must be collection or adjustment — payouts are recorded as disbursements'
      using errcode = '22023';
  end if;
  if not exists (select 1 from public.profiles where id = p_host_id) then
    raise exception 'no such user' using errcode = '22023';
  end if;
  if p_entry_type = 'collection' and v_amount <= 0 then
    raise exception 'a collection must be a positive amount' using errcode = '22023';
  end if;
  if p_entry_type = 'adjustment' and v_amount = 0 then
    raise exception 'an adjustment cannot be zero' using errcode = '22023';
  end if;
  if p_entry_type = 'adjustment' and coalesce(btrim(p_note), '') = '' then
    raise exception 'an adjustment needs a note explaining it' using errcode = '22023';
  end if;

  insert into public.host_ledger_entries
    (host_id, entry_type, amount, reference, note, created_by)
  values
    (p_host_id, p_entry_type, v_amount,
     nullif(btrim(p_reference), ''), nullif(btrim(p_note), ''), v_admin)
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.redeem_coupon(p_coupon_id uuid, p_booking_id uuid, p_discount_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c public.coupons%rowtype;
  v_uid uuid := auth.uid();
  v_booking public.bookings%rowtype;
  v_user_uses int;
begin
  if v_uid is null then raise exception 'Not authenticated'; end if;

  select * into v_booking from public.bookings where id = p_booking_id;
  if v_booking.tenant_id is null or v_booking.tenant_id <> v_uid then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  -- One redemption per booking (idempotent no-op on repeat).
  if exists (select 1 from public.coupon_redemptions where booking_id = p_booking_id) then
    return;
  end if;

  select * into c from public.coupons where id = p_coupon_id for update;
  if not found or not c.is_active then raise exception 'Coupon unavailable'; end if;

  -- 138: the booking must actually carry this coupon. The parameter is kept
  -- for the existing signature but the amount recorded is the booking's own.
  if v_booking.coupon_code is distinct from c.code then
    raise exception 'This booking was not made with that coupon'
      using errcode = '42501', hint = 'coupon_not_on_booking';
  end if;

  if c.usage_limit is not null and c.used_count >= c.usage_limit then
    raise exception 'Coupon usage limit reached';
  end if;
  if c.per_user_limit is not null then
    select count(*) into v_user_uses from public.coupon_redemptions
      where coupon_id = c.id and user_id = v_uid;
    if v_user_uses >= c.per_user_limit then raise exception 'Coupon already used'; end if;
  end if;

  insert into public.coupon_redemptions (coupon_id, user_id, booking_id, discount_amount)
    values (c.id, v_uid, p_booking_id, coalesce(v_booking.discount_amount, 0));
  update public.coupons set used_count = used_count + 1 where id = c.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.register_device(p_device_id text, p_platform text, p_model text DEFAULT NULL::text, p_os_version text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_session uuid;
  v_id uuid;
begin
  if v_user is null then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  if p_device_id is null or length(p_device_id) not between 8 and 128 then
    raise exception 'Invalid device id' using errcode = '22023';
  end if;

  begin
    v_session := nullif(auth.jwt() ->> 'session_id', '')::uuid;
  exception when others then
    v_session := null;
  end;

  insert into public.user_devices as d (
    user_id, device_id, platform, model, os_version, app_version,
    session_id, last_ip
  )
  values (
    v_user, p_device_id, p_platform, p_model, p_os_version, p_app_version,
    v_session, inet_client_addr()
  )
  on conflict (user_id, device_id) do update set
    platform = excluded.platform,
    model = coalesce(excluded.model, d.model),
    os_version = coalesce(excluded.os_version, d.os_version),
    app_version = coalesce(excluded.app_version, d.app_version),
    session_id = coalesce(excluded.session_id, d.session_id),
    last_ip = coalesce(excluded.last_ip, d.last_ip),
    last_seen_at = now(),
    revoked_at = null
  returning d.id into v_id;

  -- ── Phase 2 (125) ────────────────────────────────────────────────────────
  -- After the upsert, and passing the row that just registered so it is
  -- protected by identity rather than by timestamp. A user must never be
  -- signed out by their own login.
  perform public.fn_enforce_device_limit(v_user, v_id);

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.retire_payout_method(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_was_def boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- An owner or an admin may retire; an admin needs it to kill a method that
  -- turns out to be fraudulent without waiting for the account holder.
  select is_default into v_was_def
    from public.payout_methods
   where id = p_id and retired_at is null
     and (user_id = v_uid or public.is_admin());

  if not found then
    raise exception 'no such payout method' using errcode = '22023';
  end if;

  -- A payout already queued against this method would otherwise be sent to an
  -- account the user has just disowned.
  if exists (
    select 1 from public.disbursements
     where payout_method_id = p_id and status = 'pending'
  ) then
    raise exception 'a payout is still pending against this method — resolve it first'
      using errcode = '22023';
  end if;

  update public.payout_methods
     set retired_at = now(), is_default = false
   where id = p_id;

  -- Leave the user with a default if any live method remains, preferring a
  -- verified one so the replacement is immediately payable. Without this, a
  -- host who retires their old wallet silently has nowhere to be paid.
  if v_was_def then
    update public.payout_methods
       set is_default = true
     where id = (
       select id from public.payout_methods
        where user_id = (select user_id from public.payout_methods where id = p_id)
          and retired_at is null and status <> 'rejected'
        order by (status = 'verified') desc, created_at
        limit 1
     );
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.review_face_verification(p_attempt_id uuid, p_evidence_version uuid, p_decision text, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.face_verification_attempts; target_user uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Admin approval required' using errcode='42501'; end if;
  if p_decision is null or p_decision not in ('approved','rejected','retry') then raise exception 'Invalid review decision'; end if;
  if length(coalesce(p_note,''))>500 then raise exception 'Keep the note under 500 characters'; end if;
  select user_id into target_user from public.face_verification_attempts where id=p_attempt_id;
  if target_user=auth.uid() then raise exception 'Another admin must review your submission' using errcode='42501'; end if;
  perform 1 from public.profiles where id=target_user for update;
  select * into a from public.face_verification_attempts where id=p_attempt_id for update;
  if not found or a.status<>'pending' or a.evidence_version is distinct from p_evidence_version
     or a.media_deleted_at is not null then raise exception 'Submission changed. Refresh the review queue'; end if;
  if exists(select 1 from public.face_verification_attempts where user_id=a.user_id and created_at>a.created_at) then
    raise exception 'A newer submission exists'; end if;
  if (p_decision<>'approved' or a.method='manual') and coalesce(btrim(p_note),'')='' then
    raise exception 'A reason is required, including for manual approval'; end if;
  update public.face_verification_attempts set status=p_decision, reviewed_by=auth.uid(),
    reviewed_at=now(),review_note=nullif(btrim(p_note),'') where id=a.id;
  -- Deliberately never writes profiles.verification_status or nid_verified.
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_device(p_device_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_row uuid;
begin
  if v_user is null then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  select id into v_row
    from public.user_devices
   where user_id = v_user
     and device_id = p_device_id
     and revoked_at is null;

  if v_row is null then
    -- Already revoked, or never this user's. Both answer the same way on
    -- purpose: telling a caller that a device id belongs to somebody else is
    -- an oracle for device ids.
    return false;
  end if;

  return public.fn_revoke_device_row(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_other_devices()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_session uuid;
  v_row record;
  v_count integer := 0;
begin
  if v_user is null then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  begin
    v_session := nullif(auth.jwt() ->> 'session_id', '')::uuid;
  exception when others then
    v_session := null;
  end;

  for v_row in
    select id from public.user_devices
     where user_id = v_user
       and revoked_at is null
       -- `is distinct from` and not `<>`: with a null session_id on either
       -- side, `<>` is null, the row is skipped, and the button silently signs
       -- nothing out.
       and (v_session is null or session_id is distinct from v_session)
  loop
    if public.fn_revoke_device_row(v_row.id) then
      v_count := v_count + 1;
    end if;
  end loop;

  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.search_landmarks(p_query text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_limit integer DEFAULT 20)
 RETURNS SETOF jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select to_jsonb(x) from (
    select id, name, type, city, area, latitude, longitude
    from public.landmarks
    where is_active
      and (p_type is null or type = p_type)
      and (p_query is null or p_query = '' or
           name ilike '%' || p_query || '%' or
           area ilike '%' || p_query || '%' or
           city ilike '%' || p_query || '%')
    order by name
    limit greatest(coalesce(p_limit, 20), 0)
  ) x;
$function$;

CREATE OR REPLACE FUNCTION public.search_listings(p_property_types text[] DEFAULT NULL::text[], p_guest_count integer DEFAULT 1, p_min_price numeric DEFAULT NULL::numeric, p_max_price numeric DEFAULT NULL::numeric, p_amenities text[] DEFAULT NULL::text[], p_location text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_purpose_tags text[] DEFAULT NULL::text[], p_center_lat double precision DEFAULT NULL::double precision, p_center_lng double precision DEFAULT NULL::double precision, p_radius_m integer DEFAULT NULL::integer, p_radii integer[] DEFAULT NULL::integer[], p_ne_lat double precision DEFAULT NULL::double precision, p_ne_lng double precision DEFAULT NULL::double precision, p_sw_lat double precision DEFAULT NULL::double precision, p_sw_lng double precision DEFAULT NULL::double precision, p_check_in timestamp with time zone DEFAULT NULL::timestamp with time zone, p_check_out timestamp with time zone DEFAULT NULL::timestamp with time zone, p_adults integer DEFAULT NULL::integer, p_children integer DEFAULT NULL::integer, p_infants integer DEFAULT NULL::integer, p_pets integer DEFAULT NULL::integer)
 RETURNS SETOF jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with center as (
    select case
             when p_center_lat is not null and p_center_lng is not null
             then ST_SetSRID(ST_MakePoint(p_center_lng, p_center_lat), 4326)::geography
           end as g
  ),
  -- How many listings the nearest-N fallback may return when no tier matched.
  -- Admin-configurable; falls back to the historical 20 when the row is absent
  -- or unreadable, so search degrades to its old behaviour rather than to zero
  -- results. The validation trigger keeps the stored text numeric.
  fallback_cap as (
    select coalesce(
             (select btrim(value)::integer
              from public.app_settings
              where key = 'search_nearest_fallback_limit'
                and btrim(coalesce(value, '')) ~ '^[0-9]+$'),
             20) as n
  ),
  -- The bounding box is active only when all four corners are present and the
  -- box is non-degenerate (north-east actually north-east of south-west).
  bbox as (
    select (p_ne_lat is not null and p_ne_lng is not null
            and p_sw_lat is not null and p_sw_lng is not null
            and p_ne_lat > p_sw_lat and p_ne_lng > p_sw_lng) as active
  ),
  -- Every filter except the expanding radius. dist is non-null whenever a
  -- center is set and the listing has coordinates.
  base as (
    select l.id as lid, l as row_l, lr.average_rating as rating,
           coalesce(lr.review_count, 0) as review_count,
           -- Live host avatar (public_profiles is anon-readable, no PII). The
           -- listings.host_avatar_url column is dead (never written), so we
           -- source the real, current picture from the owner's profile. (091)
           pp.avatar_url as host_avatar,
           case when c.g is not null and l.geog is not null
                then ST_Distance(l.geog, c.g) end as dist
    from public.listings l
    left join public.listing_ratings lr on lr.listing_id = l.id
    left join public.public_profiles pp on pp.id = l.owner_id
    cross join center c
    cross join bbox bb
    where l.is_active = true
      and l.host_available = true
      and (p_property_types is null or l.listing_type::text = any(p_property_types))
      and l.max_guests >= coalesce(p_guest_count, 1)
      -- Per-category caps (118). Each is a sub-cap UNDER max_guests, not a
      -- replacement for it: the line above still rejects a party too big for
      -- the place, and these only narrow it further. A null column means the
      -- host set no separate limit for that category, so the total is the
      -- only thing standing -- which is why every existing listing keeps
      -- matching exactly what it matched before this migration.
      and (p_adults   is null or l.max_adults   is null or l.max_adults   >= p_adults)
      and (p_children is null or l.max_children is null or l.max_children >= p_children)
      and (p_infants  is null or l.max_infants  is null or l.max_infants  >= p_infants)
      -- Pets are the one category that defaults to DENY, because unlike the
      -- others it already had a switch: pets_allowed (053) is `not null
      -- default false`, so silence means no. A guest travelling with an animal
      -- must not be shown a place that never said yes -- that is a refusal at
      -- the door, not a preference. max_pets then narrows a host who does
      -- allow them; null there means "allowed, no stated number".
      and (coalesce(p_pets, 0) = 0
           or (l.pets_allowed and (l.max_pets is null or l.max_pets >= p_pets)))
      and (p_min_price is null or least(l.hourly_rate, l.daily_rate, l.monthly_rate) >= p_min_price)
      and (p_max_price is null or least(l.hourly_rate, l.daily_rate, l.monthly_rate) <= p_max_price)
      and (p_location is null or p_location = '' or
           l.city    ilike '%' || p_location || '%' or
           l.address ilike '%' || p_location || '%' or
           l.title   ilike '%' || p_location || '%')
      and (p_amenities is null or (
        select count(distinct f.name)
        from public.listing_facilities lf
        join public.facilities f on f.id = lf.facility_id
        where lf.listing_id = l.id and f.name = any(p_amenities)
      ) = array_length(p_amenities, 1))
      and (p_purpose_tags is null or l.purpose_tags && p_purpose_tags)
      -- bounding-box search: the listing must sit inside the place's extent.
      -- This is the exact area the guest searched, so it supersedes both radius
      -- paths (which are passed null in box mode anyway).
      and (not bb.active or
           (l.latitude between p_sw_lat and p_ne_lat and
            l.longitude between p_sw_lng and p_ne_lng))
      -- single fixed radius (purpose/landmark search) — unchanged
      and (c.g is null or p_radius_m is null or
           (l.geog is not null and ST_DWithin(l.geog, c.g, p_radius_m)))
      -- tiered search ranks by distance; listings without a pin can't qualify
      and (c.g is null or p_radii is null or l.geog is not null)
      -- Dates the guest asked for must be bookable: no host block (110) and no
      -- active booking. Delegated so this stays one rule with one home.
      --
      -- CASE, not `p_check_in is null or ... or is_booking_available(...)`:
      -- Postgres does not promise left-to-right OR evaluation, and a reversed
      -- window would reach tstzrange(lower > upper) and abort the search with
      -- 22000. CASE does promise it, so a degenerate window disables the
      -- filter instead of erroring. The client guards this too; a public RPC
      -- cannot rely on that.
      and case
            when p_check_in is null or p_check_out is null
                 or p_check_out <= p_check_in then true
            else public.is_booking_available(l.id, p_check_in, p_check_out)
          end
  ),
  -- Smallest tier that contains at least one match (null → nearest fallback).
  -- Reads `base`, so an unavailable listing cannot win a tier and then be
  -- filtered out of it, which would answer a dated search with an empty ring.
  chosen as (
    select min(r) as radius
    from unnest(coalesce(p_radii, '{}'::integer[])) r
    where (select min(dist) from base) <= r
  )
  select to_jsonb(b.row_l) || jsonb_build_object(
    'host_avatar_url', b.host_avatar,
    'rating', b.rating,
    'review_count', b.review_count,
    'distance_m', b.dist,
    'search_radius_m', (select radius from chosen),
    'radius_fallback',
      (p_radii is not null and (select radius from chosen) is null),
    'listing_facilities',
    coalesce((
      select jsonb_agg(jsonb_build_object(
               'facility_id', lf.facility_id,
               'facilities', jsonb_build_object('name', f.name)))
      from public.listing_facilities lf
      join public.facilities f on f.id = lf.facility_id
      where lf.listing_id = b.lid
    ), '[]'::jsonb)
  )
  from base b
  where p_radii is null
     or (select radius from chosen) is null            -- fallback: nearest N
     or b.dist <= (select radius from chosen)
  order by b.dist asc nulls last,
           coalesce(b.rating, 0) desc,
           b.review_count desc,
           (b.row_l).created_at desc
  limit case
          when p_radii is not null and (select radius from chosen) is null
          then least(greatest(coalesce(p_limit, 20), 0), (select n from fallback_cap))
          else greatest(coalesce(p_limit, 20), 0)
        end
  offset greatest(coalesce(p_offset, 0), 0);
$function$;

CREATE OR REPLACE FUNCTION public.search_listings_by_location(center_lat numeric, center_lng numeric, radius_meters integer DEFAULT 10000)
 RETURNS SETOF listings
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT *
    FROM listings
    WHERE is_active = TRUE
    AND ST_DWithin(
        location,
        ST_SetSRID(ST_MakePoint(center_lng, center_lat), 4326)::geography,
        radius_meters
    )
    ORDER BY ST_Distance(
        location,
        ST_SetSRID(ST_MakePoint(center_lng, center_lat), 4326)::geography
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.send_booking_accept_messages(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_host_id UUID;
BEGIN
    SELECT l.owner_id INTO v_host_id
    FROM public.bookings b
    JOIN public.listings l ON l.id = b.listing_id
    WHERE b.id = p_booking_id;

    IF v_host_id IS NULL THEN RETURN; END IF;
    -- Only the listing's host may trigger these sends (null uid = server/cron).
    IF auth.uid() IS NOT NULL AND auth.uid() <> v_host_id THEN
        RAISE EXCEPTION 'Not authorized';
    END IF;

    PERFORM public.send_booking_map(p_booking_id);
    PERFORM public.send_precheckin_for_booking(p_booking_id);
    PERFORM public.send_booking_contacts(p_booking_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.send_booking_contacts(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    rec RECORD;
    v_conv_id UUID;
    v_lang TEXT;
    v_header TEXT;
    v_msg TEXT;
begin
    select b.id as booking_id, b.tenant_id, b.listing_id,
           coalesce(b.tenant_name, gp.full_name, 'Guest') as guest_name,
           coalesce(public.fn_identity_phone(gp.id), gp.mobile) as guest_phone,
           l.owner_id as host_id,
           coalesce(hp.full_name, 'Host') as host_name,
           coalesce(public.fn_identity_phone(hp.id), hp.mobile) as host_phone,
           coalesce(hp.message_language, gp.message_language, 'en') as lang
    into rec
    from public.bookings b
    join public.listings l on l.id = b.listing_id
    left join public.profiles gp on gp.id = b.tenant_id
    left join public.profiles hp on hp.id = l.owner_id
    where b.id = p_booking_id
      and b.booking_status = 'confirmed'
      and b.tenant_id is not null;

    if not found then return; end if;

    -- Deliver only once per booking.
    if exists (select 1 from public.scheduled_message_sends s
               where s.booking_id = rec.booking_id and s.trigger = 'contacts') then
        return;
    end if;

    v_lang := rec.lang;
    v_header := case when v_lang = 'bn' then '📞 যোগাযোগের তথ্য' else '📞 Contact details' end;
    v_msg := v_header;

    if nullif(trim(rec.guest_phone), '') is not null then
        v_msg := v_msg || E'\n'
            || (case when v_lang = 'bn' then 'অতিথি: ' else 'Guest: ' end)
            || rec.guest_name || ' — ' || trim(rec.guest_phone);
    end if;
    if nullif(trim(rec.host_phone), '') is not null then
        v_msg := v_msg || E'\n'
            || (case when v_lang = 'bn' then 'হোস্ট: ' else 'Host: ' end)
            || rec.host_name || ' — ' || trim(rec.host_phone);
    end if;

    v_conv_id := public.get_or_create_conversation(
        rec.tenant_id, rec.host_id, rec.booking_id, rec.listing_id);

    -- Only post if at least one phone was present.
    if v_msg <> v_header then
        insert into public.messages (conversation_id, sender_id, content, content_type)
        values (v_conv_id, rec.host_id, v_msg, 'text');
    end if;

    insert into public.scheduled_message_sends (booking_id, trigger)
    values (rec.booking_id, 'contacts');
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_booking_map(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    rec RECORD;
    v_conv_id UUID;
    v_address TEXT;
    v_lang TEXT;
BEGIN
    SELECT b.id AS booking_id, b.tenant_id, b.listing_id,
           COALESCE(b.listing_title, l.title) AS listing_title,
           -- Exact address + coordinates from the gated table, falling back to
           -- the listing's public (area-level) values so a listing with no
           -- listing_addresses row still gets a usable map pin.
           COALESCE(la.exact_address, l.address) AS listing_address,
           l.city AS listing_city,
           COALESCE(la.latitude, l.latitude) AS listing_lat,
           COALESCE(la.longitude, l.longitude) AS listing_lng,
           l.owner_id AS host_id,
           COALESCE(p.message_language, 'en') AS message_language
    INTO rec
    FROM public.bookings b
    JOIN public.listings l ON l.id = b.listing_id
    LEFT JOIN public.listing_addresses la ON la.listing_id = l.id
    LEFT JOIN public.profiles p ON p.id = l.owner_id
    WHERE b.id = p_booking_id AND b.booking_status = 'confirmed'
      AND b.tenant_id IS NOT NULL;

    IF NOT FOUND THEN RETURN; END IF;
    IF rec.listing_lat IS NULL OR rec.listing_lng IS NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM public.scheduled_message_sends s
               WHERE s.booking_id = rec.booking_id AND s.trigger = 'map') THEN
        RETURN;
    END IF;

    v_lang := rec.message_language;
    v_address := NULLIF(TRIM(BOTH ', ' FROM
        COALESCE(rec.listing_address, '') ||
        CASE WHEN rec.listing_city IS NOT NULL
                  AND (rec.listing_address IS NULL
                       OR rec.listing_address NOT ILIKE '%' || rec.listing_city || '%')
             THEN ', ' || rec.listing_city ELSE '' END), '');

    v_conv_id := public.get_or_create_conversation(
        rec.tenant_id, rec.host_id, rec.booking_id, rec.listing_id);

    INSERT INTO public.messages
        (conversation_id, sender_id, content, content_type, metadata)
    VALUES (
        v_conv_id, rec.host_id,
        COALESCE(v_address, rec.listing_title,
                 CASE WHEN v_lang = 'bn' THEN 'লিস্টিং লোকেশন' ELSE 'Listing location' END),
        'location',
        jsonb_build_object(
            'latitude', rec.listing_lat,
            'longitude', rec.listing_lng,
            'address', v_address,
            'place_name', rec.listing_title
        )
    );

    INSERT INTO public.scheduled_message_sends (booking_id, trigger)
    VALUES (rec.booking_id, 'map');
END;
$function$;

CREATE OR REPLACE FUNCTION public.send_checkout_for_booking(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    rec RECORD;
    v_content TEXT;
    v_enabled BOOLEAN;
    v_conv_id UUID;
    v_rendered TEXT;
    v_nights INTEGER;
    v_units INTEGER;
    v_duration TEXT;
    v_lang TEXT;
    v_default_en TEXT;
    v_default_bn TEXT;
    v_ci_date TEXT;
    v_co_date TEXT;
BEGIN
    SELECT b.id AS booking_id, b.tenant_id, b.tenant_name, b.guest_count,
           b.starts_at, b.ends_at, b.pricing_unit,
           COALESCE(b.listing_title, l.title) AS listing_title,
           b.listing_id, l.owner_id AS host_id,
           COALESCE(p.full_name, 'Your host') AS host_name,
           COALESCE(p.message_language, 'en') AS message_language
    INTO rec
    FROM public.bookings b
    JOIN public.listings l ON l.id = b.listing_id
    LEFT JOIN public.profiles p ON p.id = l.owner_id
    WHERE b.id = p_booking_id AND b.tenant_id IS NOT NULL;

    IF NOT FOUND THEN RETURN; END IF;

    -- Deliver once per booking.
    IF EXISTS (SELECT 1 FROM public.scheduled_message_sends s
               WHERE s.booking_id = rec.booking_id AND s.trigger = 'check_out') THEN
        RETURN;
    END IF;

    v_lang := rec.message_language;

    -- Keep in sync with MessageTemplate.defaultContentFor(checkOut, en).
    v_default_en := E'Hi {{guest_name}},\n\n' ||
        'Thanks for staying at {{listing_title}} — I hope you enjoyed ' ||
        E'your visit! You are welcome back anytime.\n\n' ||
        E'Safe travels!\n\n' ||
        E'Thanks,\n{{host_name}}';
    -- Keep in sync with MessageTemplate.defaultContentFor(checkOut, bn).
    v_default_bn := E'হ্যালো {{guest_name}},\n\n' ||
        '{{listing_title}}-এ থাকার জন্য ধন্যবাদ — আশা করি আপনার সময়টা ' ||
        E'ভালো কেটেছে! আপনি যেকোনো সময় আবার স্বাগত।\n\n' ||
        E'শুভ যাত্রা!\n\n' ||
        E'ধন্যবাদ,\n{{host_name}}';

    SELECT t.content, t.enabled
    INTO v_content, v_enabled
    FROM public.message_templates t
    WHERE t.host_id = rec.host_id AND t.trigger = 'check_out';

    IF NOT FOUND THEN
        v_enabled := TRUE;
        v_content := CASE WHEN v_lang = 'bn' THEN v_default_bn ELSE v_default_en END;
    ELSIF v_content = v_default_en OR v_content = v_default_bn THEN
        -- Host stored an un-customized default; render it in their language.
        v_content := CASE WHEN v_lang = 'bn' THEN v_default_bn ELSE v_default_en END;
    END IF;

    IF NOT v_enabled THEN RETURN; END IF;

    v_conv_id := public.get_or_create_conversation(
        rec.tenant_id, rec.host_id, rec.booking_id, rec.listing_id);

    v_nights := GREATEST(1, ((rec.ends_at at time zone 'Asia/Dhaka')::date - (rec.starts_at at time zone 'Asia/Dhaka')::date));
    IF rec.pricing_unit::text = 'hour' THEN
        v_units := GREATEST(1, FLOOR(EXTRACT(EPOCH FROM (rec.ends_at - rec.starts_at)) / 3600)::int);
        v_duration := v_units || CASE WHEN v_lang = 'bn' THEN ' ঘণ্টা'
                                      WHEN v_units = 1 THEN ' hour' ELSE ' hours' END;
    ELSIF rec.pricing_unit::text = 'month' THEN
        v_units := GREATEST(1, ROUND(((rec.ends_at at time zone 'Asia/Dhaka')::date - (rec.starts_at at time zone 'Asia/Dhaka')::date) / 30.0)::int);
        v_duration := v_units || CASE WHEN v_lang = 'bn' THEN ' মাস'
                                      WHEN v_units = 1 THEN ' month' ELSE ' months' END;
    ELSE
        v_duration := v_nights || CASE WHEN v_lang = 'bn' THEN ' রাত'
                                       WHEN v_nights = 1 THEN ' night' ELSE ' nights' END;
    END IF;

    v_ci_date := to_char(rec.starts_at at time zone 'Asia/Dhaka', 'FMDay, FMMonth FMDD');
    v_co_date := to_char(rec.ends_at at time zone 'Asia/Dhaka', 'FMDay, FMMonth FMDD');
    IF v_lang = 'bn' THEN
        v_ci_date := public._localize_date_bn(v_ci_date);
        v_co_date := public._localize_date_bn(v_co_date);
    END IF;

    v_rendered := v_content;
    v_rendered := replace(v_rendered, '{{guest_name}}',
        COALESCE(rec.tenant_name, CASE WHEN v_lang = 'bn' THEN 'অতিথি' ELSE 'Guest' END));
    v_rendered := replace(v_rendered, '{{listing_title}}',
        COALESCE(rec.listing_title, CASE WHEN v_lang = 'bn' THEN 'আপনার থাকার জায়গা' ELSE 'your stay' END));
    v_rendered := replace(v_rendered, '{{check_in_date}}', v_ci_date);
    v_rendered := replace(v_rendered, '{{check_out_date}}', v_co_date);
    v_rendered := replace(v_rendered, '{{duration}}', v_duration);
    v_rendered := replace(v_rendered, '{{nights}}', v_nights::text);
    v_rendered := replace(v_rendered, '{{guest_count}}', COALESCE(rec.guest_count, 1)::text);
    v_rendered := replace(v_rendered, '{{host_name}}', rec.host_name);

    INSERT INTO public.messages (conversation_id, sender_id, content, content_type)
    VALUES (v_conv_id, rec.host_id, v_rendered, 'text');

    INSERT INTO public.scheduled_message_sends (booking_id, trigger)
    VALUES (rec.booking_id, 'check_out');
END;
$function$;

CREATE OR REPLACE FUNCTION public.send_pre_checkin_messages()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    sent_count integer := 0;
    rec RECORD;
BEGIN
    FOR rec IN
        SELECT b.id AS booking_id
        FROM public.bookings b
        WHERE b.booking_status = 'confirmed'
          AND b.tenant_id IS NOT NULL
          -- Candidate while the stay is not fully over. The per-booking window
          -- guard inside send_precheckin_for_booking enforces "not too early";
          -- using ends_at (not starts_at) is what lets lead_days=0 fire.
          AND b.ends_at > NOW()
          AND NOT EXISTS (
              SELECT 1 FROM public.scheduled_message_sends s
              WHERE s.booking_id = b.id AND s.trigger = 'check_in'
          )
    LOOP
        -- Isolate each booking: one bad render must not abort the whole run
        -- (defect #1 was exactly a single-call error cascading to every booking).
        BEGIN
            PERFORM public.send_precheckin_for_booking(rec.booking_id);
            sent_count := sent_count + 1;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'pre-checkin message failed for booking %: %', rec.booking_id, SQLERRM;
        END;
    END LOOP;
    RETURN sent_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.send_precheckin_for_booking(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    rec RECORD;
    v_content TEXT;
    v_enabled BOOLEAN;
    v_lead_days INTEGER;
    v_conv_id UUID;
    v_rendered TEXT;
    v_nights INTEGER;
    v_units INTEGER;
    v_duration TEXT;
    v_address TEXT;
    v_access TEXT;
    v_lang TEXT;
    v_default_en TEXT;
    v_default_bn TEXT;
    v_ci_date TEXT;
    v_co_date TEXT;
BEGIN
    SELECT b.id AS booking_id, b.tenant_id, b.tenant_name, b.guest_count,
           b.starts_at, b.ends_at, b.pricing_unit,
           COALESCE(b.listing_title, l.title) AS listing_title,
           b.listing_id, l.address AS listing_address, l.city AS listing_city,
           l.owner_id AS host_id,
           COALESCE(p.full_name, 'Your host') AS host_name,
           COALESCE(p.message_language, 'en') AS message_language,
           cd.directions AS ci_directions, cd.wifi_name AS ci_wifi_name,
           cd.wifi_password AS ci_wifi_password, cd.access_code AS ci_access_code
    INTO rec
    FROM public.bookings b
    JOIN public.listings l ON l.id = b.listing_id
    LEFT JOIN public.profiles p ON p.id = l.owner_id
    LEFT JOIN public.listing_checkin_details cd ON cd.listing_id = b.listing_id
    WHERE b.id = p_booking_id AND b.booking_status = 'confirmed'
      AND b.tenant_id IS NOT NULL;

    IF NOT FOUND THEN RETURN; END IF;

    -- Already delivered for this booking?
    IF EXISTS (SELECT 1 FROM public.scheduled_message_sends s
               WHERE s.booking_id = rec.booking_id AND s.trigger = 'check_in') THEN
        RETURN;
    END IF;

    v_lang := rec.message_language;

    -- Keep in sync with MessageTemplate.defaultContentFor(checkIn, en).
    v_default_en := E'Hi {{guest_name}},\n\n' ||
        E'Thanks again for booking at {{listing_title}}!\n\n' ||
        'Please find the details below for a smooth and seamless ' ||
        E'check-in on {{check_in_date}}.\n\n' ||
        E'Address:\n{{listing_address}}\n\n' ||
        'I am sharing the exact map location below so you can find ' ||
        'the place easily. Please let me know your expected arrival ' ||
        'time, and feel free to reach out if you have any questions ' ||
        E'before your stay.\n\n' ||
        'I hope you will have an enjoyable stay at ' ||
        E'{{listing_title}}!\n\n' ||
        E'Thanks,\n{{host_name}}';

    -- Keep in sync with MessageTemplate.defaultContentFor(checkIn, bn).
    v_default_bn := E'হ্যালো {{guest_name}},\n\n' ||
        E'{{listing_title}}-এ বুকিং করার জন্য আবারও ধন্যবাদ!\n\n' ||
        '{{check_in_date}} তারিখে সহজ ও ঝামেলাহীন চেক-ইনের জন্য নিচের ' ||
        E'তথ্যগুলো দেখুন।\n\n' ||
        E'ঠিকানা:\n{{listing_address}}\n\n' ||
        'জায়গাটি সহজে খুঁজে পেতে আমি নিচে সঠিক ম্যাপ লোকেশন শেয়ার করছি। ' ||
        'অনুগ্রহ করে আপনার সম্ভাব্য আগমনের সময় জানাবেন, এবং থাকার আগে ' ||
        E'কোনো প্রশ্ন থাকলে নির্দ্বিধায় যোগাযোগ করবেন।\n\n' ||
        E'আশা করি {{listing_title}}-এ আপনার থাকা আনন্দদায়ক হবে!\n\n' ||
        E'ধন্যবাদ,\n{{host_name}}';

    SELECT t.content, t.enabled, t.lead_days
    INTO v_content, v_enabled, v_lead_days
    FROM public.message_templates t
    WHERE t.host_id = rec.host_id AND t.trigger = 'check_in';

    IF NOT FOUND THEN
        v_enabled := TRUE;
        v_lead_days := 2;
        v_content := CASE WHEN v_lang = 'bn' THEN v_default_bn ELSE v_default_en END;
    ELSIF v_content = v_default_en OR v_content = v_default_bn THEN
        v_content := CASE WHEN v_lang = 'bn' THEN v_default_bn ELSE v_default_en END;
    END IF;

    IF NOT v_enabled THEN RETURN; END IF;
    -- Not yet within the near-check-in window — the cron will pick it up later.
    IF rec.starts_at > NOW() + make_interval(days => v_lead_days) THEN RETURN; END IF;

    v_conv_id := public.get_or_create_conversation(
        rec.tenant_id, rec.host_id, rec.booking_id, rec.listing_id);

    v_nights := GREATEST(1, ((rec.ends_at at time zone 'Asia/Dhaka')::date - (rec.starts_at at time zone 'Asia/Dhaka')::date));
    IF rec.pricing_unit::text = 'hour' THEN
        v_units := GREATEST(1, FLOOR(EXTRACT(EPOCH FROM (rec.ends_at - rec.starts_at)) / 3600)::int);
        v_duration := v_units || CASE WHEN v_lang = 'bn' THEN ' ঘণ্টা'
                                      WHEN v_units = 1 THEN ' hour' ELSE ' hours' END;
    ELSIF rec.pricing_unit::text = 'month' THEN
        v_units := GREATEST(1, ROUND(((rec.ends_at at time zone 'Asia/Dhaka')::date - (rec.starts_at at time zone 'Asia/Dhaka')::date) / 30.0)::int);
        v_duration := v_units || CASE WHEN v_lang = 'bn' THEN ' মাস'
                                      WHEN v_units = 1 THEN ' month' ELSE ' months' END;
    ELSE
        v_duration := v_nights || CASE WHEN v_lang = 'bn' THEN ' রাত'
                                       WHEN v_nights = 1 THEN ' night' ELSE ' nights' END;
    END IF;

    v_address := NULLIF(TRIM(BOTH ', ' FROM
        COALESCE(rec.listing_address, '') ||
        CASE WHEN rec.listing_city IS NOT NULL
                  AND (rec.listing_address IS NULL
                       OR rec.listing_address NOT ILIKE '%' || rec.listing_city || '%')
             THEN ', ' || rec.listing_city ELSE '' END), '');

    v_ci_date := to_char(rec.starts_at at time zone 'Asia/Dhaka', 'FMDay, FMMonth FMDD');
    v_co_date := to_char(rec.ends_at at time zone 'Asia/Dhaka', 'FMDay, FMMonth FMDD');
    IF v_lang = 'bn' THEN
        v_ci_date := public._localize_date_bn(v_ci_date);
        v_co_date := public._localize_date_bn(v_co_date);
    END IF;

    v_rendered := v_content;
    v_rendered := replace(v_rendered, '{{guest_name}}',
        COALESCE(rec.tenant_name, CASE WHEN v_lang = 'bn' THEN 'অতিথি' ELSE 'Guest' END));
    v_rendered := replace(v_rendered, '{{listing_title}}',
        COALESCE(rec.listing_title, CASE WHEN v_lang = 'bn' THEN 'আপনার থাকার জায়গা' ELSE 'your stay' END));
    v_rendered := replace(v_rendered, '{{listing_address}}',
        COALESCE(v_address, rec.listing_title, CASE WHEN v_lang = 'bn' THEN 'লিস্টিং' ELSE 'the listing' END));
    v_rendered := replace(v_rendered, '{{check_in_date}}', v_ci_date);
    v_rendered := replace(v_rendered, '{{check_out_date}}', v_co_date);
    v_rendered := replace(v_rendered, '{{duration}}', v_duration);
    v_rendered := replace(v_rendered, '{{nights}}', v_nights::text);
    v_rendered := replace(v_rendered, '{{guest_count}}', COALESCE(rec.guest_count, 1)::text);
    v_rendered := replace(v_rendered, '{{host_name}}', rec.host_name);
    v_rendered := replace(v_rendered, '{{directions}}', COALESCE(rec.ci_directions, ''));
    v_rendered := replace(v_rendered, '{{wifi_name}}', COALESCE(rec.ci_wifi_name, ''));
    v_rendered := replace(v_rendered, '{{wifi_password}}', COALESCE(rec.ci_wifi_password, ''));
    v_rendered := replace(v_rendered, '{{access_code}}', COALESCE(rec.ci_access_code, ''));

    INSERT INTO public.messages (conversation_id, sender_id, content, content_type)
    VALUES (v_conv_id, rec.host_id, v_rendered, 'text');

    v_access := '';
    IF NULLIF(TRIM(rec.ci_directions), '') IS NOT NULL THEN
        v_access := v_access ||
            CASE WHEN v_lang = 'bn' THEN E'\n\n📍 দিকনির্দেশনা:\n' ELSE E'\n\n📍 Directions:\n' END
            || TRIM(rec.ci_directions);
    END IF;
    IF NULLIF(TRIM(rec.ci_wifi_name), '') IS NOT NULL THEN
        v_access := v_access ||
            CASE WHEN v_lang = 'bn' THEN E'\n\n📶 ওয়াই-ফাই: ' ELSE E'\n\n📶 Wi-Fi: ' END
            || TRIM(rec.ci_wifi_name)
            || CASE WHEN NULLIF(TRIM(rec.ci_wifi_password), '') IS NOT NULL
                    THEN (CASE WHEN v_lang = 'bn' THEN E'\nপাসওয়ার্ড: ' ELSE E'\nPassword: ' END)
                         || TRIM(rec.ci_wifi_password) ELSE '' END;
    END IF;
    IF NULLIF(TRIM(rec.ci_access_code), '') IS NOT NULL THEN
        v_access := v_access ||
            CASE WHEN v_lang = 'bn' THEN E'\n\n🔑 দরজা / অ্যাক্সেস কোড: ' ELSE E'\n\n🔑 Door / access code: ' END
            || TRIM(rec.ci_access_code);
    END IF;

    IF v_access <> '' THEN
        INSERT INTO public.messages (conversation_id, sender_id, content, content_type)
        VALUES (v_conv_id, rec.host_id,
                (CASE WHEN v_lang = 'bn' THEN 'চেক-ইন বিবরণ' ELSE 'Check-in details' END)
                || v_access, 'text');
    END IF;

    INSERT INTO public.scheduled_message_sends (booking_id, trigger)
    VALUES (rec.booking_id, 'check_in');
END;
$function$;

CREATE OR REPLACE FUNCTION public.send_push_on_notification_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_auth text;
begin
  -- 129: a recipient whose preferences say in-app only still gets the row.
  if coalesce(new.data ->> 'suppress_push', '') = 'true' then
    return new;
  end if;

  select value into v_auth from public.app_secrets where key = 'edge_invoke_key';

  -- Loud, because the silent version of this cost the app every push it should
  -- have sent. A warning cannot fail the insert — the notification must still
  -- reach the in-app inbox whatever the delivery layer is doing.
  if coalesce(v_auth, '') = '' then
    raise warning 'push not sent: app_secrets.edge_invoke_key is missing or empty';
    return new;
  end if;

  perform net.http_post(
    url := 'https://bojkmonskqlhuakxhzcb.supabase.co/functions/v1/send-push-notification',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_auth,
      'x-push-secret',
      coalesce((select value from public.app_secrets where key = 'push_secret'), '')
    ),
    body := jsonb_build_object(
      'user_id', NEW.user_id,
      'title', NEW.title,
      'body', NEW.body,
      'data', coalesce(NEW.data, '{}'::jsonb) || jsonb_build_object(
        'type', NEW.type::text,
        'notification_id', NEW.id::text,
        'action_url', coalesce(NEW.action_url, '')
      )
    )
  );
  return NEW;
exception
  when others then
    raise warning 'Push notification error: %', SQLERRM;
    return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_review_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    reminder_count integer := 0;
    booking_record record;
    listing_record record;
    v_day text;
begin
    for booking_record in
        select b.*, case when (b.completed_at at time zone 'Asia/Dhaka')::date
                              = ((now() - interval '3 days') at time zone 'Asia/Dhaka')::date
                         then '3' else '7' end as which
        from public.bookings b
        where b.booking_status = 'completed'
          and b.completed_at is not null
          and (b.completed_at at time zone 'Asia/Dhaka')::date in (
                ((now() - interval '3 days') at time zone 'Asia/Dhaka')::date,
                ((now() - interval '7 days') at time zone 'Asia/Dhaka')::date)
    loop
        v_day := booking_record.which;

        select l.title, l.owner_id into listing_record
        from public.listings l
        where l.id = booking_record.listing_id;

        if booking_record.tenant_id is not null
           and not exists (select 1 from public.reviews r
                            where r.booking_id = booking_record.id
                              and r.review_type = 'guest_to_host')
           and not exists (select 1 from public.notifications n
                            where n.user_id = booking_record.tenant_id
                              and n.type = 'review_reminder'
                              and n.data ->> 'booking_id' = booking_record.id::text
                              and n.data ->> 'day' = v_day) then
            insert into public.notifications (user_id, type, title, body, priority, action_url, data)
            values (
                booking_record.tenant_id, 'review_reminder',
                'Don''t Forget to Review!',
                format('Share your experience at %s. Your review helps other travelers!',
                    coalesce(listing_record.title, 'your recent stay')),
                'normal', '/review/' || booking_record.id || '/guest',
                jsonb_build_object('booking_id', booking_record.id,
                                   'listing_id', booking_record.listing_id,
                                   'reminder_type', 'guest', 'day', v_day)
            );
            reminder_count := reminder_count + 1;
        end if;

        if listing_record.owner_id is not null
           and not exists (select 1 from public.reviews r
                            where r.booking_id = booking_record.id
                              and r.review_type = 'host_to_guest')
           and not exists (select 1 from public.notifications n
                            where n.user_id = listing_record.owner_id
                              and n.type = 'review_reminder'
                              and n.data ->> 'booking_id' = booking_record.id::text
                              and n.data ->> 'day' = v_day) then
            insert into public.notifications (user_id, type, title, body, priority, action_url, data)
            values (
                listing_record.owner_id, 'review_reminder',
                'Review Your Guest',
                format('Don''t forget to review your guest from %s. Your feedback helps the community!',
                    coalesce(listing_record.title, 'your property')),
                'normal', '/review/' || booking_record.id || '/host',
                jsonb_build_object('booking_id', booking_record.id,
                                   'listing_id', booking_record.listing_id,
                                   'reminder_type', 'host', 'day', v_day)
            );
            reminder_count := reminder_count + 1;
        end if;
    end loop;

    if reminder_count > 0 then
        raise notice 'Sent % review reminders', reminder_count;
    end if;
    return reminder_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_address_verification(p_user_id uuid, p_status verification_status, p_visit_notes text DEFAULT NULL::text, p_rejection_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin uuid := auth.uid();
begin
  if not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if p_status not in ('pending', 'verified', 'rejected') then
    raise exception 'status must be pending, verified or rejected'
      using errcode = '22023';
  end if;
  if p_status = 'rejected'
     and coalesce(btrim(p_rejection_reason), '') = '' then
    raise exception 'a rejection reason is required' using errcode = '22023';
  end if;

  update public.profiles
     set address_verification_status = p_status,
         -- Stamped only on approval; cleared otherwise, so verified_at can
         -- never outlive the verdict it belongs to.
         address_verified_at = case when p_status = 'verified' then now() end,
         address_verified_by = case when p_status = 'verified' then v_admin end,
         address_visit_notes = coalesce(btrim(p_visit_notes), address_visit_notes),
         address_rejection_reason =
           case when p_status = 'rejected' then btrim(p_rejection_reason) end
   where id = p_user_id;

  if not found then
    raise exception 'no such profile' using errcode = 'P0002';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_booking_paid_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.payment_status = 'paid' AND NEW.paid_at IS NULL THEN
        NEW.paid_at := now();
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_booking_payment_method(p_booking_id uuid, p_method text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_tenant uuid;
  v_pay_status text;
  v_status text;
  v_cash_enabled boolean;
begin
  if v_uid is null then raise exception 'Not authenticated'; end if;

  if p_method not in ('online', 'cash') then
    raise exception 'Invalid payment method: %', p_method using errcode = '22023';
  end if;

  select tenant_id, payment_status, booking_status
    into v_tenant, v_pay_status, v_status
    from public.bookings where id = p_booking_id;
  if v_tenant is null then raise exception 'Booking not found'; end if;

  -- Only the guest who owns the booking may choose its payment method.
  if v_tenant <> v_uid then
    raise exception 'Only the guest can choose the payment method'
      using errcode = '42501';
  end if;

  -- Nothing to choose once it's already settled.
  if v_pay_status = 'paid' then
    raise exception 'This booking is already paid' using errcode = '42501';
  end if;

  -- Payment is only arranged after the host accepts and before completion.
  if v_status not in ('confirmed', 'active') then
    raise exception 'Payment can only be arranged after the host accepts'
      using errcode = '42501';
  end if;

  -- 'cash' requires the admin toggle. Defence in depth: the client hides the
  -- option, but never trust the client.
  if p_method = 'cash' then
    select lower(coalesce(value, '')) = 'true' into v_cash_enabled
      from public.app_settings where key = 'cash_payment_enabled';
    if not coalesce(v_cash_enabled, false) then
      raise exception 'Cash payment is not available' using errcode = '42501';
    end if;
  end if;

  -- 132: this is a settlement-column write from a real auth.uid(); tell the
  -- bookings trigger it is ours.
  perform set_config('musafir.settlement_write', '1', true);
  update public.bookings set payment_method = p_method where id = p_booking_id;
  perform set_config('musafir.settlement_write', '0', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_booking_rejected_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.booking_status = 'rejected' AND NEW.rejected_at IS NULL THEN
        NEW.rejected_at := now();
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_default_payout_method(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.payout_methods
     where id = p_id and user_id = v_uid
       and retired_at is null and status <> 'rejected'
  ) then
    raise exception 'no such payout method' using errcode = '22023';
  end if;

  -- Clear first: the partial unique index permits exactly one live default,
  -- so setting before clearing would collide.
  update public.payout_methods
     set is_default = false
   where user_id = v_uid and is_default and retired_at is null and id <> p_id;

  update public.payout_methods set is_default = true where id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_disbursement_status(p_id uuid, p_status text, p_reference text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if p_status not in ('pending', 'sent', 'failed') then
    raise exception 'status must be pending, sent or failed' using errcode = '22023';
  end if;
  if p_status = 'failed' and coalesce(btrim(p_failure_reason), '') = '' then
    raise exception 'a failure reason is required' using errcode = '22023';
  end if;

  update public.disbursements
     set status         = p_status,
         reference      = coalesce(nullif(btrim(p_reference), ''), reference),
         failure_reason = case when p_status = 'failed'
                               then btrim(p_failure_reason) end,
         sent_at        = case when p_status = 'sent'
                               then coalesce(sent_at, now()) end
   where id = p_id;

  if not found then
    raise exception 'no such disbursement' using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_landmark_geog()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.geog := ST_SetSRID(ST_MakePoint(new.longitude, new.latitude), 4326)::geography;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_listing_geog()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.latitude is not null and new.longitude is not null then
    new.geog := ST_SetSRID(ST_MakePoint(new.longitude, new.latitude), 4326)::geography;
  else
    new.geog := null;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_listing_host_available()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  SELECT is_available INTO NEW.host_available
  FROM public.profiles WHERE id = NEW.owner_id;
  IF NEW.host_available IS NULL THEN
    NEW.host_available := TRUE;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_payout_method_verification(p_id uuid, p_status verification_status, p_rejection_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin uuid := auth.uid();
begin
  if not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if p_status not in ('pending', 'verified', 'rejected') then
    raise exception 'status must be pending, verified or rejected'
      using errcode = '22023';
  end if;
  if p_status = 'rejected' and coalesce(btrim(p_rejection_reason), '') = '' then
    raise exception 'a rejection reason is required' using errcode = '22023';
  end if;

  update public.payout_methods
     set status           = p_status,
         verified_at      = case when p_status = 'verified' then now() end,
         verified_by      = case when p_status = 'verified' then v_admin end,
         rejection_reason = case when p_status = 'rejected'
                                 then btrim(p_rejection_reason) end,
         -- A rejected method must not stay the target of the next payout.
         is_default       = case when p_status = 'rejected' then false
                                 else is_default end
   where id = p_id and retired_at is null;

  if not found then
    raise exception 'no such payout method' using errcode = '22023';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_verification_pending()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (select 1 from public.owner_documents
              where user_id = new.user_id and document_type = 'nid_front')
     and exists (select 1 from public.owner_documents
                  where user_id = new.user_id and document_type = 'nid_back') then
    update public.profiles
       set verification_status = 'pending'
     where id = new.user_id
       and verification_status in ('none', 'rejected');
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sms_bulk_max_recipients()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v text;
begin
  select value into v from public.app_settings where key = 'sms_bulk_max_recipients';
  if v is null or v !~ '^[0-9]{1,6}$' then
    return 500;
  end if;
  return least(v::integer, 100000);
end;
$function$;

CREATE OR REPLACE FUNCTION public.snap_coordinate(p_degrees numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select round(p_degrees / 0.001) * 0.001;
$function$;

CREATE OR REPLACE FUNCTION public.start_face_verification(p_method text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.face_verification_attempts; sequence text[];
begin
  if auth.uid() is null then raise exception 'Sign in first' using errcode='42501'; end if;
  if not coalesce((select value='true' from public.app_settings where key='face_review_enabled'),false) then
    raise exception 'Face review is not available yet. Please try later'; end if;
  if p_method is null or p_method not in ('guided','manual') then raise exception 'Invalid capture method'; end if;
  -- Serialize starts/submission/review for a user, including simultaneous devices.
  perform 1 from public.profiles where id=auth.uid() and suspended_at is null for update;
  if not found then raise exception 'Account unavailable' using errcode='42501'; end if;
  if (select status='approved' from public.face_verification_attempts where user_id=auth.uid() order by created_at desc,id desc limit 1) then raise exception 'Face already approved'; end if;
  if exists(select 1 from public.face_verification_attempts where user_id=auth.uid() and status='pending') then
    raise exception 'Your submission is already awaiting review'; end if;
  if (select count(*) from public.face_verification_attempts where user_id=auth.uid()
      and created_at > now()-interval '24 hours') >= 5 then
    raise exception 'Daily attempt limit reached. Please try tomorrow'; end if;
  update public.face_verification_attempts set status='superseded' where user_id=auth.uid() and status='draft';
  sequence := case when random() < 0.5 then array['blink','left','right'] else array['blink','right','left'] end;
  if random() < 0.5 then sequence := array[sequence[2],sequence[1],sequence[3]]; end if;
  if p_method='manual' then sequence := '{}'::text[]; end if;
  insert into public.face_verification_attempts(user_id,method,actions)
    values(auth.uid(),p_method,sequence) returning * into a;
  return to_jsonb(a);
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_address_verification(p_address_line text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if coalesce(btrim(p_address_line), '') = '' then
    raise exception 'a full address is required' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.profiles
     where id = v_uid and address_proof_path is not null
  ) then
    raise exception 'upload a proof-of-address document first'
      using errcode = '22023';
  end if;

  update public.profiles
     set address_line = btrim(p_address_line),
         address_verification_status = 'pending',
         address_submitted_at = now()
   where id = v_uid;
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_face_verification(p_attempt_id uuid, p_nonce uuid, p_clip_extension text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.face_verification_attempts; clip text; selfie text;
begin
  if auth.uid() is null then raise exception 'Sign in first' using errcode='42501'; end if;
  perform 1 from public.profiles where id=auth.uid() and suspended_at is null for update;
  if not found then raise exception 'Account unavailable' using errcode='42501'; end if;
  select * into a from public.face_verification_attempts where id=p_attempt_id and user_id=auth.uid() for update;
  if not found or a.nonce is distinct from p_nonce then raise exception 'Invalid attempt' using errcode='42501'; end if;
  if a.status='pending' then return; end if;
  if a.status<>'draft' or a.expires_at<=now() then raise exception 'Attempt expired. Start again'; end if;
  selfie := a.user_id::text||'/'||a.id::text||'/selfie.jpg';
  if not exists(select 1 from storage.objects where bucket_id='face-evidence' and name=selfie
    and (metadata->>'size')::bigint between 100 and 524288 and metadata->>'mimetype'='image/jpeg') then
    raise exception 'Selfie upload is missing or invalid'; end if;
  if a.method='guided' then
    if p_clip_extension is null or p_clip_extension not in ('webm','mp4') then raise exception 'Invalid video format'; end if;
    clip := a.user_id::text||'/'||a.id::text||'/clip.'||p_clip_extension;
    if not exists(select 1 from storage.objects where bucket_id='face-evidence' and name=clip
      and (metadata->>'size')::bigint between 100 and 8388608
      and metadata->>'mimetype'='video/'||p_clip_extension) then raise exception 'Video upload is missing or invalid'; end if;
  end if;
  -- No client liveness boolean is trusted. The admin must review the media.
  update public.face_verification_attempts set status='pending', submitted_at=now(),
    clip_path=clip, selfie_path=selfie where id=a.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_identity_document(p_document_type text, p_front_path text, p_back_path text DEFAULT NULL::text, p_document_number text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid(); p public.profiles; path text; mime text;
begin
  if uid is null then raise exception 'Sign in first' using errcode='42501'; end if;
  select * into p from public.profiles where id=uid and suspended_at is null for update;
  if not found then raise exception 'Account unavailable' using errcode='42501'; end if;
  if p_document_type is null or p_document_type not in ('nid','passport','driving_license','student_id','office_id') then raise exception 'Unsupported document type'; end if;
  if p_document_number is not null and (length(btrim(p_document_number))=0 or length(p_document_number)>100) then raise exception 'Invalid document number'; end if;
  -- Lost-response retries may reuse the same paths without replacing evidence.
  if p.verification_status='pending' and p.id_document_type=p_document_type and p.nid is not distinct from nullif(btrim(p_document_number),'') and exists(select 1 from public.owner_documents where user_id=uid and document_type='nid_front' and file_path=p_front_path)
    and ((p_back_path is null and not exists(select 1 from public.owner_documents where user_id=uid and document_type='nid_back')) or exists(select 1 from public.owner_documents where user_id=uid and document_type='nid_back' and file_path=p_back_path)) then return; end if;
  if p.verification_status in ('pending','verified') then raise exception 'Your document is already submitted. Refresh status.'; end if;
  if p_front_path is null or (p_document_type='nid' and p_back_path is null) or p_front_path=p_back_path then raise exception 'Front image is required; NID also requires the back'; end if;
  foreach path in array array[p_front_path,p_back_path] loop
    if path is null then continue; end if;
    if path not like uid::text||'/nid/%' then raise exception 'Invalid document owner' using errcode='42501'; end if;
    select metadata->>'mimetype' into mime from storage.objects where bucket_id='documents' and name=path
      and (metadata->>'size')::bigint between 100 and 5242880;
    if not found or mime not in ('image/jpeg','image/png') or mime is null then raise exception 'Upload a JPG or PNG of each side, under 5 MB'; end if;
  end loop;
  -- A replacement with a single-sided document must not inherit an old back.
  -- Stored historical image bytes are preserved; only the current slot changes.
  if p_back_path is null then delete from public.owner_documents where user_id=uid and document_type='nid_back'; end if;
  insert into public.owner_documents(user_id,document_type,file_path,mime_type,uploaded_at,verified_at,verified_by,rejection_reason)
    select uid,sides.slot,sides.file_path,(select metadata->>'mimetype' from storage.objects where bucket_id='documents' and name=sides.file_path),now(),null,null,null
    from (values ('nid_front',p_front_path),('nid_back',p_back_path)) sides(slot,file_path) where sides.file_path is not null
    on conflict(user_id,document_type) do update set file_path=excluded.file_path,mime_type=excluded.mime_type,
      uploaded_at=excluded.uploaded_at,verified_at=null,verified_by=null,rejection_reason=null;
  update public.profiles set verification_status='pending',nid_verified=false,id_document_type=p_document_type,nid=nullif(btrim(p_document_number),'') where id=uid;
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_nid_verification(p_front_path text, p_back_path text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.submit_identity_document('nid',p_front_path,p_back_path,null);
$function$;

CREATE OR REPLACE FUNCTION public.sweep_sms_campaigns()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_url    text;
  v_secret text;
  v_auth   text;
  v_row    record;
  v_count  integer := 0;
begin
  select value into v_url    from public.app_secrets where key = 'sms_worker_url';
  select value into v_secret from public.app_secrets where key = 'sms_worker_secret';
  select value into v_auth   from public.app_secrets where key = 'edge_invoke_key';

  if coalesce(v_url,'') = '' or coalesce(v_secret,'') = '' or coalesce(v_auth,'') = '' then
    return 0;
  end if;

  for v_row in
    select c.id
      from public.sms_campaigns c
     where c.status in ('queued', 'sending')
       and exists (select 1 from public.sms_recipients r
                    where r.campaign_id = c.id and r.status = 'pending')
  loop
    perform net.http_post(
      url := v_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_auth,
        'x-sms-worker-secret', v_secret
      ),
      body := jsonb_build_object('campaignId', v_row.id)
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
exception when others then
  raise warning 'sweep_sms_campaigns failed: %', sqlerrm;
  return 0;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_listings_host_available()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NEW.is_available IS DISTINCT FROM OLD.is_available THEN
    UPDATE public.listings
    SET host_available = NEW.is_available
    WHERE owner_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.touch_device(p_device_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_revoked timestamptz;
  v_found boolean;
begin
  if v_user is null then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  if public.fn_is_suspended(v_user) then
    return true;
  end if;

  update public.user_devices
     set last_seen_at = now(),
         last_ip = coalesce(inet_client_addr(), last_ip)
   where user_id = v_user
     and device_id = p_device_id
     and revoked_at is null
  returning revoked_at into v_revoked;

  get diagnostics v_found = row_count;

  -- An unknown device id is not "revoked": it is a device that has never
  -- registered, or one whose row was cascaded away with a deleted account.
  -- Answering true would sign out a perfectly good session.
  if not v_found then
    return exists (
      select 1 from public.user_devices
       where user_id = v_user
         and device_id = p_device_id
         and revoked_at is not null
    );
  end if;

  return false;
end;
$function$;

