CREATE OR REPLACE FUNCTION public.unblock_listing_dates(p_block_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'You must be signed in' using errcode = '42501';
  end if;

  delete from public.listing_availability_blocks blk
  using public.listings l
  where blk.id = p_block_id
    and l.id = blk.listing_id
    and (l.owner_id = v_uid or public.is_admin());

  if not found then
    raise exception 'Block not found' using errcode = 'P0002';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_conversation_last_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.conversations
  SET
    last_message_id = NEW.id,
    last_message_text = CASE
      WHEN NEW.content_type = 'text' THEN LEFT(NEW.content, 100)
      WHEN NEW.content_type = 'booking_card' THEN 'Booking details'
      WHEN NEW.content_type = 'image' THEN 'Sent an image'
      WHEN NEW.content_type = 'location' THEN 'Shared a location'
      WHEN NEW.content_type = 'file' THEN 'Sent a file'
      ELSE LEFT(NEW.content, 100)
    END,
    last_message_at = NEW.created_at,
    last_message_sender_id = NEW.sender_id,
    last_message_preview = LEFT(NEW.content, 100),
    updated_at = NOW()
  WHERE id = NEW.conversation_id;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_fcm_token_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_listing_location()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.latitude IS NOT NULL AND NEW.longitude IS NOT NULL THEN
        NEW.location = ST_SetSRID(ST_MakePoint(NEW.longitude, NEW.latitude), 4326)::geography;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_notifications_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
  BEGIN
      NEW.updated_at = NOW();
      RETURN NEW;
  END;
  $function$;

CREATE OR REPLACE FUNCTION public.update_profile_verification_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Check if both NID documents are verified
  IF NEW.verified_at IS NOT NULL THEN
    -- Check if both front and back are now verified
    IF EXISTS (
      SELECT 1 FROM public.owner_documents
      WHERE user_id = NEW.user_id
        AND document_type = 'nid_front'
        AND verified_at IS NOT NULL
    ) AND EXISTS (
      SELECT 1 FROM public.owner_documents
      WHERE user_id = NEW.user_id
        AND document_type = 'nid_back'
        AND verified_at IS NOT NULL
    ) THEN
      UPDATE public.profiles
      SET verification_status = 'verified'
      WHERE id = NEW.user_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_reviews_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = timezone('utc', now());
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_fcm_token(p_user_id uuid, p_token text, p_device_type text DEFAULT 'android'::text, p_device_name text DEFAULT NULL::text, p_device_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  -- Unchanged from the live definition: 012's repo file shows no guard, but
  -- the deployed body has had one since a later migration, and dropping it
  -- here would reopen push-notification hijacking for every account.
  if auth.uid() is null or auth.uid() <> p_user_id then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  insert into public.fcm_tokens (user_id, token, device_type, device_name, device_id)
  values (p_user_id, p_token, p_device_type, p_device_name, p_device_id)
  on conflict (user_id, token)
  do update set
    is_active = true,
    last_used_at = now(),
    updated_at = now(),
    device_type = coalesce(excluded.device_type, fcm_tokens.device_type),
    device_name = coalesce(excluded.device_name, fcm_tokens.device_name),
    device_id = coalesce(excluded.device_id, fcm_tokens.device_id)
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.validate_coupon(p_code text, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c public.coupons%rowtype;
  v_uid uuid := auth.uid();
  v_user_uses int;
  v_discount numeric;
begin
  if v_uid is null then
    return jsonb_build_object('valid', false, 'message', 'Please sign in to use a coupon');
  end if;

  select * into c from public.coupons where code = upper(trim(p_code));
  if not found then
    return jsonb_build_object('valid', false, 'message', 'Coupon not found');
  end if;
  if not c.is_active then
    return jsonb_build_object('valid', false, 'message', 'This coupon is no longer active');
  end if;
  if c.starts_at is not null and now() < c.starts_at then
    return jsonb_build_object('valid', false, 'message', 'This coupon is not active yet');
  end if;
  if c.expires_at is not null and now() > c.expires_at then
    return jsonb_build_object('valid', false, 'message', 'This coupon has expired');
  end if;
  if c.usage_limit is not null and c.used_count >= c.usage_limit then
    return jsonb_build_object('valid', false, 'message', 'This coupon has reached its usage limit');
  end if;
  if p_amount < c.min_booking_amount then
    return jsonb_build_object('valid', false, 'message',
      'Minimum booking amount for this coupon is ' || c.min_booking_amount::text);
  end if;
  if c.per_user_limit is not null then
    select count(*) into v_user_uses from public.coupon_redemptions
      where coupon_id = c.id and user_id = v_uid;
    if v_user_uses >= c.per_user_limit then
      return jsonb_build_object('valid', false, 'message', 'You have already used this coupon');
    end if;
  end if;

  if c.discount_type = 'percentage' then
    v_discount := round(p_amount * c.discount_value / 100.0, 2);
    if c.max_discount_amount is not null and v_discount > c.max_discount_amount then
      v_discount := c.max_discount_amount;
    end if;
  else
    v_discount := c.discount_value;
  end if;
  if v_discount > p_amount then v_discount := p_amount; end if;

  return jsonb_build_object(
    'valid', true,
    'coupon_id', c.id,
    'code', c.code,
    'discount_type', c.discount_type,
    'discount_value', c.discount_value,
    'discount_amount', v_discount,
    'final_amount', p_amount - v_discount,
    'message', 'Coupon applied'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.verification_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n jsonb; f jsonb; state text; required boolean:=public.face_review_required();
begin
  n:=public.nid_verification_status(); f:=public.face_verification_status();
  if not required then
    state:=case when n->>'status'='verified' then 'verified'
      when n->>'status'='pending' then 'pending' else 'none' end;
  else
    state:=case when n->>'status'='verified' and f->>'status'='verified' then 'verified'
      when n->>'status' in ('pending','verified') and f->>'status' in ('pending','verified') then 'pending'
      else 'none' end;
  end if;
  -- face_enabled is kept for builds that predate face_required.
  return jsonb_build_object('status',state,'nid_status',n->>'status','face_status',f->>'status',
    'face_enabled',required,'face_required',required);
end;
$function$;

-- ===== views =====
create or replace view public.financial_audit with (security_invoker=true) as
 SELECT id,
    occurred_at,
    table_name,
    record_id,
    action,
    actor_id,
    actor_role,
    source,
    amount,
    currency,
    changed_cols
   FROM audit_log
  WHERE category = 'financial'::text;
create or replace view public.guest_ratings with (security_invoker=on) as
 SELECT reviewee_id AS guest_id,
    count(*) AS review_count,
    round(avg(overall_rating), 1) AS average_rating
   FROM reviews
  WHERE review_type = 'host_to_guest'::review_type AND is_revealed = true
  GROUP BY reviewee_id;
create or replace view public.host_balances with (security_invoker=true) as
 SELECT e.host_id,
    p.full_name,
    p.mobile,
    p.avatar_url,
    sum(e.amount) AS balance,
    sum(e.commission_amount) FILTER (WHERE e.entry_type = ANY (ARRAY['booking_online'::text, 'booking_cash'::text, 'booking_refund_reversal'::text])) AS commission_earned,
    count(*) AS entry_count,
    max(e.created_at) AS last_entry_at
   FROM host_ledger_entries e
     JOIN profiles p ON p.id = e.host_id
  GROUP BY e.host_id, p.full_name, p.mobile, p.avatar_url;
create or replace view public.host_payouts_due with (security_invoker=true) as
 SELECT b.id AS booking_id,
    e.host_id,
    p.full_name AS host_name,
    b.listing_title,
    b.total_price,
    e.amount AS suggested_amount,
    b.ends_at,
    b.booking_status,
    b.payment_status,
    b.paid_at,
    ( SELECT pm.id
           FROM payout_methods pm
          WHERE pm.user_id = e.host_id AND pm.retired_at IS NULL AND pm.status = 'verified'::verification_status
          ORDER BY pm.is_default DESC, pm.created_at
         LIMIT 1) AS default_payout_method_id
   FROM bookings b
     JOIN host_ledger_entries e ON e.booking_id = b.id AND e.entry_type = 'booking_online'::text
     JOIN profiles p ON p.id = e.host_id
  WHERE (b.booking_status <> ALL (ARRAY['cancelled'::booking_status, 'rejected'::booking_status, 'pending'::booking_status])) AND NOT (EXISTS ( SELECT 1
           FROM host_ledger_entries r
          WHERE r.booking_id = b.id AND r.entry_type = 'booking_refund_reversal'::text)) AND NOT (EXISTS ( SELECT 1
           FROM disbursements d
          WHERE d.booking_id = b.id AND d.kind = 'host_payout'::text AND d.status <> 'failed'::text));
create or replace view public.listing_ratings with (security_invoker=on) as
 SELECT listing_id,
    count(*) AS review_count,
    round(avg(overall_rating), 1) AS average_rating,
    round(avg(cleanliness_rating), 1) AS average_cleanliness,
    round(avg(accuracy_rating), 1) AS average_accuracy,
    round(avg(communication_rating), 1) AS average_communication,
    round(avg(location_rating), 1) AS average_location,
    round(avg(value_rating), 1) AS average_value
   FROM reviews
  WHERE review_type = 'guest_to_host'::review_type AND listing_id IS NOT NULL
  GROUP BY listing_id;
create or replace view public.public_profiles as
 SELECT id,
    full_name,
    avatar_url,
    role,
    is_host,
    host_since,
    bio,
    response_rate,
    response_time,
    is_available,
    message_language,
    created_at,
    COALESCE(phone_verified, false) AS phone_verified,
    verification_status = 'verified'::verification_status AS identity_verified,
    address_verification_status = 'verified'::verification_status AS address_verified
   FROM profiles;

