-- ===== triggers =====
do $t$ begin if not exists (select 1 from pg_trigger x join pg_class c on c.oid=x.tgrelid join pg_namespace n on n.oid=c.relnamespace where x.tgname='on_auth_user_created' and c.relname='users' and n.nspname='auth') then execute $q$ CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user() $q$; end if; end $t$;
